text_nat:
TIER_DISCOUNTS = {
    "bronze": 0.05,
    "silver": 0.10,
    "gold": 0.15,
    "platinum": 0.20,
}

SEASONAL_PROMO_THRESHOLD = 100.0
SEASONAL_PROMO_AMOUNT = 15.0


def normalize_tier_name(
    customer_loyalty_tier_name: str
) -> str:
    """Return the tier name in the canonical lowercase, trimmed form."""
    return customer_loyalty_tier_name.strip().lower()


def get_base_discount(
    customer_loyalty_tier_name: str
) -> float:
    """Return the loyalty discount fraction for the given tier name."""
    tier_key: str = normalize_tier_name(customer_loyalty_tier_name)
    return TIER_DISCOUNTS.get(tier_key, 0.0)


def apply_seasonal_promo(
    current_cart_total_amount: float,
    is_active_holiday_season: bool
) -> float:
    """Subtract the flat holiday promo when the season is on and the total exceeds $100."""
    if is_active_holiday_season and current_cart_total_amount > SEASONAL_PROMO_THRESHOLD:
        return current_cart_total_amount - SEASONAL_PROMO_AMOUNT
    return current_cart_total_amount


def calculate_final_checkout_price(
    current_cart_total_amount: float,
    customer_loyalty_tier_name: str,
    is_active_holiday_season: bool
) -> float:
    """Apply the loyalty discount first, then the seasonal promo, and round to cents."""
    if current_cart_total_amount < 0:
        raise ValueError("cart total cannot be negative")
    discount_fraction: float = get_base_discount(customer_loyalty_tier_name)
    discounted_total = current_cart_total_amount * (1.0 - discount_fraction)
    promoted_total = apply_seasonal_promo(discounted_total, is_active_holiday_season)
    return round(promoted_total, 2)


def format_money(
    amount: float
) -> str:
    """Render a dollar amount with a currency symbol and two decimals."""
    return f"${amount:,.2f}"


def describe_checkout(
    current_cart_total_amount: float,
    customer_loyalty_tier_name: str,
    is_active_holiday_season: bool
) -> str:
    """Build a one-line receipt summary for the given checkout inputs."""
    final_price: float = calculate_final_checkout_price(
        current_cart_total_amount,
        customer_loyalty_tier_name,
        is_active_holiday_season,
    )
    tier_label = normalize_tier_name(customer_loyalty_tier_name)
    discount_percent = get_base_discount(customer_loyalty_tier_name) * 100
    season_label: str = "holiday" if is_active_holiday_season else "regular season"
    return (
        f"Cart {format_money(current_cart_total_amount)} "
        f"[{tier_label}, {discount_percent:.0f}% off, {season_label}] "
        f"-> {format_money(final_price)}"
    )


if __name__ == "__main__":
    print(describe_checkout(150.00, "gold", True))
    print(calculate_final_checkout_price(150.00, "gold", True))

