def extract_ip_and_status(
    single_log_line_string: str,
    status_separator_character: str,
) -> tuple[str, int]:
    """Split a line such as '192.168.1.10 - 404' into its IP and status code."""
    if len(status_separator_character) != 1:
        raise ValueError("the status separator must be a single character")
    fields = single_log_line_string.split(status_separator_character)
    if len(fields) < 2:
        raise ValueError("log line %r lacks the separator %r" % (single_log_line_string, status_separator_character))
    status_text = fields[-1].strip()
    if not status_text.isdigit():
        raise ValueError("status %r is not numeric" % status_text)
    return fields[0].strip(), int(status_text)


def aggregate_error_counts(
    parsed_log_entries_list: list[tuple[str, int]],
    target_error_codes_list: list[int],
) -> dict[str, int]:
    """Count, per IP, how many of its entries carry one of the target status codes."""
    watched_codes = frozenset(target_error_codes_list)
    error_counts = {}
    for ip_address, status_code in parsed_log_entries_list:
        error_counts[ip_address] = error_counts.get(ip_address, 0) + (1 if status_code in watched_codes else 0)
    return error_counts


def generate_ip_blocklist(
    raw_log_lines_list: list[str],
    status_separator_character: str,
    target_error_codes_list: list[int],
    maximum_allowed_errors: int,
) -> list[str]:
    """Parse every line, aggregate the errors and return the offending IPs, sorted."""
    if maximum_allowed_errors < 0:
        raise ValueError("the error threshold cannot be negative")
    parsed_entries = [
        extract_ip_and_status(line, status_separator_character)
        for line in raw_log_lines_list
        if line.strip()
    ]
    error_counts = aggregate_error_counts(parsed_entries, target_error_codes_list)
    return sorted(
        ip_address
        for ip_address, count in error_counts.items()
        if count > maximum_allowed_errors
    )


def format_blocklist_report(
    blocked_ip_addresses: list[str],
    maximum_allowed_errors: int,
) -> str:
    """Render a short human-readable summary of the blocklist."""
    headline = "IPs with more than %d error(s): %d" % (maximum_allowed_errors, len(blocked_ip_addresses))
    if not blocked_ip_addresses:
        return headline
    body = "\n".join("  - " + ip_address for ip_address in blocked_ip_addresses)
    return headline + "\n" + body


def main() -> None:
    sample_log_lines = [
        "192.168.1.10 - 404",
        "192.168.1.10 - 500",
        "10.0.0.7 - 200",
        "192.168.1.10 - 404",
        "10.0.0.7 - 500",
    ]
    separator = "-"
    watched_codes = [404, 500]
    threshold = 1
    counts = aggregate_error_counts(
        [extract_ip_and_status(line, separator) for line in sample_log_lines],
        watched_codes,
    )
    for ip_address in sorted(counts):
        print("%-14s %d error(s)" % (ip_address, counts[ip_address]))
    blocklist = generate_ip_blocklist(sample_log_lines, separator, watched_codes, threshold)
    print(format_blocklist_report(blocklist, threshold))


if __name__ == "__main__":
    main()

