def calculate_scaling_factor(
    original_serving_size_count: float,
    desired_serving_size_count: float,
) -> float:
    """Return the ratio of desired servings to original servings."""
    if original_serving_size_count <= 0:
        raise ValueError("original serving size must be greater than zero")
    if desired_serving_size_count <= 0:
        raise ValueError("desired serving size must be greater than zero")
    return desired_serving_size_count / original_serving_size_count


def scale_single_ingredient(
    original_ingredient_amount: float,
    scaling_factor_multiplier: float,
) -> float:
    """Multiply one ingredient amount by the factor, rounded to 2 decimals."""
    if original_ingredient_amount < 0:
        raise ValueError("ingredient amounts cannot be negative")
    return round(original_ingredient_amount * scaling_factor_multiplier, 2)


def scale_entire_recipe(
    recipe_ingredients_dictionary: dict[str, float],
    original_serving_size_count: float,
    desired_serving_size_count: float,
) -> dict[str, float]:
    """Return a new ingredient dictionary scaled to the desired servings."""
    scaling_factor_multiplier = calculate_scaling_factor(
        original_serving_size_count,
        desired_serving_size_count,
    )
    scaled_recipe: dict[str, float] = {}
    for ingredient_name, original_amount in recipe_ingredients_dictionary.items():
        scaled_recipe[ingredient_name] = scale_single_ingredient(
            original_amount,
            scaling_factor_multiplier,
        )
    return scaled_recipe


def format_amount(
    ingredient_amount: float,
) -> str:
    """Render an amount without a trailing '.0' when it is a whole number."""
    if ingredient_amount == int(ingredient_amount):
        return str(int(ingredient_amount))
    return f"{ingredient_amount:.2f}"


def build_recipe_report(
    scaled_recipe: dict[str, float],
    desired_serving_size_count: float,
) -> str:
    """Build a printable ingredient list for the scaled recipe."""
    header = f"Ingredients for {format_amount(desired_serving_size_count)} servings:"
    lines = [header]
    for ingredient_name, ingredient_amount in scaled_recipe.items():
        lines.append(f"  {ingredient_name}: {format_amount(ingredient_amount)}")
    return "\n".join(lines)


def main() -> None:
    pancake_recipe: dict[str, float] = {
        "flour": 250,
        "sugar": 100,
        "milk": 330,
        "eggs": 2,
    }
    original_servings = 4
    desired_servings = 6
    scaled = scale_entire_recipe(pancake_recipe, original_servings, desired_servings)
    print(build_recipe_report(scaled, desired_servings))
    halved = scale_entire_recipe(pancake_recipe, original_servings, 2)
    print(build_recipe_report(halved, 2))


if __name__ == "__main__":
    main()

