text_nat:
XP_PER_LEVEL: int = 1000


def calculate_base_xp_yield(
    enemy_level_value: int,
    player_level_value: int,
    enemy_difficulty_rank: int,
) -> int:
    if player_level_value < 1:
        raise ValueError("player level must be at least 1")
    return (enemy_level_value * 10 * enemy_difficulty_rank) // player_level_value


def determine_level_ups(
    current_total_xp: int,
    newly_gained_xp: int,
) -> int:
    levels_before: int = current_total_xp // XP_PER_LEVEL
    levels_after: int = (current_total_xp + newly_gained_xp) // XP_PER_LEVEL
    return levels_after - levels_before


def apply_combat_results(
    current_total_xp: int,
    current_player_level: int,
    enemy_level_value: int,
    enemy_difficulty_rank: int,
) -> dict[str, int]:
    gained_xp: int = calculate_base_xp_yield(
        enemy_level_value,
        current_player_level,
        enemy_difficulty_rank,
    )
    new_total_xp: int = current_total_xp + gained_xp
    levels_gained: int = determine_level_ups(current_total_xp, gained_xp)
    return {
        "new_total_xp": new_total_xp,
        "new_player_level": current_player_level + levels_gained,
    }


def format_encounter_report(
    enemy_level_value: int,
    enemy_difficulty_rank: int,
    previous_state: dict[str, int],
    updated_state: dict[str, int],
) -> str:
    gained_xp: int = updated_state["new_total_xp"] - previous_state["new_total_xp"]
    line: str = (
        f"Lv{enemy_level_value} rank-{enemy_difficulty_rank} enemy defeated: "
        f"+{gained_xp} XP -> total {updated_state['new_total_xp']}, "
        f"level {updated_state['new_player_level']}"
    )
    if updated_state["new_player_level"] > previous_state["new_player_level"]:
        gained_levels: int = (
            updated_state["new_player_level"] - previous_state["new_player_level"]
        )
        return line + f" (LEVEL UP x{gained_levels}!)"
    return line


def run_encounter_chain(
    starting_total_xp: int,
    starting_level: int,
    encounters: list[tuple[int, int]],
) -> dict[str, int]:
    state: dict[str, int] = {
        "new_total_xp": starting_total_xp,
        "new_player_level": starting_level,
    }
    for enemy_level_value, enemy_difficulty_rank in encounters:
        updated: dict[str, int] = apply_combat_results(
            state["new_total_xp"],
            state["new_player_level"],
            enemy_level_value,
            enemy_difficulty_rank,
        )
        print(
            format_encounter_report(
                enemy_level_value, enemy_difficulty_rank, state, updated
            )
        )
        state = updated
    return state


def main() -> None:
    planned: list[tuple[int, int]] = [(6, 2), (40, 3), (12, 5), (60, 4)]
    final_state: dict[str, int] = run_encounter_chain(4800, 5, planned)
    print(
        f"Final: {final_state['new_total_xp']} XP at level "
        f"{final_state['new_player_level']}"
    )


if __name__ == "__main__":
    main()

