OVERTIME_THRESHOLD_HOURS = 40.0
OVERTIME_MULTIPLIER = 1.5


def calculate_gross_pay(
    hours_worked_this_period: float,
    hourly_wage_rate: float,
) -> float:
    if hours_worked_this_period < 0:
        raise ValueError("hours worked cannot be negative")
    if hourly_wage_rate < 0:
        raise ValueError("hourly wage rate cannot be negative")
    regular_hours = min(hours_worked_this_period, OVERTIME_THRESHOLD_HOURS)
    overtime_hours = max(0.0, hours_worked_this_period - OVERTIME_THRESHOLD_HOURS)
    regular_pay = regular_hours * hourly_wage_rate
    overtime_pay = overtime_hours * hourly_wage_rate * OVERTIME_MULTIPLIER
    return regular_pay + overtime_pay


def compute_tax_deductions(
    gross_pay_amount: float,
    employee_tax_bracket_percentage: float,
) -> float:
    if not 0 <= employee_tax_bracket_percentage <= 100:
        raise ValueError("tax bracket percentage must be between 0 and 100")
    return gross_pay_amount * employee_tax_bracket_percentage / 100


def calculate_final_net_pay(
    hours_worked_this_period: float,
    hourly_wage_rate: float,
