    hours_worked_this_period,
    hourly_wage_rate,
):
    if hours_worked_this_period < 0:
        raise ValueError("hours worked cannot be negative")
    if hourly_wage_rate < 0:
        raise ValueError("hourly wage rate cannot be negative")
    regular_hours = min(hours_worked_this_period, OVERTIME_THRESHOLD_HOURS)
    overtime_hours = max(0.0, hours_worked_this_period - OVERTIME_THRESHOLD_HOURS)
