def validate_thresholds(
    minimum_stock_threshold: int,
    target_maximum_stock_capacity: int,
) -> None:
    if minimum_stock_threshold < 0:
        raise ValueError("minimum stock threshold cannot be negative")
    if target_maximum_stock_capacity <= minimum_stock_threshold:
        raise ValueError("target capacity must exceed the minimum threshold")


def requires_reorder(
    current_stock_level: int,
    minimum_stock_threshold: int,
) -> bool:
    return current_stock_level <= minimum_stock_threshold


def calculate_reorder_quantity(
    current_stock_level: int,
    target_maximum_stock_capacity: int,
) -> int:
    return target_maximum_stock_capacity - current_stock_level


def generate_purchase_orders(
    inventory_status_records: dict[str, int],
    minimum_stock_threshold: int,
    target_maximum_stock_capacity: int,
) -> dict[str, int]:
    validate_thresholds(minimum_stock_threshold, target_maximum_stock_capacity)
    purchase_orders = {}
    for sku, current_stock_level in inventory_status_records.items():
        if requires_reorder(current_stock_level, minimum_stock_threshold):
            purchase_orders[sku] = calculate_reorder_quantity(
                current_stock_level, target_maximum_stock_capacity
            )
    return purchase_orders


def total_units_ordered(purchase_orders: dict[str, int]) -> int:
    return sum(purchase_orders.values())


def format_order_lines(purchase_orders: dict[str, int]) -> list[str]:
    lines = []
    for sku in sorted(purchase_orders):
        lines.append(f"{sku}: order {purchase_orders[sku]} units")
    return lines


def build_report(
    inventory_status_records: dict[str, int],
    minimum_stock_threshold: int,
    target_maximum_stock_capacity: int,
) -> str:
    orders = generate_purchase_orders(
        inventory_status_records,
        minimum_stock_threshold,
        target_maximum_stock_capacity,
    )
    if not orders:
        return "No reorders required."
    body = "\n".join(format_order_lines(orders))
    return f"{body}\nTotal units: {total_units_ordered(orders)}"


def main() -> None:
    inventory = {"A": 5, "B": 20, "C": 10, "D": 0}
    print(build_report(inventory, 10, 50))
    print(build_report({"E": 80, "F": 95}, 10, 50))


if __name__ == "__main__":
    main()

