BAGGAGE_FIRST_BAG_FEE = 30.0
BAGGAGE_SECOND_BAG_FEE = 40.0
BAGGAGE_EXTRA_BAG_FEE = 50.0
OVERWEIGHT_SURCHARGE = 25.0
OVERWEIGHT_LIMIT_KG = 23.0

SEAT_CLASS_COSTS = {"economy": 0.0, "premium": 50.0, "business": 200.0}
DISCOUNTED_TIERS = ("gold", "platinum")


def calculate_baggage_fees(
    number_of_checked_bags: int,
    weight_of_heaviest_bag_kg: float,
) -> float:
    if number_of_checked_bags < 0:
        raise ValueError("number_of_checked_bags cannot be negative")
    if weight_of_heaviest_bag_kg < 0:
        raise ValueError("weight_of_heaviest_bag_kg cannot be negative")
    total = 0.0
    for bag_index in range(number_of_checked_bags):
        if bag_index == 0:
            total += BAGGAGE_FIRST_BAG_FEE
        elif bag_index == 1:
            total += BAGGAGE_SECOND_BAG_FEE
        else:
            total += BAGGAGE_EXTRA_BAG_FEE
    if number_of_checked_bags > 0 and weight_of_heaviest_bag_kg > OVERWEIGHT_LIMIT_KG:
        total += OVERWEIGHT_SURCHARGE
    return total


def calculate_seat_upgrade_cost(
    seat_class_preference_name: str,
    frequent_flyer_status_tier: str,
) -> float:
    seat_key = seat_class_preference_name.strip().lower()
    if seat_key not in SEAT_CLASS_COSTS:
        raise ValueError("unknown seat class: " + seat_class_preference_name)
    upgrade_cost = SEAT_CLASS_COSTS[seat_key]
    if frequent_flyer_status_tier.strip().lower() in DISCOUNTED_TIERS:
        upgrade_cost *= 0.5
    return upgrade_cost


def compute_total_itinerary_price(
    base_ticket_fare_amount: float,
    number_of_checked_bags: int,
    weight_of_heaviest_bag_kg: float,
    seat_class_preference_name: str,
    frequent_flyer_status_tier: str,
) -> float:
    if base_ticket_fare_amount < 0:
        raise ValueError("base_ticket_fare_amount cannot be negative")
    baggage = calculate_baggage_fees(number_of_checked_bags, weight_of_heaviest_bag_kg)
    upgrade = calculate_seat_upgrade_cost(
        seat_class_preference_name, frequent_flyer_status_tier
    )
    return base_ticket_fare_amount + baggage + upgrade


def format_itinerary_receipt(
    passenger_name: str,
    itinerary: dict,
) -> str:
    baggage = calculate_baggage_fees(itinerary["bags"], itinerary["heaviest_kg"])
    upgrade = calculate_seat_upgrade_cost(itinerary["seat_class"], itinerary["tier"])
    total = compute_total_itinerary_price(
        itinerary["fare"],
        itinerary["bags"],
        itinerary["heaviest_kg"],
        itinerary["seat_class"],
        itinerary["tier"],
    )
    lines = [
        f"Passenger: {passenger_name} ({itinerary['tier']})",
        f"  Base fare      ${itinerary['fare']:8.2f}",
        f"  Baggage fees   ${baggage:8.2f}",
        f"  Seat upgrade   ${upgrade:8.2f}",
        f"  TOTAL          ${total:8.2f}",
    ]
    return "\n".join(lines)


def main() -> None:
    bookings = [
        ("Ada Lovelace", {"fare": 420.0, "bags": 3, "heaviest_kg": 26.5,
                          "seat_class": "business", "tier": "gold"}),
        ("Grace Hopper", {"fare": 180.5, "bags": 1, "heaviest_kg": 18.0,
                          "seat_class": "economy", "tier": "none"}),
        ("Alan Turing", {"fare": 310.0, "bags": 2, "heaviest_kg": 23.0,
                         "seat_class": "premium", "tier": "silver"}),
    ]
    for name, itinerary in bookings:
        print(format_itinerary_receipt(name, itinerary))
        print("-" * 34)


if __name__ == "__main__":
    main()

