MET_VALUES: dict[str, float] = {
    "running": 9.8,
    "cycling": 7.5,
    "swimming": 8.3,
    "walking": 3.5,
}

DEFAULT_MET: float = 1.0


def get_exercise_metabolic_equivalent(
    exercise_type_name_string: str,
) -> float:
    """Return the standard MET value for an exercise, or 1.0 if unknown."""
    normalized_name: str = exercise_type_name_string.strip().lower()
    return MET_VALUES.get(normalized_name, DEFAULT_MET)


def validate_positive_measurement(
    measurement_label: str,
    measurement_value: float,
) -> float:
    """Reject non-positive durations or weights, which make the formula meaningless."""
    numeric_value: float = float(measurement_value)
    if numeric_value <= 0.0:
        raise ValueError(f"{measurement_label} must be positive, got {numeric_value}")
    return numeric_value


def calculate_calories_burned(
    exercise_metabolic_equivalent_value: float,
    duration_in_minutes: float,
    user_weight_kilograms: float,
) -> float:
    energy_per_minute: float = (
        exercise_metabolic_equivalent_value * 3.5 * user_weight_kilograms
    ) / 200.0
    return duration_in_minutes * energy_per_minute


def process_workout_session(
    exercise_type_name_string: str,
    duration_in_minutes: float,
    user_weight_kilograms: float,
) -> str:
    checked_duration: float = validate_positive_measurement(
        "duration_in_minutes", duration_in_minutes
    )
    checked_weight: float = validate_positive_measurement(
        "user_weight_kilograms", user_weight_kilograms
    )
    met_value: float = get_exercise_metabolic_equivalent(exercise_type_name_string)
    burned: float = calculate_calories_burned(
        met_value, checked_duration, checked_weight
    )
    return f"Burned {round(burned, 1)} kcal doing {exercise_type_name_string.strip().lower()}"


def summarize_workout_log(
    workout_log: list[tuple[str, float]],
    user_weight_kilograms: float,
) -> str:
    report_lines: list[str] = []
    total_calories: float = 0.0
    for exercise_name, minutes in workout_log:
        report_lines.append(
            process_workout_session(exercise_name, minutes, user_weight_kilograms)
        )
        met_value: float = get_exercise_metabolic_equivalent(exercise_name)
        total_calories += calculate_calories_burned(
            met_value, minutes, user_weight_kilograms
        )
    report_lines.append(f"Total: {round(total_calories, 1)} kcal")
    return "\n".join(report_lines)


if __name__ == "__main__":
    body_weight: float = 70.0
    print(process_workout_session("running", 60.0, body_weight))
    print(process_workout_session("swimming", 45.0, body_weight))
    weekly_log: list[tuple[str, float]] = [
        ("cycling", 30.0),
        ("walking", 90.0),
        ("kayaking", 25.0),
    ]
    print(summarize_workout_log(weekly_log, body_weight))

