def validate_allocation_percentages(
    target_allocation_percentages: dict[str, float],
) -> None:
    for ticker, percentage in target_allocation_percentages.items():
        if percentage < 0 or percentage > 100:
            raise ValueError(f"allocation for {ticker} must be between 0 and 100")
    total_percentage: float = sum(target_allocation_percentages.values())
    if abs(total_percentage - 100.0) > 1e-6:
        raise ValueError(f"allocations must sum to 100, got {total_percentage}")


def calculate_current_portfolio_value(
    asset_holdings_quantities: dict[str, float],
    current_asset_prices: dict[str, float],
) -> float:
    total_value: float = 0.0
    for ticker, quantity in asset_holdings_quantities.items():
        if ticker not in current_asset_prices:
            raise KeyError(f"missing price for {ticker}")
        total_value += quantity * current_asset_prices[ticker]
    return total_value


def determine_target_value_per_asset(
    total_portfolio_value_amount: float,
    target_allocation_percentages: dict[str, float],
) -> dict[str, float]:
    validate_allocation_percentages(target_allocation_percentages)
    return {
        ticker: total_portfolio_value_amount * percentage / 100.0
        for ticker, percentage in target_allocation_percentages.items()
    }


def generate_rebalancing_trades(
    asset_holdings_quantities: dict[str, float],
    current_asset_prices: dict[str, float],
    target_allocation_percentages: dict[str, float],
) -> dict[str, float]:
    total_value: float = calculate_current_portfolio_value(
