    target_allocation_percentages,
):
    for ticker, percentage in target_allocation_percentages.items():
        if percentage < 0 or percentage > 100:
            raise ValueError(f"allocation for {ticker} must be between 0 and 100")
    total_percentage = sum(target_allocation_percentages.values())
    if abs(total_percentage - 100.0) > 1e-6:
        raise ValueError(f"allocations must sum to 100, got {total_percentage}")


def calculate_current_portfolio_value(
    asset_holdings_quantities,
    current_asset_prices,
):
