def _require_positive(
    field_name: str,
    value: int,
) -> int:
    if value <= 0:
        raise ValueError(f"{field_name} must be a positive integer, got {value}")
    return value


def _require_reliability(
    path_reliability_score: int,
) -> int:
    if not 1 <= path_reliability_score <= 255:
        raise ValueError(f"reliability must be in 1..255, got {path_reliability_score}")
    return path_reliability_score


def calculate_bandwidth_metric(
    minimum_path_bandwidth_kbps: int,
    reference_bandwidth_kbps: int,
) -> int:
    bandwidth = _require_positive("minimum_path_bandwidth_kbps", minimum_path_bandwidth_kbps)
    reference = _require_positive("reference_bandwidth_kbps", reference_bandwidth_kbps)
    return reference // bandwidth


def calculate_delay_metric(
    total_path_delay_microseconds: int,
    delay_scaling_factor: int,
) -> int:
    delay = _require_positive("total_path_delay_microseconds", total_path_delay_microseconds)
    scaling = _require_positive("delay_scaling_factor", delay_scaling_factor)
    return delay // scaling


def compute_composite_routing_metric(
    minimum_path_bandwidth_kbps: int,
    reference_bandwidth_kbps: int,
    total_path_delay_microseconds: int,
    delay_scaling_factor: int,
    path_reliability_score: int,
) -> int:
    reliability = _require_reliability(path_reliability_score)
    bandwidth_metric = calculate_bandwidth_metric(
        minimum_path_bandwidth_kbps, reference_bandwidth_kbps
    )
    delay_metric = calculate_delay_metric(
        total_path_delay_microseconds, delay_scaling_factor
    )
    metric = (bandwidth_metric + delay_metric) * 256
    if reliability < 255:
        metric = int(metric * (255 / reliability))
    return metric


def score_paths(
    path_definitions: list[tuple[str, tuple[int, int, int, int, int]]],
) -> list[tuple[str, int]]:
    scored: list[tuple[str, int]] = []
    for label, parameters in path_definitions:
        scored.append((label, compute_composite_routing_metric(*parameters)))
    return scored


def format_metric_row(
    path_label: str,
    composite_metric: int,
) -> str:
    return f"{path_label:<14}{composite_metric:>14,}"


def select_best_path(
    scored_paths: list[tuple[str, int]],
) -> str:
    return min(scored_paths, key=lambda entry: entry[1])[0]


def main() -> None:
    path_definitions = [
        ("core-fiber", (1000000, 10000000, 1000, 10, 255)),
        ("metro-ring", (100000, 10000000, 4500, 10, 250)),
        ("backup-dsl", (2048, 10000000, 21000, 10, 200)),
    ]
    scored_paths = score_paths(path_definitions)
    print(f"{'PATH':<14}{'METRIC':>14}")
    for label, metric in scored_paths:
        print(format_metric_row(label, metric))
    print(f"preferred path: {select_best_path(scored_paths)}")


if __name__ == "__main__":
    main()

