CATEGORY_DAILY_RATES = {"book": 0.25, "dvd": 1.00, "equipment": 5.00}

ABSOLUTE_FINE_CEILING = 10.00


def normalize_category_name(
    raw_category_text: str,
) -> str:
    return raw_category_text.strip().lower()


def determine_daily_fine_rate(
    library_item_category_name: str,
) -> float:
    normalized_name = normalize_category_name(library_item_category_name)
    if normalized_name not in CATEGORY_DAILY_RATES:
        raise ValueError(f"unknown library item category: {library_item_category_name!r}")
    return CATEGORY_DAILY_RATES[normalized_name]


def calculate_raw_fine_amount(
    days_overdue_count: int,
    daily_fine_rate_amount: float,
) -> float:
    if days_overdue_count <= 0:
        return 0.0
    return float(days_overdue_count) * float(daily_fine_rate_amount)


def determine_effective_cap(
    item_replacement_cost_amount: float,
) -> float:
    if item_replacement_cost_amount < 0:
        raise ValueError("replacement cost may not be negative")
    return min(ABSOLUTE_FINE_CEILING, item_replacement_cost_amount)


def compute_final_capped_fine(
    library_item_category_name: str,
    days_overdue_count: int,
    item_replacement_cost_amount: float,
) -> float:
    daily_rate = determine_daily_fine_rate(library_item_category_name)
    raw_fine = calculate_raw_fine_amount(days_overdue_count, daily_rate)
    effective_cap = determine_effective_cap(item_replacement_cost_amount)
    return float(min(raw_fine, effective_cap))


def format_currency_amount(
    amount_value: float,
) -> str:
    return f"${amount_value:,.2f}"


def build_fine_report_line(
    library_item_category_name: str,
    days_overdue_count: int,
    item_replacement_cost_amount: float,
) -> str:
    final_fine = compute_final_capped_fine(
        library_item_category_name,
        days_overdue_count,
        item_replacement_cost_amount,
    )
    daily_rate = determine_daily_fine_rate(library_item_category_name)
    raw_fine = calculate_raw_fine_amount(days_overdue_count, daily_rate)
    category_label = normalize_category_name(library_item_category_name)
    return (
        f"{category_label}: {days_overdue_count} day(s) overdue at "
        f"{format_currency_amount(daily_rate)}/day = {format_currency_amount(raw_fine)} raw, "
        f"capped to {format_currency_amount(final_fine)} "
        f"(replacement cost {format_currency_amount(item_replacement_cost_amount)})"
    )


def main() -> None:
    overdue_days = 10
    replacement_cost = 15.00
    print(build_fine_report_line("dvd", overdue_days, replacement_cost))
