BASE_PRICE: float = 15.0
CHILD_AGE_LIMIT: int = 12
SENIOR_AGE_LIMIT: int = 65
TUESDAY: int = 2
TUESDAY_DEDUCTION: float = 3.0
IMAX_PREMIUM: float = 5.0


def validate_booking(
    booking: tuple[int, int, str],
) -> tuple[int, int, str]:
    age, day, fmt = booking
    if age < 0:
        raise ValueError(f"age must not be negative: {age}")
    if not 1 <= day <= 7:
        raise ValueError(f"day must be between 1 and 7: {day}")
    return age, day, fmt.strip().lower()


def age_multiplier(
    age: int,
) -> float:
    if age < CHILD_AGE_LIMIT:
        return 0.5
    if age > SENIOR_AGE_LIMIT:
        return 0.8
    return 1.0


def day_deduction(
    day: int,
) -> float:
    return TUESDAY_DEDUCTION if day == TUESDAY else 0.0


def format_premium(
    movie_format: str,
) -> float:
    return IMAX_PREMIUM if movie_format == "imax" else 0.0


def ticket_price(
    booking: tuple[int, int, str],
) -> float:
    age, day, movie_format = validate_booking(booking)
    discounted: float = BASE_PRICE * age_multiplier(age)
    return discounted - day_deduction(day) + format_premium(movie_format)


def price(
    bookings: list[tuple[int, int, str]],
) -> float:
    return sum(ticket_price(booking) for booking in bookings)


def receipt_line(
    booking: tuple[int, int, str],
) -> str:
    age, day, movie_format = validate_booking(booking)
    label: str = f"age {age}, day {day}, {movie_format}"
    return f"{label:<28} {ticket_price(booking):>7.2f}"


