        (8, 6, "IMAX"),
        (45, 2, "imax"),
    ]
    for booking in bookings:
        print(receipt_line(booking))
    total: float = price(bookings)
    print(f"{'TOTAL':<28} {total:>7.2f}")


if __name__ == "__main__":
