from __future__ import annotations

MISSING_SENTINEL: float = -999.0
HOT_THRESHOLD: float = 30.0


def is_missing(
    value: float,
) -> bool:
    return value <= MISSING_SENTINEL


def neighbour_average(
    values: list[float],
    index: int,
) -> float:
    previous: float | None = None
    for i in range(index - 1, -1, -1):
        if not is_missing(values[i]):
            previous = values[i]
            break
    following: float | None = None
    for j in range(index + 1, len(values)):
        if not is_missing(values[j]):
            following = values[j]
            break
    if previous is not None and following is not None:
        return (previous + following) / 2.0
    if previous is not None:
        return previous
    if following is not None:
        return following
    raise ValueError("cannot interpolate: no valid temperatures available")


def fill_missing(
    values: list[float],
) -> list[float]:
    return [
        neighbour_average(values, i) if is_missing(v) else float(v)
        for i, v in enumerate(values)
    ]


def moving_average(
    values: list[float],
    window: int = 3,
) -> list[float]:
    half = window // 2
    averages: list[float] = []
    for i in range(len(values)):
        low = max(0, i - half)
        high = min(len(values), i + half + 1)
        chunk = values[low:high]
        averages.append(sum(chunk) / len(chunk))
    return averages


def count_above(
    values: list[float],
    threshold: float,
) -> int:
    return sum(1 for value in values if value > threshold)


def format_report(
    filled: list[float],
    averages: list[float],
) -> str:
    lines = ["day  filled  smoothed"]
    for day, (raw, avg) in enumerate(zip(filled, averages), start=1):
        lines.append(f"{day:>3}  {raw:>6.2f}  {avg:>8.2f}")
    return "\n".join(lines)


def smooth(
    temperatures: list[float],
) -> int:
    for value in temperatures:
        if not isinstance(value, (int, float)):
            raise TypeError(f"temperature readings must be numeric, got {value!r}")
    if not temperatures:
        return 0
    filled = fill_missing(temperatures)
    return count_above(moving_average(filled), HOT_THRESHOLD)


def main() -> None:
    readings: list[float] = [20.0, -999.0, 24.0, 31.5, 33.0, -999.0, 36.0, 29.0]
    filled = fill_missing(readings)
    print(format_report(filled, moving_average(filled)))
    print(f"days above {HOT_THRESHOLD:.0f} degrees: {smooth(readings)}")


if __name__ == "__main__":
    main()

