def format_report(
    filled,
    averages,
):
    lines = ["day  filled  smoothed"]
    for day, (raw, avg) in enumerate(zip(filled, averages), start=1):
        lines.append(f"{day:>3}  {raw:>6.2f}  {avg:>8.2f}")
    return "\n".join(lines)


def smooth(
    temperatures,
):
    for value in temperatures:
        if not isinstance(value, (int, float)):
            raise TypeError(f"temperature readings must be numeric, got {value!r}")
    if not temperatures:
        return 0
    filled = fill_missing(temperatures)
    return count_above(moving_average(filled), HOT_THRESHOLD)


def main():
    readings = [20.0, -999.0, 24.0, 31.5, 33.0, -999.0, 36.0, 29.0]
    filled = fill_missing(readings)
    print(format_report(filled, moving_average(filled)))
    print(f"days above {HOT_THRESHOLD:.0f} degrees: {smooth(readings)}")


if __name__ == "__main__":
    main()

