"""Loyalty points rewards for a coffee shop."""

REWARD_THRESHOLD = 100
CUP_BONUS = 2


def points_for(
    amount: float,
    reusable_cup: bool,
) -> int:
    """One point per whole dollar, plus a bonus for a reusable cup."""
    if amount < 0:
        raise ValueError("purchase amount cannot be negative")
    points = int(amount)
    if reusable_cup:
        points += CUP_BONUS
    return points


def normalize_id(
    customer_id: str,
) -> str:
    cleaned = customer_id.strip()
    if not cleaned:
        raise ValueError("customer id must not be blank")
    return cleaned


def accumulate(
    purchases: list[tuple[str, float, bool]],
) -> dict[str, int]:
    totals = {}
    for customer_id, amount, reusable_cup in purchases:
        key = normalize_id(customer_id)
        totals[key] = totals.get(key, 0) + points_for(amount, reusable_cup)
    return totals


def qualifying_ids(
    totals: dict[str, int],
) -> list[str]:
    return sorted(
        customer_id
        for customer_id, points in totals.items()
        if points >= REWARD_THRESHOLD
    )


def reward(
    purchases: list[tuple[str, float, bool]],
) -> list[str]:
    return qualifying_ids(accumulate(purchases))


def format_report(
    totals: dict[str, int],
) -> str:
    lines = []
    for customer_id in sorted(totals):
        points = totals[customer_id]
        status = "REWARD" if points >= REWARD_THRESHOLD else "pending"
        lines.append(f"{customer_id:<8}{points:>5} pts  {status}")
    return "\n".join(lines)


def main() -> None:
    purchases = [
        ("alice", 45.75, True),
        ("alice", 52.10, True),
        ("bob", 12.99, False),
        ("carol", 99.00, True),
        ("bob", 30.50, True),
        ("carol", 4.25, False),
    ]
    print(format_report(accumulate(purchases)))
    rewarded = reward(purchases)
    print("Rewarded:", ", ".join(rewarded) if rewarded else "nobody yet")


if __name__ == "__main__":
    main()

