from __future__ import annotations


def validate_players(
    entries: list[tuple[str, int]],
) -> list[tuple[str, int]]:
    checked: list[tuple[str, int]] = []
    for position, entry in enumerate(entries):
        if len(entry) != 2:
            raise ValueError(f"entry {position} must be a (name, wins) pair")
        name, wins = entry
        if not isinstance(name, str) or not name.strip():
            raise ValueError(f"entry {position} has an empty player name")
        if not isinstance(wins, int) or isinstance(wins, bool):
            raise ValueError(f"player {name!r} has a non-integer win record")
        if wins < 0:
            raise ValueError(f"player {name!r} has a negative win record")
        checked.append((name.strip(), wins))
    return checked


def rank_players(
    entries: list[tuple[str, int]],
) -> list[tuple[str, int]]:
    return sorted(entries, key=lambda entry: (-entry[1], entry[0].lower()))


def seed(
    players: list[tuple[str, int]],
) -> list[tuple[str, str | None]]:
    ranked = rank_players(validate_players(players))
    pairs: list[tuple[str, str | None]] = []
    top = 0
    bottom = len(ranked) - 1
    while top < bottom:
        pairs.append((ranked[top][0], ranked[bottom][0]))
        top += 1
        bottom -= 1
    if top == bottom:
        pairs.append((ranked[top][0], None))
    return pairs


def format_pairing(
    match_number: int,
    pair: tuple[str, str | None],
) -> str:
    home, away = pair
    if away is None:
        return f"Match {match_number}: {home} advances on a bye"
    return f"Match {match_number}: {home} vs {away}"


def build_report(
    players: list[tuple[str, int]],
) -> str:
    pairings = seed(players)
    lines = [
        format_pairing(number, pair)
        for number, pair in enumerate(pairings, start=1)
    ]
    return "\n".join(lines)


def main() -> None:
    roster: list[tuple[str, int]] = [
        ("Alice", 10),
        ("Bob", 2),
        ("Charlie", 5),
        ("Dana", 7),
        ("Eve", 1),
        ("Frank", 9),
    ]
    print(seed([("Alice", 10), ("Bob", 2), ("Charlie", 5)]))
    print(build_report(roster))


if __name__ == "__main__":
