BRACKETS: tuple[tuple[float, float], ...] = (
    (10000.0, 0.00),
    (30000.0, 0.10),
    (float("inf"), 0.20),
)

DEDUCTION: float = 2000.0


def validate_income(
    income: float,
) -> float:
    if income < 0:
        raise ValueError(f"income must not be negative: {income}")
    return float(income)


def base_tax(
    income: float,
) -> float:
    remaining: float = income
    total: float = 0.0
    for width, rate in BRACKETS:
        taxed: float = min(remaining, width)
        total += taxed * rate
        remaining -= taxed
        if remaining <= 0:
            break
    return total


def apply_deduction(
    gross: float,
) -> float:
    return max(0.0, gross - DEDUCTION)


def tax(
    incomes: list[float],
) -> list[float]:
    results: list[float] = []
    for raw in incomes:
        income: float = validate_income(raw)
        results.append(apply_deduction(base_tax(income)))
    return results


def format_row(
    income: float,
    net: float,
) -> str:
    effective: float = (net / income * 100.0) if income else 0.0
    return f"{income:>12,.2f} {net:>12,.2f} {effective:>8.2f}%"


def format_report(
    incomes: list[float],
) -> str:
    nets: list[float] = tax(incomes)
    lines: list[str] = [f"{'income':>12} {'net tax':>12} {'rate':>9}"]
    for income, net in zip(incomes, nets):
        lines.append(format_row(income, net))
    return "\n".join(lines)


def main() -> None:
    sample: list[float] = [5000.0, 12000.0, 40000.0, 50000.0, 120000.0]
    print(format_report(sample))


