COMPLETE_THRESHOLD = 90.0


def _normalize(
    entry: tuple[str, float, float],
) -> tuple[str, float, float]:
    """Validate one raw record and clamp watched time to the module length."""
    name, total, watched = entry
    if not str(name).strip():
        raise ValueError("module name must not be empty")
    if total < 0 or watched < 0:
        raise ValueError(f"negative duration for module {name!r}")
    return str(name), float(total), min(float(watched), float(total))


def percent_watched(
    total: float,
    watched: float,
) -> float:
    """Completion percentage; a module with no content counts as finished."""
    if total == 0.0:
        return 100.0
    return watched / total * 100.0


def is_complete(
    percent: float,
) -> bool:
    return percent >= COMPLETE_THRESHOLD


def remaining_minutes(
    total: float,
    watched: float,
) -> int:
    return int(round(total - watched))


def progress(
    modules: list[tuple[str, float, float]],
) -> tuple[int, int]:
    completed = 0
    unwatched = 0
    for entry in modules:
        _, total, watched = _normalize(entry)
        if is_complete(percent_watched(total, watched)):
            completed += 1
        else:
            unwatched += remaining_minutes(total, watched)
    return completed, unwatched


def format_report(
    modules: list[tuple[str, float, float]],
) -> str:
    rows = []
    for entry in modules:
        name, total, watched = _normalize(entry)
        percent = percent_watched(total, watched)
        status = "done" if is_complete(percent) else f"{remaining_minutes(total, watched)} min left"
        rows.append(f"{name:<20} {percent:6.1f}%  {status}")
    completed, unwatched = progress(modules)
    rows.append(f"{completed}/{len(modules)} modules complete, {unwatched} minutes remaining")
    return "\n".join(rows)


def main() -> None:
    course = [
        ("Intro to Python", 100, 95),
        ("Data Structures", 120, 60),
        ("Testing Basics", 45, 45),
        ("Async Programming", 80, 12),
    ]
    print(format_report(course))


if __name__ == "__main__":
    main()

