from itertools import groupby
from operator import itemgetter

SCORE_THRESHOLD = 7.0
DURATION_THRESHOLD = 300.0

SAMPLE_CALLS: list[tuple[str, float, int]] = [
    ("a101", 350, 6),
    ("a101", 360, 6),
    ("b202", 120, 9),
    ("b202", 200, 8),
    ("c303", 400, 8),
    ("d404", 280, 4),
]


def validate_call(
    call: tuple[str, float, int],
) -> tuple[str, float, int]:
    agent_id, duration, score = call
    if not isinstance(agent_id, str) or not agent_id.strip():
        raise ValueError(f"agent id must be a non-empty string: {agent_id!r}")
    if duration < 0:
        raise ValueError(f"call duration must not be negative: {duration!r}")
    if not 1 <= score <= 10:
        raise ValueError(f"satisfaction score must be 1..10: {score!r}")
    return agent_id.strip(), float(duration), int(score)


def group_calls(
    calls: list[tuple[str, float, int]],
) -> dict[str, list[tuple[float, int]]]:
    validated = sorted(validate_call(call) for call in calls)
    return {
        agent_id: [(duration, score) for _, duration, score in records]
        for agent_id, records in groupby(validated, key=itemgetter(0))
    }


def mean(
    values: list[float],
) -> float:
    return sum(values) / len(values)


def agent_stats(
    calls: list[tuple[str, float, int]],
) -> dict[str, tuple[float, float]]:
    return {
        agent_id: (
            mean([float(score) for _, score in records]),
            mean([duration for duration, _ in records]),
        )
        for agent_id, records in group_calls(calls).items()
    }


def is_flagged(
    avg_score: float,
    avg_duration: float,
) -> bool:
    return avg_score < SCORE_THRESHOLD and avg_duration > DURATION_THRESHOLD


def format_report(
    stats: dict[str, tuple[float, float]],
    flagged: list[str],
) -> list[str]:
    return [
        f"{agent_id}: score={stats[agent_id][0]:.2f} "
        f"duration={stats[agent_id][1]:.1f}s "
        f"[{'FLAGGED' if agent_id in flagged else 'ok'}]"
        for agent_id in sorted(stats)
    ]


def evaluate(
    calls: list[tuple[str, float, int]],
) -> list[str]:
    stats = agent_stats(calls)
    return [
        agent_id
        for agent_id in sorted(stats)
        if is_flagged(stats[agent_id][0], stats[agent_id][1])
    ]


def main() -> None:
    stats: dict[str, tuple[float, float]] = agent_stats(SAMPLE_CALLS)
    flagged: list[str] = evaluate(SAMPLE_CALLS)
    for line in format_report(stats, flagged):
        print(line)
    print("flagged agents:", flagged)


if __name__ == "__main__":
    main()

