def normalize(
    record: tuple,
) -> tuple[str, float, str]:
    """Coerce a raw transaction tuple into (user id, amount, location)."""
    if len(record) != 3:
        raise ValueError(f"transaction must have 3 fields: {record!r}")
    user_id, amount, location = record
    user_key = str(user_id).strip()
    if not user_key:
        raise ValueError("transaction is missing a user id")
    return user_key, float(amount), str(location).strip()


def group_amounts(
    transactions: list[tuple[str, float, str]],
) -> dict[str, list[float]]:
    grouped: dict[str, list[float]] = {}
    for user_id, amount, _location in transactions:
        grouped.setdefault(user_id, []).append(amount)
    return grouped


def average_amounts(
    grouped: dict[str, list[float]],
) -> dict[str, float]:
    return {user: sum(values) / len(values) for user, values in grouped.items()}


def is_flagged(
    amount: float,
    average: float,
) -> bool:
    if amount > HARD_LIMIT:
        return True
    return amount > AVERAGE_MULTIPLIER * average


def flagged_transactions(
    transactions: list[tuple[str, float, str]],
    averages: dict[str, float],
) -> list[tuple[str, float, str]]:
    suspicious: list[tuple[str, float, str]] = []
    for user_id, amount, location in transactions:
        if is_flagged(amount, averages[user_id]):
            suspicious.append((user_id, amount, location))
    return suspicious


def detect(
    transactions: list[tuple],
) -> list[str]:
    clean = [normalize(record) for record in transactions]
    averages = average_amounts(group_amounts(clean))
    offenders: list[str] = []
    for user_id, _amount, _location in flagged_transactions(clean, averages):
        if user_id not in offenders:
            offenders.append(user_id)
    return offenders


def format_report(
    suspicious: list[tuple[str, float, str]],
    averages: dict[str, float],
) -> str:
    lines = [
        f"{user_id}: {amount:.2f} in {location} (avg {averages[user_id]:.2f})"
        for user_id, amount, location in suspicious
    ]
