HORIZON_START: int = 1
HORIZON_END: int = 30


def booking_days(
    room: int,
    check_in: int,
    check_out: int,
) -> list[int]:
    """Days occupied by one booking: check-in inclusive, check-out exclusive."""
    if check_out <= check_in:
        raise ValueError(f"room {room}: check-out {check_out} must follow check-in {check_in}")
    return list(range(check_in, check_out))


def expand_bookings(
    bookings: list[tuple[int, int, int]],
) -> list[list[int]]:
    """Turn every booking into its own list of occupied days."""
    expanded: list[list[int]] = []
    for room, check_in, check_out in bookings:
        expanded.append(booking_days(room, check_in, check_out))
    return expanded


def daily_occupancy(
    expanded: list[list[int]],
) -> dict[int, int]:
    """Count occupied rooms for each day of the planning horizon."""
    counts: dict[int, int] = {day: 0 for day in range(HORIZON_START, HORIZON_END + 1)}
    for days in expanded:
        for day in days:
            if day in counts:
                counts[day] += 1
    return counts


def find_peak(
    counts: dict[int, int],
) -> tuple[int, int]:
    """Return the earliest day carrying the highest occupancy."""
    peak_day: int = HORIZON_START
    peak_count: int = counts[HORIZON_START]
    for day in range(HORIZON_START + 1, HORIZON_END + 1):
        if counts[day] > peak_count:
            peak_day = day
            peak_count = counts[day]
    return peak_day, peak_count


def occupancy(
    bookings: list[tuple[int, int, int]],
) -> tuple[int, int]:
    """Entry function: peak day and peak number of occupied rooms."""
    return find_peak(daily_occupancy(expand_bookings(bookings)))


def format_report(
    counts: dict[int, int],
) -> str:
    """Render a one-line-per-day textual summary of busy days."""
    lines: list[str] = []
    for day, count in sorted(counts.items()):
        if count:
            lines.append(f"day {day:2d}: {'#' * count} ({count})")
    return "\n".join(lines)


def main() -> None:
    bookings: list[tuple[int, int, int]] = [
        (101, 2, 4),
        (102, 3, 8),
        (103, 3, 5),
        (104, 7, 12),
        (101, 6, 9),
        (105, 25, 31),
    ]
    counts: dict[int, int] = daily_occupancy(expand_bookings(bookings))
    print(format_report(counts))
    day, rooms = occupancy(bookings)
    print(f"Peak occupancy: {rooms} rooms on day {day}")


if __name__ == "__main__":
    main()

