from __future__ import annotations


def _clean_song(
    song: object,
) -> tuple[str, str, int]:
    """Validate a raw record and return it as (title, genre, seconds)."""
    if not isinstance(song, tuple) or len(song) != 3:
        raise ValueError(f"each song must be a 3-tuple, got {song!r}")
    title, genre, seconds = song
    if not isinstance(title, str) or not title.strip():
        raise ValueError(f"song title must be a non-empty string, got {title!r}")
    if not isinstance(genre, str) or not genre.strip():
        raise ValueError(f"genre must be a non-empty string, got {genre!r}")
    if not isinstance(seconds, int) or isinstance(seconds, bool) or seconds < 0:
        raise ValueError(f"length must be a non-negative int, got {seconds!r}")
    return title.strip(), genre.strip(), seconds


def group_by_genre(
    songs: list[tuple[str, str, int]],
) -> dict[str, int]:
    """Sum the lengths of all songs belonging to the same genre."""
    totals: dict[str, int] = {}
    for song in songs:
        _, genre, seconds = _clean_song(song)
        totals[genre] = totals.get(genre, 0) + seconds
    return totals


def format_duration(
    total_seconds: int,
) -> str:
    minutes, seconds = divmod(total_seconds, 60)
    return f"{minutes} minutes {seconds} seconds"


def organize(
    songs: list[tuple[str, str, int]],
) -> list[tuple[str, str]]:
    """Group songs by genre and report each genre's total playing time."""
    totals = group_by_genre(songs)
    ordered: list[tuple[str, int]] = sorted(
        totals.items(), key=lambda item: (-item[1], item[0])
    )
    return [(genre, format_duration(total)) for genre, total in ordered]


def build_report(
    entries: list[tuple[str, str]],
) -> str:
    if not entries:
        return "No songs to organize."
    width: int = max(len(genre) for genre, _ in entries)
    lines = [f"{genre.ljust(width)}  {duration}" for genre, duration in entries]
    return "\n".join(lines)


def main() -> None:
    library: list[tuple[str, str, int]] = [
        ("Bright Lights", "pop", 120),
        ("Sugar Rush", "pop", 120),
        ("Midnight Blues", "jazz", 305),
        ("Slow Burn", "jazz", 254),
        ("Thunder Road", "rock", 185),
        ("Quiet Hours", "ambient", 600),
    ]
    print(build_report(organize(library)))


if __name__ == "__main__":
    main()

