HEAVY_WEIGHT_LIMIT = 50.0
BULKY_VOLUME_LIMIT = 2.0

ZONE_HEAVY = "heavy"
ZONE_BULKY = "bulky"
ZONE_STANDARD = "standard"


def classify_zone(
    weight: float,
    volume: float,
) -> str:
    if weight > HEAVY_WEIGHT_LIMIT:
        return ZONE_HEAVY
    if volume > BULKY_VOLUME_LIMIT:
        return ZONE_BULKY
    return ZONE_STANDARD


def validate_item(
    item: tuple,
) -> tuple[str, float, float]:
    if len(item) != 3:
        raise ValueError(f"item must have 3 fields, got {len(item)}")
    item_id, weight, volume = item
    if not isinstance(item_id, str) or not item_id:
        raise ValueError(f"item id must be a non-empty string: {item_id!r}")
    weight_value = float(weight)
    volume_value = float(volume)
    if weight_value < 0.0 or volume_value < 0.0:
        raise ValueError(f"item {item_id} has negative measurements")
    return item_id, weight_value, volume_value


def assign_zones(
    items: list,
) -> dict[str, str]:
    assignments = {}
    for item in items:
        item_id, weight, volume = validate_item(item)
        assignments[item_id] = classify_zone(weight, volume)
    return assignments


def allocate(
    items: list,
) -> tuple[int, int, int]:
    zones = list(assign_zones(items).values())
    return (
        zones.count(ZONE_HEAVY),
        zones.count(ZONE_BULKY),
        zones.count(ZONE_STANDARD),
    )


def format_report(
    counts: tuple[int, int, int],
) -> str:
    heavy, bulky, standard = counts
    lines = [
        f"heavy    : {heavy}",
        f"bulky    : {bulky}",
        f"standard : {standard}",
        f"total    : {heavy + bulky + standard}",
    ]
    return "\n".join(lines)


def main() -> None:
    warehouse = [
        ("A-1", 60.0, 3.0),
        ("A-2", 51.5, 0.4),
        ("B-1", 12.0, 2.5),
        ("B-2", 50.0, 2.0),
        ("C-1", 3.2, 0.1),
        ("C-2", 0.5, 1.9),
    ]
    print(format_report(allocate(warehouse)))


if __name__ == "__main__":
    main()

