MOISTURE_THRESHOLD: int = 30
SHORT_CYCLE_DAYS: int = 3


def is_thirsty(
    moisture: int,
) -> bool:
    return moisture < MOISTURE_THRESHOLD


def water_amount(
    frequency: int,
) -> int:
    if frequency < SHORT_CYCLE_DAYS:
        return 500
    return 1000


def validate_plant(
    entry: tuple,
) -> tuple[str, int, int]:
    if len(entry) != 3:
        raise ValueError(f"plant record must have 3 fields: {entry!r}")
    name, moisture, frequency = entry
    if not isinstance(name, str) or not name.strip():
        raise ValueError(f"plant name must be a non-empty string: {name!r}")
    if not 0 <= moisture <= 100:
        raise ValueError(f"moisture for {name} out of range: {moisture!r}")
    if frequency <= 0:
        raise ValueError(f"watering frequency for {name} must be positive")
    return name.strip(), int(moisture), int(frequency)


def schedule(
    plants: list[tuple],
) -> list[tuple[str, int]]:
    plan: list[tuple[str, int]] = []
    for entry in plants:
        name, moisture, frequency = validate_plant(entry)
        if is_thirsty(moisture):
            plan.append((name, water_amount(frequency)))
    return plan


def total_water(
    plan: list[tuple[str, int]],
) -> int:
    return sum(item[1] for item in plan)


def format_row(
    name: str,
    millilitres: int,
) -> str:
    return f"{name:<12} {millilitres:>5} ml"


def build_report(
    plan: list[tuple[str, int]],
) -> str:
    if not plan:
        return "All plants are sufficiently watered."
    lines: list[str] = [format_row(name, ml) for name, ml in plan]
    lines.append(f"{'TOTAL':<12} {total_water(plan):>5} ml")
    return "\n".join(lines)


def main() -> None:
    garden: list[tuple[str, int, int]] = [
        ("fern", 20, 2),
        ("cactus", 55, 14),
        ("basil", 18, 1),
        ("ficus", 29, 5),
        ("orchid", 12, 7),
    ]
    print(build_report(schedule(garden)))


if __name__ == "__main__":
    main()

