RATE_BY_RATING = {5: 0.20, 4: 0.15, 3: 0.10}


def tip_rate(
    rating: int,
) -> float:
    """Return the tip fraction earned for a given customer rating."""
    return RATE_BY_RATING.get(rating, 0.0)


def validate_entry(
    entry: tuple[str, float, int],
) -> tuple[str, float, int]:
    """Normalise one raw bill record, rejecting unusable values."""
    server, total, rating = entry
    if not server.strip():
        raise ValueError("server name must not be blank")
    amount = float(total)
    if amount < 0:
        raise ValueError(f"bill total for {server} must not be negative")
    stars = int(rating)
    if not 1 <= stars <= 5:
        raise ValueError(f"rating {rating} for {server} is outside 1..5")
    return server.strip(), amount, stars


def tip_amount(
    bill_total: float,
    rating: int,
) -> float:
    """Tip in dollars produced by one bill."""
    return bill_total * tip_rate(rating)


def accumulate_tips(
    entries: list[tuple[str, float, int]],
) -> dict[str, float]:
    """Sum tips per server, keeping first-seen server order."""
    totals = {}
    for server, amount, stars in entries:
        totals[server] = totals.get(server, 0.0) + tip_amount(amount, stars)
    return totals


def calculate(
    bills: list[tuple[str, float, int]],
) -> list[tuple[str, float]]:
    """Entry point: total tips per server, rounded to one decimal."""
    cleaned = [validate_entry(entry) for entry in bills]
    totals = accumulate_tips(cleaned)
    return [(server, round(tips, 1)) for server, tips in totals.items()]


def format_report(
    results: list[tuple[str, float]],
) -> str:
    """Render the per-server totals as an aligned text table."""
    if not results:
        return "no tips earned"
    width = max(len(server) for server, _ in results)
    lines = [f"{server:<{width}}  ${tips:>8.1f}" for server, tips in results]
    return "\n".join(lines)


def main() -> None:
    shift = [
        ("Jesse", 100.0, 4),
        ("Jesse", 80.5, 5),
        ("Rachel", 60.0, 3),
        ("Rachel", 45.25, 2),
        ("Sam", 120.0, 5),
    ]
    results = calculate(shift)
    print(format_report(results))
    payout = sum(tips for _, tips in results)
    print(f"total payout: ${payout:.1f}")


if __name__ == "__main__":
    main()

