OPEN_START: int = 9
OPEN_END: int = 21


def validate_entries(
    entries: list[tuple[int, int]],
) -> None:
    """Reject malformed records before they corrupt the aggregation."""
    for hour, count in entries:
        if not isinstance(hour, int) or not 0 <= hour <= 23:
            raise ValueError(f"hour out of range: {hour!r}")
        if not isinstance(count, int) or count < 0:
            raise ValueError(f"invalid visitor count: {count!r}")


def aggregate_hours(
    entries: list[tuple[int, int]],
) -> dict[int, int]:
    """Sum the people entering for every hour of the day."""
    totals: dict[int, int] = {hour: 0 for hour in range(24)}
    for hour, count in entries:
        totals[hour] += count
    return totals


def find_peak_hour(
    totals: dict[int, int],
) -> int:
    """Return the busiest hour, preferring the earliest one on a tie."""
    peak: int = 0
    for hour in range(24):
        if totals[hour] > totals[peak]:
            peak = hour
    return peak


def open_hours() -> range:
    return range(OPEN_START, OPEN_END + 1)


def average_open_hours(
    totals: dict[int, int],
) -> float:
    """Mean visitors per hour across the store's opening window."""
    window: range = open_hours()
    served: int = sum(totals[hour] for hour in window)
    return served / len(window)


def format_report(
    peak: int,
    average: float,
    totals: dict[int, int],
) -> str:
    lines: list[str] = [f"Peak hour: {peak:02d}:00 ({totals[peak]} visitors)"]
    lines.append(f"Average during open hours: {average:.2f}")
    for hour in open_hours():
        bar: str = "#" * (totals[hour] // 10)
        lines.append(f"  {hour:02d}:00 {totals[hour]:4d} {bar}")
    return "\n".join(lines)


def traffic(
    entries: list[tuple[int, int]],
) -> tuple[int, float]:
    validate_entries(entries)
    totals: dict[int, int] = aggregate_hours(entries)
    return find_peak_hour(totals), average_open_hours(totals)


def main() -> None:
    log: list[tuple[int, int]] = [
        (8, 12), (9, 40), (10, 50), (10, 15), (11, 150),
        (12, 90), (13, 70), (14, 65), (15, 55), (16, 80),
        (17, 120), (18, 110), (19, 60), (20, 35), (21, 20),
        (22, 5),
    ]
    peak, average = traffic(log)
    print(format_report(peak, average, aggregate_hours(log)))


if __name__ == "__main__":
    main()

