def validate_sighting(
    record: tuple[str, int, str],
) -> tuple[str, int, str]:
    animal_id, zone, time_of_day = record
    if not isinstance(animal_id, str) or not animal_id:
        raise ValueError(f"animal id must be a non-empty string: {animal_id!r}")
    if not isinstance(zone, int) or isinstance(zone, bool):
        raise ValueError(f"zone must be an integer: {zone!r}")
    if not isinstance(time_of_day, str) or not time_of_day:
        raise ValueError(f"time of day must be a non-empty string: {time_of_day!r}")
    return record


def group_zones_by_animal(
    sightings: list[tuple[str, int, str]],
) -> dict[str, list[int]]:
    grouped = defaultdict(list)
    for record in sightings:
        animal_id, zone, _time_of_day = validate_sighting(record)
        grouped[animal_id].append(zone)
    return dict(grouped)


def distinct_zone_count(
    zones: list[int],
) -> int:
    return len(set(zones))


def most_frequent_zone(
    zones: list[int],
) -> int:
    counts = Counter(zones)
    best_zone, best_count = zones[0], 0
    for zone, count in sorted(counts.items()):
        if count > best_count:
            best_zone, best_count = zone, count
    return best_zone


def select_active_animals(
    grouped: dict[str, list[int]],
    minimum_zones: int,
) -> list[str]:
    return [
        animal_id
        for animal_id, zones in grouped.items()
        if distinct_zone_count(zones) > minimum_zones
    ]


def track(
