BASE_FEE: float = 10.0
OVERAGE_RATE: float = 2.0


def overage(
    used: float,
    limit: float,
) -> float:
    """Gigabytes consumed beyond the plan limit (never negative)."""
    if used > limit:
        return used - limit
    return 0.0


def charge_for(
    used: float,
    limit: float,
) -> float:
    """Base fee plus the per-gigabyte penalty for any overage."""
    extra: float = overage(used, limit)
    return BASE_FEE + OVERAGE_RATE * extra


def validate_record(
    record: tuple,
) -> tuple[str, float, float]:
    """Unpack one usage record, rejecting malformed or negative values."""
    if len(record) != 3:
        raise ValueError(f"expected 3 fields per record, got {len(record)}")
    account_id, used, limit = record
    if not isinstance(account_id, str) or not account_id:
        raise ValueError("account id must be a non-empty string")
    used_gb = float(used)
    limit_gb = float(limit)
    if used_gb < 0 or limit_gb < 0:
        raise ValueError(f"negative gigabytes for account {account_id}")
    return account_id, used_gb, limit_gb


def bill(
    usage: list,
) -> list[tuple[str, float]]:
    """Turn usage records into (account id, total bill) pairs."""
    bills: list[tuple[str, float]] = []
    for record in usage:
        account_id, used_gb, limit_gb = validate_record(record)
        bills.append((account_id, charge_for(used_gb, limit_gb)))
    return bills


def format_line(
    account_id: str,
    amount: float,
) -> str:
    return f"{account_id:<8} ${amount:>7.2f}"


def report(
    usage: list,
) -> str:
    """Human-readable statement covering every account, with a grand total."""
    results = bill(usage)
    lines = [format_line(account_id, amount) for account_id, amount in results]
    total: float = sum(amount for _, amount in results)
    lines.append(format_line("TOTAL", total))
    return "\n".join(lines)


def main() -> None:
    usage = [
        ("A-1001", 15.0, 10.0),
        ("A-1002", 7.5, 10.0),
        ("A-1003", 10.0, 10.0),
        ("A-1004", 23.25, 20.0),
    ]
    print(report(usage))


if __name__ == "__main__":
    main()

