def validate_grid(
    rows: list[list[int]],
) -> int:
    """Check the grid is rectangular and binary; return the seats per row."""
    if not rows:
        raise ValueError("the seating grid has no rows")
    width = len(rows[0])
    if width == 0:
        raise ValueError("the seating grid has no seats")
    for index, row in enumerate(rows):
        if len(row) != width:
            raise ValueError("row %d has %d seats, expected %d" % (index, len(row), width))
        for seat in row:
            if seat not in (0, 1):
                raise ValueError("row %d contains an invalid seat value %r" % (index, seat))
    return width


def find_empty_runs(
    row: list[int],
) -> list[tuple[int, int]]:
