Profile = tuple[str, list[int], int]
Standing = tuple[str, int]
KNIGHT_BONUS = 2


def resource_points(
    resources: list[int],
) -> int:
    if len(resources) != 3:
        raise ValueError("each player needs counts for wood, brick and sheep")
    if any(count < 0 for count in resources):
        raise ValueError("resource counts cannot be negative")
    return sum(resources) // 3


def knight_counts(
    players: list[Profile],
) -> list[int]:
    counts = [knights for _name, _resources, knights in players]
    if any(knights < 0 for knights in counts):
        raise ValueError("knight counts cannot be negative")
    return counts


def knight_leader(
    players: list[Profile],
) -> int | None:
    counts = knight_counts(players)
    best = max(counts, default=0)
    if best > 2 and counts.count(best) == 1:
        return counts.index(best)
    return None


def player_total(
    profile: Profile,
    bonus: int,
) -> int:
    _name, resources, _knights = profile
    return resource_points(resources) + bonus


def score(
    players: list[Profile],
) -> list[Standing]:
    leader = knight_leader(players)
    return sorted(
        (
            (profile[0], player_total(profile, KNIGHT_BONUS if index == leader else 0))
            for index, profile in enumerate(players)
        ),
        key=lambda entry: entry[1],
        reverse=True,
    )


def format_standings(
    standings: list[Standing],
) -> str:
    width = max((len(name) for name, _points in standings), default=0)
    return "\n".join(
        f"{rank}. {name:<{width}}  {points:>3}"
        for rank, (name, points) in enumerate(standings, start=1)
    )


