from math import floor

RATES: dict[str, float] = {"basic": 10.0, "pro": 20.0, "max": 50.0}
ANNUAL_DISCOUNT: float = 0.15
VOLUME_DISCOUNT: float = 0.10
VOLUME_THRESHOLD: int = 50


def rate_for(
    tier: str,
) -> float:
    key: str = tier.strip().lower()
    if key not in RATES:
        raise ValueError("unknown plan tier: " + tier)
    return RATES[key]


def raw_subtotal(
    tier: str,
    users: int,
) -> float:
    if users < 0:
        raise ValueError("user count cannot be negative")
    return rate_for(tier) * users


def apply_discounts(
    subtotal: float,
    annual: bool,
    users: int,
) -> float:
    amount = subtotal
    if annual:
        amount *= 1.0 - ANNUAL_DISCOUNT
    if users > VOLUME_THRESHOLD:
        amount *= 1.0 - VOLUME_DISCOUNT
    return amount


def line_total(
    subscription: tuple[str, int, bool],
) -> float:
    tier, users, annual = subscription
    subtotal: float = raw_subtotal(tier, users)
    return apply_discounts(subtotal, annual, users)


def invoice(
    subscriptions: list[tuple[str, int, bool]],
) -> int:
    total = 0.0
    for subscription in subscriptions:
        total += line_total(subscription)
    return int(floor(total))


def format_line(
    subscription: tuple[str, int, bool],
) -> str:
    tier, users, annual = subscription
    billing: str = "annual" if annual else "monthly"
    charge: float = line_total(subscription)
    return f"{tier:>5} x{users:<4} {billing:<8} {charge:10.2f}"


def build_report(
    subscriptions: list[tuple[str, int, bool]],
) -> list[str]:
    lines: list[str] = [format_line(sub) for sub in subscriptions]
    lines.append(f"{'TOTAL':>5} {invoice(subscriptions):24d}")
    return lines


def main() -> None:
    clients: list[tuple[str, int, bool]] = [
        ("pro", 10, True),
        ("basic", 60, False),
        ("max", 80, True),
    ]
    for row in build_report(clients):
        print(row)


if __name__ == "__main__":
    main()

