VEHICLE_MINUTES = {"small": 10, "medium": 15, "large": 20}
PACKAGE_MINUTES = {"basic": 0, "premium": 5, "ultimate": 15}
DETAILING_MINUTES = 20
TURNAROUND_MINUTES = 5


def booking_duration(
    booking: tuple[str, str, bool],
) -> int:
    size, package, detailing = booking
    if size not in VEHICLE_MINUTES:
        raise ValueError(f"unknown vehicle size: {size!r}")
    if package not in PACKAGE_MINUTES:
        raise ValueError(f"unknown wash package: {package!r}")
    minutes = VEHICLE_MINUTES[size] + PACKAGE_MINUTES[package]
    if detailing:
        minutes += DETAILING_MINUTES
    return minutes


def timeline(
    bookings: list[tuple[str, str, bool]],
) -> list[tuple[int, int]]:
    spans = []
    clock = 0
    for index, booking in enumerate(bookings):
        if index:
            clock += TURNAROUND_MINUTES
        end = clock + booking_duration(booking)
        spans.append((clock, end))
        clock = end
    return spans


def schedule(
    bookings: list[tuple[str, str, bool]],
) -> tuple[int, int]:
    spans = timeline(bookings)
    active = sum(end - start for start, end in spans)
    closing = spans[-1][1] if spans else 0
    return active, closing


def describe_booking(
    booking: tuple[str, str, bool],
    span: tuple[int, int],
) -> str:
    size, package, detailing = booking
    extras = "with detailing" if detailing else "no detailing"
    start, end = span
    return f"{start:>3}-{end:<3} {size:<6} {package:<8} {extras}"


def format_report(
    bookings: list[tuple[str, str, bool]],
) -> str:
    active, closing = schedule(bookings)
    lines = [
        describe_booking(booking, span)
        for booking, span in zip(bookings, timeline(bookings))
    ]
    lines.append(f"active washing minutes: {active}")
    lines.append(f"bay closes at minute: {closing}")
    return "\n".join(lines)


def main() -> None:
    day = [
        ("small", "basic", False),
        ("large", "ultimate", True),
        ("medium", "premium", False),
    ]
    print(format_report(day[:2]))
    print()
    print(format_report(day))


if __name__ == "__main__":
    main()

