from __future__ import annotations

from decimal import Decimal, ROUND_HALF_UP

PEAK_RATE = Decimal("0.15")
OFF_PEAK_RATE = Decimal("0.08")
WATTS_PER_KILOWATT = Decimal("1000")


def _as_decimal(
    value: float,
    label: str,
) -> Decimal:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError(f"{label} must be a number, got {type(value).__name__}")
    number = Decimal(str(value))
    if number < 0:
        raise ValueError(f"{label} must not be negative")
    return number


def unpack_device(
    device: tuple[float, float, float],
) -> tuple[Decimal, Decimal, Decimal]:
    if len(device) != 3:
        raise ValueError("each device needs power, peak hours and off peak hours")
    power, peak_hours, off_peak_hours = device
    return (
        _as_decimal(power, "power rating"),
        _as_decimal(peak_hours, "peak hours"),
        _as_decimal(off_peak_hours, "off peak hours"),
    )


def energy_split(
    power_watts: Decimal,
    peak_hours: Decimal,
    off_peak_hours: Decimal,
) -> tuple[Decimal, Decimal]:
    kilowatts = power_watts / WATTS_PER_KILOWATT
    return kilowatts * peak_hours, kilowatts * off_peak_hours


def device_cost(
    device: tuple[float, float, float],
) -> Decimal:
    power, peak_hours, off_peak_hours = unpack_device(device)
    peak_energy, off_peak_energy = energy_split(power, peak_hours, off_peak_hours)
    return peak_energy * PEAK_RATE + off_peak_energy * OFF_PEAK_RATE


def to_currency(
    amount: Decimal,
) -> float:
    return float(amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))


def evaluate(
    devices: list[tuple[float, float, float]],
) -> float:
    total = sum((device_cost(device) for device in devices), Decimal("0"))
    return to_currency(total)


def format_report(
    devices: list[tuple[float, float, float]],
) -> str:
    lines = []
    for index, device in enumerate(devices, start=1):
        cost = to_currency(device_cost(device))
        lines.append(f"Device {index}: {device[0]:g} W costs ${cost:.2f} per day")
    lines.append(f"Total daily cost: ${evaluate(devices):.2f}")
    return "\n".join(lines)


def main() -> None:
    household = [
        (2000, 2, 4),
        (100, 5, 5),
        (1200, 0.5, 1.5),
    ]
    print(format_report(household))


if __name__ == "__main__":
    main()

