def validate_splits(
    splits: list[float],
) -> None:
    """Reject inputs that cannot describe a real run."""
    if not splits:
        raise ValueError("at least one kilometre split is required")
    for index, split in enumerate(splits, start=1):
        if split <= 0:
            raise ValueError(f"split {index} must be positive, got {split!r}")


def split_halves(
    splits: list[float],
) -> tuple[list[float], list[float]]:
    """Cut the run in two, the middle kilometre joining the first half."""
    middle = (len(splits) + 1) // 2
    return splits[:middle], splits[middle:]


def mean(
    values: list[float],
) -> float:
    return sum(values) / len(values)


def fatigue_gap(
    first_half: list[float],
    second_half: list[float],
) -> float:
    if not second_half:
        return 0.0
    return mean(second_half) - mean(first_half)


def classify(
    difference: float,
) -> str:
    if difference > 10:
        return "severe fatigue"
    if difference < 0:
        return "negative split"
    return "steady pace"


def pace(
    splits: list[float],
) -> tuple[float, str]:
    validate_splits(splits)
    first_half, second_half = split_halves(list(splits))
    difference = fatigue_gap(first_half, second_half)
    return round(mean(list(splits)), 1), classify(difference)


def format_time(
    seconds: float,
) -> str:
    minutes, rest = divmod(seconds, 60)
    return f"{int(minutes)}:{rest:04.1f}"


def format_report(
    splits: list[float],
    result: tuple[float, str],
) -> str:
    average, verdict = result
    return (
        f"{len(splits)} km | avg {format_time(average)} /km "
        f"({average} s) | {verdict}"
    )


def main() -> None:
    runs: list[list[float]] = [
        [300, 310, 330, 340],
        [290, 288, 285, 280, 275],
        [301, 299, 300],
    ]
    for run in runs:
        print(format_report(run, pace(run)))


if __name__ == "__main__":
    main()

