import math


def ph_shift(
    current: float,
    target: float,
) -> float:
    return abs(current - target)


def buffer_for_tank(
    volume: float,
    current: float,
    target: float,
) -> float:
    return (ph_shift(current, target) / 0.1) * (volume / 10.0)


def validate_tank(
    tank: tuple[float, float, float],
) -> tuple[float, float, float]:
    if len(tank) != 3:
        raise ValueError(f"each tank needs volume, current ph and target ph: {tank!r}")
    volume, current, target = (float(value) for value in tank)
    if volume <= 0:
        raise ValueError(f"tank volume must be positive, got {volume}")
    for level in (current, target):
        if not 0.0 <= level <= 14.0:
            raise ValueError(f"ph level out of range: {level}")
    return volume, current, target


def adjust(
    tanks: list[tuple[float, float, float]],
) -> int:
    total = 0.0
    for tank in tanks:
        volume, current, target = validate_tank(tank)
        total += buffer_for_tank(volume, current, target)
    return math.ceil(total)


def describe_tank(
    index: int,
    tank: tuple[float, float, float],
) -> str:
    volume, current, target = validate_tank(tank)
    millilitres = buffer_for_tank(volume, current, target)
    if math.isclose(current, target):
        direction = "hold"
    else:
        direction = "raise" if target > current else "lower"
    return (
        f"Tank {index}: {volume:g} L, {direction} ph {current:g} -> {target:g}, "
        f"{millilitres:.1f} mL buffer"
    )


def report(
    tanks: list[tuple[float, float, float]],
) -> str:
    lines = [describe_tank(i, tank) for i, tank in enumerate(tanks, start=1)]
    lines.append(f"Total buffer required: {adjust(tanks)} mL")
    return "\n".join(lines)


def main() -> None:
    schedule = [
        (50, 7.0, 7.2),
        (100, 6.5, 6.8),
        (200, 8.1, 7.6),
        (30, 7.0, 7.0),
    ]
    print(report(schedule))


if __name__ == "__main__":
    main()

