TIME_LIMIT_MINUTES = 60
HINT_PENALTY = 2


def base_score(
    minutes: int,
) -> int:
    """Return sixty minus the minutes taken, or zero when the team failed."""
    if minutes >= TIME_LIMIT_MINUTES:
        return 0
    return TIME_LIMIT_MINUTES - minutes


def apply_penalty(
    base: int,
    hints: int,
) -> int:
    """Deduct two points per hint, keeping escaping teams at a minimum of one."""
    if base == 0:
        return 0
    penalised = base - HINT_PENALTY * hints
    if penalised < 1:
        return 1
    return penalised


def validate_entry(
    entry: tuple,
) -> tuple[str, int, int]:
    """Unpack one team record, rejecting malformed or negative values."""
    if len(entry) != 3:
        raise ValueError(f"expected (name, minutes, hints), got {entry!r}")
    name, minutes, hints = entry
    if minutes < 0 or hints < 0:
        raise ValueError(f"negative minutes or hints for team {name!r}")
    return str(name), int(minutes), int(hints)


def score_team(
    entry: tuple,
) -> tuple[str, int]:
    """Compute the final score of a single team record."""
    name, minutes, hints = validate_entry(entry)
    return name, apply_penalty(base_score(minutes), hints)


def score_all(
    teams: list[tuple],
) -> list[tuple[str, int]]:
    """Score every team, preserving the original ordering."""
    return [score_team(entry) for entry in teams]


def rank(
    teams: list[tuple],
) -> list[str]:
    """Return the team names ordered by final score, highest first."""
    scored = score_all(teams)
    scored.sort(key=lambda pair: pair[1], reverse=True)
    return [name for name, _score in scored]


def format_report(
    teams: list[tuple],
) -> str:
    """Render a one-line-per-team scoreboard with placements and scores."""
    scores = dict(score_all(teams))
    lines = []
    for place, name in enumerate(rank(teams), start=1):
        score = scores[name]
        status = "failed" if score == 0 else "escaped"
        lines.append(f"{place}. {name:<10} {score:>3} ({status})")
    return "\n".join(lines)


def main() -> None:
    competition = [
        ("alpha", 45, 1),
        ("beta", 60, 0),
        ("gamma", 20, 25),
        ("delta", 31, 3),
    ]
    print(rank(competition))
    print(format_report(competition))


if __name__ == "__main__":
    main()

