RATES = {"standard": 100, "gold": 90, "platinum": 80}


def exchange_rate(
    tier: str,
) -> int:
    """Return the number of points needed to buy one dollar for a tier."""
    key = tier.strip().lower()
    if key not in RATES:
        raise ValueError(f"unknown membership tier: {tier!r}")
    return RATES[key]


def points_required(
    tier: str,
    dollars: int,
) -> int:
    """Points consumed by redeeming the given dollar amount."""
    if dollars < 0:
        raise ValueError("redemption amount cannot be negative")
    return dollars * exchange_rate(tier)


def redeem_one(
    balance: int,
    tier: str,
    dollars: int,
) -> int:
    """Return the balance after a single redemption attempt."""
    if balance < 0:
        raise ValueError("point balance cannot be negative")
    cost = points_required(tier, dollars)
    if cost > balance:
        return balance
    return balance - cost


def redeem(
    accounts: list[tuple[int, str, int]],
) -> list[int]:
    """Process every account and return the final balances in order."""
    return [redeem_one(balance, tier, dollars) for balance, tier, dollars in accounts]


def describe(
    account: tuple[int, str, int],
    final_balance: int,
) -> str:
    """Build a one-line human readable summary of one redemption."""
    balance, tier, dollars = account
    cost = points_required(tier, dollars)
    outcome = "declined" if cost > balance else "approved"
    return (
        f"{tier.lower():<9} ${dollars:>3} costs {cost:>5} pts | "
        f"{balance:>5} -> {final_balance:>5} ({outcome})"
    )


def report(
    accounts: list[tuple[int, str, int]],
) -> str:
    """Render a full report for a batch of redemption requests."""
    finals = redeem(accounts)
    lines = [describe(account, final) for account, final in zip(accounts, finals)]
    total_spent = sum(a[0] - f for a, f in zip(accounts, finals))
    lines.append(f"total points spent: {total_spent}")
    return "\n".join(lines)


def main() -> None:
    batch = [
        (500, "gold", 5),
        (300, "standard", 4),
        (1000, "platinum", 12),
        (960, "gold", 10),
    ]
    print(redeem(batch))
    print(report(batch))


if __name__ == "__main__":
    main()

