from math import ceil

FLOUR_GRAMS: dict[str, int] = {"bread": 500, "cake": 300, "pastry": 150}
OVEN_CAPACITY: dict[str, int] = {"bread": 4, "cake": 2, "pastry": 10}


def validate_order(
    item: str,
    quantity: int,
) -> None:
    if item not in FLOUR_GRAMS:
        raise ValueError(f"unknown item type: {item!r}")
    if quantity < 0:
        raise ValueError(f"quantity for {item} must not be negative")


def flour_for(
    item: str,
    quantity: int,
) -> int:
    validate_order(item, quantity)
    return FLOUR_GRAMS[item] * quantity


def batches_for(
    item: str,
    quantity: int,
) -> int:
    validate_order(item, quantity)
    return ceil(quantity / OVEN_CAPACITY[item])


def plan(
    orders: list[tuple[str, int]],
) -> tuple[float, int]:
    total_grams: int = 0
    total_batches: int = 0
    for item, quantity in orders:
        total_grams += flour_for(item, quantity)
        total_batches += batches_for(item, quantity)
    return round(total_grams / 1000, 3), total_batches


def merge_orders(
    orders: list[tuple[str, int]],
) -> dict[str, int]:
    merged: dict[str, int] = {}
    for item, quantity in orders:
        validate_order(item, quantity)
        merged[item] = merged.get(item, 0) + quantity
    return merged


def format_report(
    orders: list[tuple[str, int]],
) -> str:
    totals: dict[str, int] = merge_orders(orders)
    flour_kg, batches = plan(orders)
    lines: list[str] = ["Daily bakery plan:"]
    for item in sorted(totals):
        quantity: int = totals[item]
        grams: int = flour_for(item, quantity)
        lines.append(f"  {item}: {quantity} ordered, {grams} g flour")
    lines.append(f"Total flour: {flour_kg} kg")
    lines.append(f"Total oven batches: {batches}")
    return "\n".join(lines)


def main() -> None:
    orders: list[tuple[str, int]] = [
        ("bread", 5),
        ("cake", 3),
        ("pastry", 22),
        ("bread", 2),
    ]
    print(format_report(orders))


if __name__ == "__main__":
    main()

