def validate_weights(
    containers: list,
) -> list[float]:
    """Check every entry is a non-negative number and collect the weights."""
    weights: list[float] = []
    for index, value in enumerate(containers):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(f"container {index} is not a numeric weight: {value!r}")
        if value < 0:
            raise ValueError(f"container {index} has a negative weight: {value}")
        weights.append(value)
    return weights


def sort_heaviest_first(
    weights: list[float],
) -> list[float]:
    """Order the containers from heaviest to lightest."""
    return sorted(weights, reverse=True)


def assign_sides(
    weights: list[float],
) -> tuple[list[float], list[float]]:
    """Greedily place each container on the currently lighter side."""
    port: list[float] = []
    starboard: list[float] = []
    port_total: float = 0
    starboard_total: float = 0
    for weight in sort_heaviest_first(weights):
        if starboard_total < port_total:
            starboard.append(weight)
            starboard_total += weight
        else:
            port.append(weight)
            port_total += weight
    return port, starboard


def balance(
    containers: list,
) -> float:
    """Return the absolute weight difference between port and starboard."""
    port, starboard = assign_sides(validate_weights(containers))
    return abs(sum(port) - sum(starboard))


def describe_side(
    name: str,
    side: list[float],
) -> str:
    """Render one side of the ship as a readable line."""
    listing: str = ", ".join(str(weight) for weight in side) or "empty"
    return f"{name:>9}: {sum(side)} t ({listing})"


def format_report(
    containers: list,
) -> str:
    """Build a small loading report for the given containers."""
    port, starboard = assign_sides(validate_weights(containers))
    lines: list[str] = [
        describe_side("port", port),
        describe_side("starboard", starboard),
        f"{'tilt':>9}: {abs(sum(port) - sum(starboard))} t",
    ]
    return "\n".join(lines)


def main() -> None:
    cargo: list[float] = [10, 20, 15, 5]
    print(balance(cargo))
    print(format_report(cargo))
    uneven: list[float] = [48, 31, 27, 19, 12, 7, 3]
    print(balance(uneven))
    print(format_report(uneven))


if __name__ == "__main__":
    main()

