) -> tuple[str, str, int, str]:
    name, housing, hours, size = application
    housing_key = normalize_field(housing)
    size_key = normalize_field(size)
    if housing_key not in HOUSING_TYPES:
        raise ValueError("unknown housing type: {!r}".format(housing))
    if size_key not in BREED_SIZES:
        raise ValueError("unknown breed size: {!r}".format(size))
    weekly_hours = int(hours)
    if weekly_hours < 0:
        raise ValueError("weekly working hours cannot be negative")
    return name.strip(), housing_key, weekly_hours, size_key


def is_oversized_for_home(
    housing: str,
    size: str,
) -> bool:
    return size == "large" and housing == "apartment"


def works_too_much(
    weekly_hours: int,
) -> bool:
    return weekly_hours > HOURS_CAP


def too_busy_for_big_breed(
    weekly_hours: int,
    size: str,
) -> bool:
    return size in {"medium", "large"} and weekly_hours > BIG_BREED_HOURS_CAP


def rejection_reason(
    housing: str,
    weekly_hours: int,
    size: str,
) -> str | None:
    if is_oversized_for_home(housing, size):
        return "a large breed needs more space than an apartment"
    if works_too_much(weekly_hours):
        return "works more than {} hours a week".format(HOURS_CAP)
    if too_busy_for_big_breed(weekly_hours, size):
        return "a {} breed needs an owner home more often".format(size)
    return None


