MEMBER_RATE = 5
DROP_IN_RATE = 18
CROWDING_LIMIT = 20
CROWDING_PENALTY = 15


def raw_earnings(
    members: int,
    drop_ins: int,
) -> int:
    return members * MEMBER_RATE + drop_ins * DROP_IN_RATE


def penalty_for(
    attendance: int,
) -> int:
    if attendance > CROWDING_LIMIT:
        return CROWDING_PENALTY
    return 0


def class_earnings(
    entry: tuple[str, int, int],
) -> int:
    _, members, drop_ins = entry
    if members < 0 or drop_ins < 0:
        raise ValueError("attendance counts cannot be negative")
    return raw_earnings(members, drop_ins) - penalty_for(members + drop_ins)


def revenue(
    classes: list[tuple[str, int, int]],
) -> int:
    return sum(class_earnings(entry) for entry in classes)


def describe_class(
    entry: tuple[str, int, int],
) -> str:
    name, members, drop_ins = entry
    attendance = members + drop_ins
    earned = class_earnings(entry)
    note = " (overcrowded)" if attendance > CROWDING_LIMIT else ""
    return f"{name:<8} {attendance:>3} students -> ${earned}{note}"


def build_report(
    classes: list[tuple[str, int, int]],
) -> list[str]:
    lines = [describe_class(entry) for entry in classes]
    lines.append(f"{'TOTAL':<8} {'':>3}          -> ${revenue(classes)}")
    return lines


def busiest_instructor(
    classes: list[tuple[str, int, int]],
) -> str:
    if not classes:
        raise ValueError("no classes to rank")
    best = max(classes, key=lambda entry: entry[1] + entry[2])
    return best[0]


def main() -> None:
    schedule = [
        ('anna', 10, 5),
        ('ben', 15, 10),
        ('cleo', 4, 2),
        ('dara', 20, 3),
    ]
    for line in build_report(schedule):
        print(line)
    print("busiest:", busiest_instructor(schedule))


if __name__ == "__main__":
    main()

