ADULT_RATE = 20
SENIOR_RATE = 15
STUDENT_RATE = 12
GUIDE_RATE = 5
CHILD_AGE = 12
SENIOR_AGE = 65


def parse_visitor(
    raw: tuple[object, ...]
) -> tuple[int, bool, bool]:
    if len(raw) != 3:
        raise ValueError(f"a visitor needs (age, student, guide), got {raw!r}")
    age, student, guide = raw
    if not isinstance(age, int) or isinstance(age, bool):
        raise TypeError(f"age must be an int, got {age!r}")
    if age < 0:
        raise ValueError(f"age cannot be negative, got {age}")
    if not isinstance(student, bool) or not isinstance(guide, bool):
        raise TypeError(f"student and guide flags must be booleans in {raw!r}")
    return age, student, guide


def base_price(
    age: int,
    is_student: bool
) -> int:
    if age < CHILD_AGE:
        return 0
    if age >= SENIOR_AGE:
        return SENIOR_RATE
    if is_student:
        return STUDENT_RATE
    return ADULT_RATE


def guide_price(
    age: int,
    wants_guide: bool
) -> int:
    if not wants_guide or age < CHILD_AGE:
        return 0
    return GUIDE_RATE


def visitor_cost(
    visitor: tuple[object, ...]
) -> int:
    age, is_student, wants_guide = parse_visitor(visitor)
    return base_price(age, is_student) + guide_price(age, wants_guide)


def admission(
    visitors: list[tuple[object, ...]]
) -> int:
    return sum(visitor_cost(visitor) for visitor in visitors)


def describe_visitor(
    visitor: tuple[object, ...]
) -> str:
    age, is_student, wants_guide = parse_visitor(visitor)
    if age < CHILD_AGE:
        label = "child"
    elif age >= SENIOR_AGE:
        label = "senior"
    elif is_student:
        label = "student"
    else:
        label = "adult"
    extra = " + guide" if wants_guide else ""
    return f"{label} ({age}){extra}: ${visitor_cost(visitor)}"


def format_receipt(
    visitors: list[tuple[object, ...]]
) -> str:
    lines = [describe_visitor(visitor) for visitor in visitors]
    lines.append(f"TOTAL: ${admission(visitors)}")
    return "\n".join(lines)


def main() -> None:
    print(format_receipt([
        (10, True, True),
        (70, False, True),
        (21, True, False),
        (34, False, True),
    ]))


if __name__ == "__main__":
    main()

