import math


FIRST_HOUR_RATE = 4.0
EXTRA_HOUR_RATE = 3.0
DAILY_MAXIMUM = 25.0
VALIDATION_FACTORS = {"none": 1.0, "half": 0.5, "full": 0.0}


def billable_hours(
    hours: float,
) -> int:
    if hours < 0:
        raise ValueError(f"hours parked cannot be negative: {hours}")
    return math.ceil(hours)


def base_cost(
    hours: float,
) -> float:
    whole_hours = billable_hours(hours)
    if whole_hours == 0:
        return 0.0
    fee = FIRST_HOUR_RATE + EXTRA_HOUR_RATE * (whole_hours - 1)
    return min(fee, DAILY_MAXIMUM)


def validation_factor(
    validation: str,
) -> float:
    key = validation.strip().lower()
    if key not in VALIDATION_FACTORS:
        raise ValueError(f"unknown validation type: {validation!r}")
    return VALIDATION_FACTORS[key]


def ticket_fee(
    ticket: tuple[float, str],
) -> float:
    hours, validation = ticket
    return base_cost(hours) * validation_factor(validation)


def charge(
    tickets: list[tuple[float, str]],
) -> float:
    return sum(ticket_fee(ticket) for ticket in tickets)


def format_money(
    amount: float,
) -> str:
    return f"${amount:,.2f}"


def describe_ticket(
    ticket: tuple[float, str],
) -> str:
    hours, validation = ticket
    gross = base_cost(hours)
    net = ticket_fee(ticket)
    return (
        f"{hours:>5.1f}h billed as {billable_hours(hours)}h  "
        f"base {format_money(gross)}  {validation:<4} -> {format_money(net)}"
    )


def build_report(
    tickets: list[tuple[float, str]],
) -> str:
    lines = [describe_ticket(ticket) for ticket in tickets]
    lines.append(f"{'TOTAL':>35}: {format_money(charge(tickets))}")
    return "\n".join(lines)


def main() -> None:
    shift = [(2.5, "none"), (10.0, "half"), (0.25, "none"), (8.0, "full")]
    print(build_report(shift))


if __name__ == "__main__":
    main()

