from __future__ import annotations

OVERWEIGHT_FEE = 50
EXTRA_BAG_FEE = 75


def policy(
    ticket_class: str,
) -> tuple[int, int]:
    """Return the free bag count and the per-bag weight limit in kilograms."""
    normalized = ticket_class.strip().lower()
    if normalized == "economy":
        return 1, 20
    if normalized == "business":
        return 2, 30
    raise ValueError(f"unknown ticket class: {ticket_class!r}")


def bag_fee(
    weight: float,
    limit: int,
    beyond_free: bool,
) -> int:
    """Fee for a single bag, given whether it sits outside the free allowance."""
    if weight < 0:
        raise ValueError(f"bag weight cannot be negative: {weight}")
    fee = EXTRA_BAG_FEE if beyond_free else 0
    if weight > limit:
        fee += OVERWEIGHT_FEE
    return fee


def passenger_fee(
    ticket_class: str,
    weights: list[float],
) -> int:
    free_count, limit = policy(ticket_class)
    total = 0
    for index, weight in enumerate(weights):
        total += bag_fee(weight, limit, index >= free_count)
    return total


def allowance(
    passengers: list[tuple[str, list[float]]],
) -> int:
    return sum(passenger_fee(ticket_class, weights) for ticket_class, weights in passengers)


def describe(
    seat: int,
    ticket_class: str,
    weights: list[float],
) -> str:
    fee = passenger_fee(ticket_class, weights)
    bags = ", ".join(f"{weight:g}kg" for weight in weights) or "no bags"
    return f"#{seat} {ticket_class:<8} [{bags}] -> ${fee}"


def main() -> None:
    flight: list[tuple[str, list[float]]] = [
        ("economy", [25, 10]),
        ("business", [30, 31, 15]),
        ("economy", []),
    ]
    for seat, (ticket_class, weights) in enumerate(flight, start=1):
        print(describe(seat, ticket_class, weights))
    print(f"total baggage fees: ${allowance(flight)}")


if __name__ == "__main__":
    main()

