BASE_RATE = 80.0
CHILD_RATE = 40.0
SENIOR_RATE = 60.0
RENTAL_RATE = 30.0
MULTI_DAY_THRESHOLD = 3
MULTI_DAY_DISCOUNT = 0.10


def daily_rate(
    age: int,
) -> float:
    if age < 16:
        return CHILD_RATE
    if age > 70:
        return SENIOR_RATE
    return BASE_RATE


def discounted_rate(
    rate: float,
    days: int,
) -> float:
    if days >= MULTI_DAY_THRESHOLD:
        return rate * (1.0 - MULTI_DAY_DISCOUNT)
    return rate


def skier_cost(
    age: int,
    days: int,
