from math import sqrt

MAX_MASS = 50.0
MIN_PRIORITY = 10
FLEET_SIZE = 3


def validate_payload(
    payload: tuple[str, float, int],
) -> tuple[str, float, int]:
    name, mass, priority = payload
    if not isinstance(name, str) or not name.strip():
        raise ValueError("instrument name must be a non-empty string")
    if mass <= 0:
        raise ValueError(f"{name}: mass must be positive")
    return name.strip(), float(mass), int(priority)


def is_flightworthy(
    payload: tuple[str, float, int],
) -> bool:
    _, mass, priority = payload
    return mass <= MAX_MASS and priority >= MIN_PRIORITY


def filter_payloads(
    payloads: list[tuple[str, float, int]],
) -> list[tuple[str, float, int]]:
    checked = [validate_payload(entry) for entry in payloads]
    return [entry for entry in checked if is_flightworthy(entry)]


def utility_score(
    payload: tuple[str, float, int],
) -> float:
    _, mass, priority = payload
    return priority / sqrt(mass)


def score_payloads(
    payloads: list[tuple[str, float, int]],
) -> list[tuple[str, float]]:
    return [(entry[0], utility_score(entry)) for entry in payloads]


def rank_payloads(
    scored: list[tuple[str, float]],
) -> list[tuple[str, float]]:
    return sorted(scored, key=lambda item: item[1], reverse=True)


def select_names(
    ranked: list[tuple[str, float]],
    limit: int = FLEET_SIZE,
) -> list[str]:
    return [name for name, _ in ranked[:limit]]


def optimize(
    payloads: list[tuple[str, float, int]],
) -> list[str]:
    return select_names(rank_payloads(score_payloads(filter_payloads(payloads))))


def format_manifest(
    selection: list[str],
) -> str:
    if not selection:
        return "Manifest: no instrument met the mission constraints."
    listing = ", ".join(f"{index}. {name}" for index, name in enumerate(selection, 1))
    return f"Manifest ({len(selection)} instruments): {listing}"


