    manifest: list[tuple[str, float, int]] = [
        ("spectrometer", 45.0, 85),
        ("telescope", 60.0, 90),
        ("camera", 5.0, 15),
        ("magnetometer", 12.0, 40),
        ("dust counter", 8.0, 9),
    ]
    chosen: list[str] = optimize(manifest)
    print(format_manifest(chosen))


if __name__ == "__main__":
    main()

