MIN_ECHO_MS = 100
MAX_ECHO_MS = 10_000
METERS_PER_MS = 1.5
SHALLOW_LIMIT = 500.0
MEDIUM_LIMIT = 2000.0
CATEGORIES = ("shallow", "medium", "deep")


def validate_echoes(
    raw: object,
) -> list[int]:
    """Ensure the input is a sequence of plain integer millisecond readings."""
    if not isinstance(raw, (list, tuple)):
        raise TypeError("echoes must be a list or tuple of integers")
    checked: list[int] = []
    for value in raw:
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError(f"invalid echo reading: {value!r}")
        checked.append(value)
    return checked


def filter_noise(
    echoes: list[int],
) -> list[int]:
    """Drop readings outside the usable sonar window."""
    return [t for t in echoes if MIN_ECHO_MS <= t <= MAX_ECHO_MS]


def to_distances(
    echo_times: list[int],
) -> list[float]:
    """Convert millisecond return times into estimated distances in meters."""
    return [t * METERS_PER_MS for t in echo_times]


def classify_depth(
    distance: float,
) -> str:
    if distance < SHALLOW_LIMIT:
        return "shallow"
    if distance < MEDIUM_LIMIT:
        return "medium"
    return "deep"


def group_by_depth(
    distances: list[float],
) -> dict[str, int]:
    counts: dict[str, int] = {name: 0 for name in CATEGORIES}
    for distance in distances:
        counts[classify_depth(distance)] += 1
    return counts


def analyze(
    echoes: list[int],
) -> tuple[int, int, int]:
    """Full pipeline: validate, denoise, convert to meters, then group."""
    readings = validate_echoes(echoes)
    clean = filter_noise(readings)
    distances = to_distances(clean)
    counts = group_by_depth(distances)
    return counts["shallow"], counts["medium"], counts["deep"]


def format_report(
    counts: tuple[int, int, int],
) -> str:
    parts = [f"{name}={count}" for name, count in zip(CATEGORIES, counts)]
    return f"total={sum(counts)} | " + ", ".join(parts)


def main(
) -> None:
    surveys: dict[str, list[int]] = {
        "bay-mouth": [50, 150, 600, 12000],
        "shelf-edge": [99, 100, 333, 1400, 9999, 10001],
    }
    for name, echoes in surveys.items():
        result = analyze(echoes)
        print(f"{name}: {result} -> {format_report(result)}")


if __name__ == "__main__":
    main()

