from collections import Counter

CORRECTION_MASK = 42


def validate_syndrome(
    syndrome: str,
) -> str:
    stripped = syndrome.strip()
    if not stripped:
        raise ValueError("syndrome string must not be empty")
    invalid = set(stripped) - {"0", "1"}
    if invalid:
        raise ValueError(f"syndrome {syndrome!r} contains non-binary digits")
    return stripped


def to_int(
    syndrome: str,
) -> int:
    return int(validate_syndrome(syndrome), 2)


def apply_mask(
    value: int,
    mask: int = CORRECTION_MASK,
) -> int:
    return value ^ mask


def map_error(
    location: int,
) -> str:
    if location % 2 == 0:
        return "phase flip"
    return "bit flip"


def decode(
    syndromes: list[str],
) -> list[str]:
    return [map_error(apply_mask(to_int(syndrome))) for syndrome in syndromes]


def describe_syndrome(
    syndrome: str,
) -> str:
    value = to_int(syndrome)
    location = apply_mask(value)
    return f"{syndrome:>8} -> value {value:3d} -> location {location:3d} -> {map_error(location)}"


def build_report(
    syndromes: list[str],
) -> str:
    return "\n".join(describe_syndrome(syndrome) for syndrome in syndromes)


def summarise(
    errors: list[str],
) -> dict[str, int]:
    return dict(Counter(errors))


def main() -> None:
    measurements = ["101010", "101011", "000000", "111111", "1", "10"]
    print(build_report(measurements))
    decoded = decode(measurements)
    print(decoded)
    for error, count in sorted(summarise(decoded).items()):
        print(f"{error}: {count}")


if __name__ == "__main__":
    main()

