MAX_TARGET_DISTANCE = 120.0


def valid_shots(
    distances: list[float],
) -> list[float]:
    """Keep only the distances that actually landed on the target board."""
    return [d for d in distances if d <= MAX_TARGET_DISTANCE]


def shot_points(
    distance: float,
) -> int:
    """Convert a single valid distance in centimetres into contest points."""
    if distance < 10.0:
        return 10
    if distance < 30.0:
        return 5
    if distance < 60.0:
        return 1
    return 0


def total_points(
    distances: list[float],
) -> int:
    """Sum the points of every shot that hit the board."""
    return sum(shot_points(d) for d in valid_shots(distances))


def tally(
    shots: list[tuple[str, list[float]]],
) -> dict[str, int]:
    """Build a name -> score mapping, merging repeated appearances of a name."""
    scores: dict[str, int] = {}
    for name, distances in shots:
        scores[name] = scores.get(name, 0) + total_points(distances)
    return scores


def rank(
    scores: dict[str, int],
) -> list[str]:
    """Order archers by descending score, then alphabetically by name."""
    return sorted(scores, key=lambda name: (-scores[name], name))


def score(
    shots: list[tuple[str, list[float]]],
) -> list[str]:
    """Final standings of the archery contest, best archer first."""
    return rank(tally(shots))


def format_standings(
    scores: dict[str, int],
) -> str:
    """Render the standings as a numbered, human readable scoreboard."""
    lines: list[str] = []
    for position, name in enumerate(rank(scores), start=1):
        lines.append(f"{position}. {name} - {scores[name]} pts")
    return "\n".join(lines)


def main() -> None:
    contest: list[tuple[str, list[float]]] = [
        ("Robin", [5.0, 25.0, 50.0]),
