from __future__ import annotations

MIN_MASS_MEGATONS = 500.0

Scan = tuple[str, float, list[float]]
Result = tuple[str, float]


def mean_index(
    readings: list[float],
) -> float:
    """Average the spectral readings into a primary ore concentration index."""
    if not readings:
        raise ValueError("spectral scan contains no readings")
    return sum(readings) / len(readings)


def project_mass(
    index: float,
    volume: float,
) -> float:
    """Project extractable ore mass in megatons from index and volume."""
    if volume < 0.0:
        raise ValueError("volume must not be negative")
    return index * volume


def summarize_scan(
    scan: Scan,
) -> Result:
    """Pair an asteroid name with its unrounded projected ore mass."""
    name, volume, readings = scan
    return name, project_mass(mean_index(readings), volume)


def qualifies(
    result: Result,
) -> bool:
    return result[1] >= MIN_MASS_MEGATONS


def sort_by_mass(
    results: list[Result],
) -> list[Result]:
    return sorted(results, key=lambda item: item[1], reverse=True)


def estimate(
    scans: list[Scan],
) -> list[Result]:
    summaries = [summarize_scan(scan) for scan in scans]
    ranked = sort_by_mass([result for result in summaries if qualifies(result)])
    return [(name, round(mass, 1)) for name, mass in ranked]


def format_row(
    rank: int,
    result: Result,
) -> str:
    name, mass = result
    return f"{rank:>2}. {name:<12} {mass:>10.1f} Mt"


def build_report(
    results: list[Result],
) -> str:
    if not results:
        return "No prospect meets the 500 Mt threshold."
    lines = ["Rank Asteroid           Projected"]
    for rank, result in enumerate(results, start=1):
        lines.append(format_row(rank, result))
    return "\n".join(lines)


def main() -> None:
    scans = [
        ("Ceres", 100.5, [4.2, 5.1, 4.8]),
        ("Pallas", 12.0, [3.9, 4.1]),
        ("Vesta", 80.25, [7.4, 6.9, 7.1, 7.6]),
        ("Juno", 45.0, [11.2, 10.8, 11.5]),
    ]
    print(build_report(estimate(scans)))


if __name__ == "__main__":
    main()

