    return checked


def geographic_center(
    fleet: list[tuple[str, tuple[int, int, int]]],
) -> tuple[float, float, float]:
    count = len(fleet)
    totals = [0, 0, 0]
    for _, position in fleet:
        for axis in range(3):
            totals[axis] += position[axis]
    return (totals[0] / count, totals[1] / count, totals[2] / count)


def euclidean_distance(
    position: tuple[int, int, int],
    center: tuple[float, float, float],
) -> float:
    return sqrt(sum((position[axis] - center[axis]) ** 2 for axis in range(3)))


def within_radius(
    fleet: list[tuple[str, tuple[int, int, int]]],
    center: tuple[float, float, float],
    radius: float = MAX_RADIUS,
) -> list[str]:
