BASES = frozenset("ACTG")


def is_valid_fragment(
    fragment: str,
) -> bool:
    return len(fragment) > 0 and set(fragment) <= BASES


def gc_content(
    fragment: str,
) -> float:
    gc_count = fragment.count("G") + fragment.count("C")
    return gc_count / len(fragment)


def filter_fragments(
    fragments: list[str],
) -> list[str]:
    return [fragment for fragment in fragments if is_valid_fragment(fragment)]


def sort_by_gc_content(
    fragments: list[str],
) -> list[str]:
    return sorted(fragments, key=gc_content, reverse=True)


def assemble(
    fragments: list[str],
) -> str:
    return "".join(fragments)


def sequence(
    fragments: list[str],
) -> tuple[str, int]:
    valid = filter_fragments(fragments)
    ordered = sort_by_gc_content(valid)
    assembled = assemble(ordered)
    return assembled, len(assembled)


def describe_fragment(
    fragment: str,
) -> str:
    return f"{fragment} (GC={gc_content(fragment):.2f})"


def build_report(
    fragments: list[str],
) -> str:
    valid = filter_fragments(fragments)
    rejected = [fragment for fragment in fragments if fragment not in valid]
    lines = [describe_fragment(fragment) for fragment in sort_by_gc_content(valid)]
    if rejected:
        lines.append("rejected: " + ", ".join(repr(item) for item in rejected))
    assembled, total = sequence(fragments)
    lines.append(f"assembly: {assembled} length={total}")
    return "\n".join(lines)


def main() -> None:
    samples: list[list[str]] = [
        ["ACGT", "GGCC"],
        ["ATAT", "GCGC", "ACGX", "", "TTGC"],
        ["AAAA", "CCCC", "ACTG"],
    ]
    for index, sample in enumerate(samples, start=1):
        print(f"--- sample {index} ---")
        print(build_report(sample))


if __name__ == "__main__":
    main()

