Ingredient = tuple[str, float, float]
NoteGroups = dict[str, list[str]]
NoteTotals = dict[str, float]

TOP_TARGET = 20.0
HEART_TARGET = 50.0
BASE_TARGET = 30.0
TOLERANCE = 1e-9


def classify_note(evaporation_rate: float) -> str:
    if evaporation_rate > 50.0:
        return "top"
    if evaporation_rate >= 20.0:
        return "heart"
    return "base"


def validate_ingredient(ingredient: Ingredient) -> Ingredient:
    name, rate, concentration = ingredient
    if not str(name).strip():
        raise ValueError("ingredient name must not be empty")
    if concentration < 0:
        raise ValueError("concentration must not be negative")
    return str(name).strip(), float(rate), float(concentration)


def validate_formula(notes: list[Ingredient]) -> list[Ingredient]:
    return [validate_ingredient(ingredient) for ingredient in notes]


def group_notes(notes: list[Ingredient]) -> NoteGroups:
    groups = {"top": [], "heart": [], "base": []}
    for name, rate, concentration in notes:
        groups[classify_note(rate)].append(f"{name} {concentration:.1f}%")
    return groups


def sum_concentrations(notes: list[Ingredient]) -> NoteTotals:
    totals = {"top": 0.0, "heart": 0.0, "base": 0.0}
    for _, rate, concentration in notes:
        totals[classify_note(rate)] += concentration
    return totals


def is_balanced(totals: NoteTotals) -> bool:
    return (
        abs(totals["top"] - TOP_TARGET) < TOLERANCE
        and abs(totals["heart"] - HEART_TARGET) < TOLERANCE
        and abs(totals["base"] - BASE_TARGET) < TOLERANCE
    )


def blend(notes: list[Ingredient]) -> tuple[float, float, float, bool]:
    totals = sum_concentrations(validate_formula(notes))
    return totals["top"], totals["heart"], totals["base"], is_balanced(totals)


def format_report(notes: list[Ingredient]) -> str:
    formula = validate_formula(notes)
    totals = sum_concentrations(formula)
    groups = group_notes(formula)
    lines = [
        f"{layer:<5} {totals[layer]:5.1f}%  " + ", ".join(groups[layer])
        for layer in ("top", "heart", "base")
    ]
    lines.append("balanced" if is_balanced(totals) else "unbalanced")
    return "\n".join(lines)


def main() -> None:
    formula = [
        ("bergamot", 92.0, 12.0),
        ("lemon", 78.5, 8.0),
        ("rose absolute", 42.0, 30.0),
        ("jasmine", 25.0, 20.0),
        ("sandalwood", 12.0, 18.0),
        ("vetiver", 5.5, 12.0),
    ]
    print(format_report(formula))


if __name__ == "__main__":
    main()

