MIN_READINGS: int = 10


def validate_readings(
    stroke: list[float],
) -> None:
    """Raise ValueError if any reading falls outside the 0..1 pressure range."""
    for index, reading in enumerate(stroke):
        if not 0.0 <= reading <= 1.0:
            raise ValueError(f"reading {index} out of range: {reading}")


def is_valid_stroke(
    stroke: list[float],
) -> bool:
    """A stroke is usable only when it holds at least MIN_READINGS samples."""
    return len(stroke) >= MIN_READINGS


def filter_strokes(
    strokes: list[list[float]],
) -> list[list[float]]:
    """Drop dots and truncated captures, validating what survives."""
    kept: list[list[float]] = []
    for stroke in strokes:
        if is_valid_stroke(stroke):
            validate_readings(stroke)
            kept.append(stroke)
    return kept


def average_pressure(
    stroke: list[float],
) -> float:
    return sum(stroke) / len(stroke)


def peak_pressure(
    stroke: list[float],
) -> float:
    return max(stroke)


def smoothness_score(
    stroke: list[float],
) -> float:
    """Distance between the peak and the mean; smaller means steadier."""
    return peak_pressure(stroke) - average_pressure(stroke)


def analyze(
    strokes: list[list[float]],
) -> float:
    valid: list[list[float]] = filter_strokes(strokes)
    if not valid:
        return 0.0
    scores: list[float] = [smoothness_score(stroke) for stroke in valid]
    return round(sum(scores) / len(scores), 4)


def format_report(
    strokes: list[list[float]],
    score: float,
) -> str:
    valid: list[list[float]] = filter_strokes(strokes)
    lines: list[str] = [f"strokes submitted: {len(strokes)}", f"strokes analyzed: {len(valid)}"]
    for number, stroke in enumerate(valid, start=1):
        mean: float = average_pressure(stroke)
        peak: float = peak_pressure(stroke)
        lines.append(
            f"  stroke {number}: mean={mean:.4f} peak={peak:.4f} score={smoothness_score(stroke):.4f}"
        )
    lines.append(f"average smoothness: {score:.4f}")
    return "\n".join(lines)


def main() -> None:
    session: list[list[float]] = [
        [0.5, 0.6, 0.5, 0.5, 0.7, 0.5, 0.6, 0.5, 0.5, 0.6],
        [0.2, 0.9],
        [0.3, 0.35, 0.4, 0.42, 0.38, 0.36, 0.41, 0.44, 0.4, 0.39, 0.37],
    ]
    overall: float = analyze(session)
    print(format_report(session, overall))


if __name__ == "__main__":
    main()

