Substation = tuple[str, float, float]


def net_power(
    demand: float,
    generation: float,
) -> float:
    return generation - demand


def compute_nets(
    substations: list[Substation],
) -> list[tuple[str, float]]:
    nets: list[tuple[str, float]] = []
    for name, demand, generation in substations:
        nets.append((name, net_power(demand, generation)))
    return nets


def split_groups(
    nets: list[tuple[str, float]],
) -> tuple[list[tuple[str, float]], list[tuple[str, float]]]:
    surpluses: list[tuple[str, float]] = []
    deficits: list[tuple[str, float]] = []
    for name, net in nets:
        if net >= 0:
            surpluses.append((name, net))
        else:
            deficits.append((name, -net))
    return surpluses, deficits


def total_surplus(
    surpluses: list[tuple[str, float]],
) -> float:
    return sum(amount for _, amount in surpluses)


def total_deficit(
    deficits: list[tuple[str, float]],
) -> float:
    return sum(amount for _, amount in deficits)


def assess_stability(
    surplus: float,
    deficit: float,
) -> str:
    if surplus >= deficit:
        return "stable"
    return "blackout risk"


def balance(
    substations: list[Substation],
) -> str:
    nets = compute_nets(substations)
    surpluses, deficits = split_groups(nets)
    return assess_stability(total_surplus(surpluses), total_deficit(deficits))


def format_report(
    substations: list[Substation],
) -> str:
    nets = compute_nets(substations)
    surpluses, deficits = split_groups(nets)
    lines: list[str] = [f"{name}: {net:+.1f} MW" for name, net in nets]
    lines.append(
        f"surplus={total_surplus(surpluses):.1f} MW "
        f"deficit={total_deficit(deficits):.1f} MW"
    )
    return "\n".join(lines)


def main() -> None:
    grid: list[Substation] = [
        ("North", 70, 50),
        ("South", 40, 90),
        ("East", 55, 55),
    ]
    print(format_report(grid))
    print(f"status: {balance(grid)}")


if __name__ == "__main__":
    main()

