def is_significant_plume(
    height: float
) -> bool:
    return height >= 5.0


def calculate_dispersal(
    height: float,
    wind_speed: float
) -> float:
    return height * wind_speed * 3.2


def filter_vents(
    vents: list[tuple[str, float, float]]
) -> list[tuple[str, float, float]]:
    return [
        vent for vent in vents
        if is_significant_plume(vent[1])
    ]


def compute_distances(
    vents: list[tuple[str, float, float]]
) -> list[tuple[str, float]]:
    distances = []
    for name, height, wind_speed in vents:
        distances.append(
            (name, calculate_dispersal(height, wind_speed))
        )
    return distances


def sort_impact_zones(
    zones: list[tuple[str, float]]
) -> list[tuple[str, float]]:
    return sorted(
        zones,
        key=lambda zone: zone[1],
        reverse=True
    )


def extract_names(
    zones: list[tuple[str, float]]
) -> list[str]:
    return [zone[0] for zone in zones]


def format_report(
    zones: list[tuple[str, float]]
) -> str:
    lines = [
        f"{name}: {distance:.1f} km"
        for name, distance in zones
    ]
    return "\n".join(lines)


def predict(
    vents: list[tuple[str, float, float]]
) -> list[str]:
    significant = filter_vents(vents)
    distances = compute_distances(significant)
    sorted_zones = sort_impact_zones(distances)
    return extract_names(sorted_zones)


def main() -> None:
    sample_vents = [
        ("Etna", 10.0, 5.0),
        ("Stromboli", 2.0, 10.0),
        ("Vesuvius", 6.5, 4.0),
        ("Fuji", 8.0, 6.0)
    ]
    zones = sort_impact_zones(
        compute_distances(filter_vents(sample_vents))
    )
    print(format_report(zones))
    print("Order:", ", ".join(predict(sample_vents)))


if __name__ == "__main__":
    main()

