    distances = []
    for name, height, wind_speed in vents:
        distances.append(
            (name, calculate_dispersal(height, wind_speed))
        )
    return distances


def sort_impact_zones(
    zones
):
    return sorted(
        zones,
        key=lambda zone: zone[1],
        reverse=True
    )


def extract_names(
    zones
):
    return [zone[0] for zone in zones]


def format_report(
    zones
):
    lines = [
        f"{name}: {distance:.1f} km"
        for name, distance in zones
    ]
    return "\n".join(lines)


def predict(
    vents
):
    significant = filter_vents(vents)
    distances = compute_distances(significant)
    sorted_zones = sort_impact_zones(distances)
    return extract_names(sorted_zones)


def main():
    sample_vents = [
        ("Etna", 10.0, 5.0),
        ("Stromboli", 2.0, 10.0),
        ("Vesuvius", 6.5, 4.0),
        ("Fuji", 8.0, 6.0)
    ]
    zones = sort_impact_zones(
        compute_distances(filter_vents(sample_vents))
    )
    print(format_report(zones))
    print("Order:", ", ".join(predict(sample_vents)))


if __name__ == "__main__":
    main()

