BACKGROUND_THRESHOLD = 1.5
CRITICAL_ENERGY = 100000.0


def validate_tremors(
    tremors: list[float],
) -> list[float]:
    """Return the readings as floats, rejecting anything non-numeric."""
    cleaned: list[float] = []
    for index, reading in enumerate(tremors):
        if isinstance(reading, bool) or not isinstance(reading, (int, float)):
            raise TypeError(f"reading {index} is not a magnitude: {reading!r}")
        cleaned.append(float(reading))
    return cleaned


def filter_background(
    tremors: list[float],
    threshold: float = BACKGROUND_THRESHOLD,
) -> list[float]:
    """Drop tremors that are mere background vibrations."""
    return [magnitude for magnitude in tremors if magnitude >= threshold]


def tremor_energy(
    magnitude: float,
) -> float:
    """Energy released by a single tremor: ten to the power of its magnitude."""
    return 10.0**magnitude


def total_energy(
    tremors: list[float],
) -> float:
    """Sum of the energy released by every significant tremor."""
    return sum(tremor_energy(magnitude) for magnitude in tremors)


def classify(
    energy: float,
    limit: float = CRITICAL_ENERGY,
) -> str:
    """Translate an accumulated energy figure into a verdict."""
    if energy > limit:
        return "critical warning"
    return "normal activity"


def monitor(
    tremors: list[float],
) -> str:
    """Evaluate a week of micro-earthquakes and report the fault-slip risk."""
    readings = validate_tremors(tremors)
    significant = filter_background(readings)
    return classify(total_energy(significant))


def format_report(
    label: str,
    tremors: list[float],
) -> str:
    """Build a one-line summary of a week's seismic record."""
    significant = filter_background(validate_tremors(tremors))
    ignored = len(tremors) - len(significant)
    energy = total_energy(significant)
    verdict = monitor(tremors)
    return (
        f"{label}: {len(significant)} significant tremors "
        f"({ignored} filtered), energy {energy:,.1f} -> {verdict}"
    )


def main() -> None:
    weeks: dict[str, list[float]] = {
        "week 1": [3.0, 4.0, 1.2, 5.1],
        "week 2": [1.0, 1.4, 2.2, 3.5],
        "week 3": [4.9, 4.8, 0.9, 4.95, 1.49],
    }
    for label, tremors in weeks.items():
        print(format_report(label, tremors))


if __name__ == "__main__":
    main()

