BASELINE_CURVATURE = 44.0
CYLINDER_THRESHOLD = 0.5


def spherical_power(
    horizontal: float,
    vertical: float,
) -> float:
    average = (horizontal + vertical) / 2
    return BASELINE_CURVATURE - average


def cylinder_power(
    horizontal: float,
    vertical: float,
) -> float:
    difference = abs(horizontal - vertical)
    if difference < CYLINDER_THRESHOLD:
        return 0.0
    return difference


def validate_reading(
    patient: str,
    horizontal: float,
    vertical: float,
) -> None:
    if not patient:
        raise ValueError("patient identifier must not be empty")
    for axis, value in (("horizontal", horizontal), ("vertical", vertical)):
        if value <= 0:
            raise ValueError(f"{axis} curvature for {patient} must be positive")


def format_measurement(
    patient: str,
    sphere: float,
    cylinder: float,
) -> tuple:
    return (patient, round(sphere, 2), cylinder)


def calculate(
    measurements: list,
) -> list:
    prescriptions = []
    for patient, horizontal, vertical in measurements:
        validate_reading(patient, horizontal, vertical)
        sphere = spherical_power(horizontal, vertical)
        cylinder = cylinder_power(horizontal, vertical)
        prescriptions.append(format_measurement(patient, sphere, cylinder))
    return prescriptions


def describe_prescription(
    prescription: tuple,
) -> str:
    patient, sphere, cylinder = prescription
    sign = "+" if sphere >= 0 else "-"
    cylinder_text = f"{cylinder:.2f}" if cylinder else "none"
    return f"{patient}: sphere {sign}{abs(sphere):.2f} D, cylinder {cylinder_text}"


def build_report(
    prescriptions: list,
) -> str:
    lines = [describe_prescription(item) for item in prescriptions]
    return "\n".join(lines)


def main() -> None:
    readings = [
        ("P-1001", 43.25, 44.75),
        ("P-1002", 42.10, 42.30),
        ("P-1003", 45.00, 46.20),
    ]
    results = calculate(readings)
    print(results)
    print(build_report(results))


if __name__ == "__main__":
    main()

