from datetime import date

PREMIUM_WOODS = frozenset({"mahogany", "walnut"})
LATEST_ANTIQUE_YEAR = 1950


def current_year() -> int:
    return date.today().year


def base_age_value(
    year_made: int,
) -> int:
    return (current_year() - year_made) * 10


def condition_modifier(
    condition: int,
) -> int:
    if condition > 7:
        return 50
    if condition < 5:
        return -30
    return 0


def wood_multiplier(
    wood: str,
) -> int:
    return 2 if wood.strip().lower() in PREMIUM_WOODS else 1


def maker_mark_bonus(
    has_mark: bool,
) -> int:
    return 500 if has_mark else 0


def is_antique(
    year_made: int,
) -> bool:
    return year_made <= LATEST_ANTIQUE_YEAR


def item_value(
    item: tuple[int, int, str, bool],
) -> int:
    year_made, condition, wood, has_mark = item
    if not 0 <= condition <= 10:
        raise ValueError(f"condition rating out of range: {condition}")
    value = base_age_value(year_made) + condition_modifier(condition)
    return value * wood_multiplier(wood) + maker_mark_bonus(has_mark)


def appraise(
    items: list[tuple[int, int, str, bool]],
) -> int:
    return sum(item_value(item) for item in items if is_antique(item[0]))


def format_report(
    items: list[tuple[int, int, str, bool]],
) -> str:
    lines = []
    for item in items:
        year_made, condition, wood, has_mark = item
        if is_antique(year_made):
            mark = "with mark" if has_mark else "no mark"
            lines.append(
                f"{year_made} {wood} (cond {condition}/10, {mark}): {item_value(item)}"
            )
        else:
            lines.append(f"{year_made} {wood}: too recent, excluded")
    lines.append(f"Total appraised value: {appraise(items)}")
    return "\n".join(lines)


def main() -> None:
    collection = [
        (1920, 8, "mahogany", True),
        (2000, 9, "oak", False),
        (1890, 4, "walnut", False),
        (1935, 6, "pine", True),
    ]
    print(format_report(collection))


if __name__ == "__main__":
    main()

