from math import ceil

ACTIVITY_FACTORS: dict[str, float] = {"high": 1.5, "moderate": 1.0, "low": 0.8}
CALORIES_PER_PORTION: int = 200


def base_calories(
    weight_kg: float
) -> float:
    return weight_kg * 50


def age_adjustment(
    age_years: float
) -> float:
    return 500.0 if age_years < 2 else 0.0


def activity_factor(
    activity_level: str
) -> float:
    key = activity_level.strip().lower()
    if key not in ACTIVITY_FACTORS:
        raise ValueError(f"unknown activity level: {activity_level!r}")
    return ACTIVITY_FACTORS[key]


def daily_calories(
    weight_kg: float,
    age_years: float,
    activity_level: str
) -> int:
    adjusted = base_calories(weight_kg) + age_adjustment(age_years)
    return round(adjusted * activity_factor(activity_level))


def fruit_portions(
    calories: int
) -> int:
    return ceil(calories / CALORIES_PER_PORTION)


def describe(
    position: int,
    calories: int,
    portions: int
) -> str:
    return f"Primate {position}: {calories} kcal/day, {portions} fruit portion(s)"


def schedule(
    primates: list[tuple[float, float, str]]
) -> tuple[int, int]:
    total_calories = 0
    total_portions = 0
    for weight_kg, age_years, activity_level in primates:
        calories = daily_calories(weight_kg, age_years, activity_level)
        total_calories += calories
        total_portions += fruit_portions(calories)
    return total_calories, total_portions


def report(
    primates: list[tuple[float, float, str]]
) -> list[str]:
    lines: list[str] = []
    for position, (weight_kg, age_years, activity_level) in enumerate(primates, start=1):
        calories = daily_calories(weight_kg, age_years, activity_level)
        lines.append(describe(position, calories, fruit_portions(calories)))
    total_calories, total_portions = schedule(primates)
    lines.append(f"Troop total: {total_calories} kcal/day, {total_portions} fruit portion(s)")
    return lines


def main() -> None:
    troop: list[tuple[float, float, str]] = [(10, 1.5, "high"), (20, 5, "low")]
    for line in report(troop):
        print(line)
    print(schedule(troop))


if __name__ == "__main__":
    main()

