WARM_THRESHOLD: float = 75.0
WARM_SUGAR_RATIO: float = 0.1
COOL_SUGAR_RATIO: float = 0.15


def validate_batch(
    batch: tuple[float, float, float],
) -> tuple[float, float, float]:
    volume_ml, temperature_f, acidity = batch
    if volume_ml < 0:
        raise ValueError(f"tea volume must not be negative: {volume_ml}")
    if acidity < 0:
        raise ValueError(f"desired acidity must not be negative: {acidity}")
    return float(volume_ml), float(temperature_f), float(acidity)


def target_sugar(
    volume_ml: float,
    temperature_f: float,
) -> float:
    ratio: float = WARM_SUGAR_RATIO if temperature_f > WARM_THRESHOLD else COOL_SUGAR_RATIO
    return volume_ml * ratio


def starter_liquid(
    sugar_g: float,
    acidity: float,
) -> float:
    return sugar_g * acidity


def total_mass(
    volume_ml: float,
    sugar_g: float,
    starter_ml: float,
) -> float:
    return volume_ml + sugar_g + starter_ml


def brew_batch(
    batch: tuple[float, float, float],
) -> tuple[float, float, float]:
    volume_ml, temperature_f, acidity = validate_batch(batch)
    sugar_g: float = target_sugar(volume_ml, temperature_f)
    starter_ml: float = starter_liquid(sugar_g, acidity)
    return sugar_g, starter_ml, total_mass(volume_ml, sugar_g, starter_ml)


def calculate(
    batches: list[tuple[float, float, float]],
) -> list[tuple[float, float, float]]:
    return [brew_batch(batch) for batch in batches]


def format_row(
    number: int,
    result: tuple[float, float, float],
) -> str:
    sugar_g, starter_ml, final_ml = result
    return (
        f"Batch {number}: add {sugar_g:.1f} g sugar and "
        f"{starter_ml:.1f} mL starter -> {final_ml:.1f} mL total"
    )


def build_report(
    results: list[tuple[float, float, float]],
) -> str:
    lines: list[str] = [
        format_row(number, result) for number, result in enumerate(results, start=1)
    ]
    return "\n".join(lines)


def main() -> None:
    batches: list[tuple[float, float, float]] = [(1000, 80, 0.8), (2000, 70, 1.0)]
    results: list[tuple[float, float, float]] = calculate(batches)
    print(build_report(results))


if __name__ == "__main__":
    main()

