BASE_TIMES = {"small": 30, "medium": 60, "large": 120}


def base_time(
    size_class: str,
) -> int:
    key = size_class.strip().lower()
    if key not in BASE_TIMES:
        raise ValueError(f"unknown size class: {size_class!r}")
    return BASE_TIMES[key]


def detail_penalty(
    detail_rating: int,
) -> int:
    if detail_rating < 0:
        raise ValueError(f"detail rating must not be negative: {detail_rating}")
    return 10 * max(0, detail_rating - 5)


def color_addition(
    color_count: int,
) -> int:
    if color_count < 0:
        raise ValueError(f"color count must not be negative: {color_count}")
    return 5 * max(0, color_count - 3)


def model_minutes(
    model: tuple[str, int, int],
) -> int:
    size_class, detail_rating, color_count = model
    total = base_time(size_class)
    total += detail_penalty(detail_rating)
    return total + color_addition(color_count)


def minutes_to_hours(
    minutes: int,
) -> float:
    return round(minutes / 60.0, 2)


def estimate(
    models: list[tuple[str, int, int]],
) -> float:
    total_minutes = sum(model_minutes(model) for model in models)
    return minutes_to_hours(total_minutes)


def describe(
    model: tuple[str, int, int],
) -> str:
    size_class, detail_rating, color_count = model
    minutes = model_minutes(model)
    return (
