Rig = tuple[float, float, float]


def wind_pressure(
    wind_speed: float,
    sail_area: float,
) -> float:
    """Base tension: wind speed squared times sail area, divided by ten."""
    return (wind_speed ** 2) * sail_area / 10.0


def apply_mast_leverage(
    base_tension: float,
    mast_height: float,
) -> float:
    """Scale the base tension by the mast leverage ratio."""
    return base_tension * mast_height / 15.0


def categorize(
    tension: float,
) -> str:
    """Map a tension value onto its rigging status."""
    if tension > 5000.0:
        return "danger"
    if tension < 1000.0:
        return "loose"
    return "optimal"


def validate_rig(
    rig: Rig,
) -> Rig:
    """Ensure a rig entry has three non-negative numeric measurements."""
    if len(rig) != 3:
        raise ValueError("each rig needs wind speed, sail area and mast height")
    wind_speed, sail_area, mast_height = rig
    for value in (wind_speed, sail_area, mast_height):
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError("rig measurements must be numeric")
        if value < 0:
            raise ValueError("rig measurements must be non-negative")
    return float(wind_speed), float(sail_area), float(mast_height)


def tension_of(
    rig: Rig,
) -> float:
    """Full tension for one rig, leverage included."""
    wind_speed, sail_area, mast_height = validate_rig(rig)
    base: float = wind_pressure(wind_speed, sail_area)
    return apply_mast_leverage(base, mast_height)


def analyze(
    rigs: list[Rig],
) -> list[str]:
    """Return a status string for every rig in the fleet."""
    return [categorize(tension_of(rig)) for rig in rigs]


def format_report(
    rigs: list[Rig],
) -> str:
    """Human-readable table of tension and status per rig."""
    lines: list[str] = []
    for rig in rigs:
        tension = tension_of(rig)
        lines.append(
            "wind {0:.0f}kt sail {1:.0f}m2 mast {2:.0f}m -> {3:8.1f} N  {4}".format(
                rig[0], rig[1], rig[2], tension, categorize(tension)
            )
        )
    return "\n".join(lines)


def main() -> None:
    fleet: list[Rig] = [(20, 30, 15), (10, 15, 10), (40, 25, 18)]
    print(analyze(fleet))
    print(format_report(fleet))


if __name__ == "__main__":
    main()

