from typing import Tuple

Material = Tuple[str, float, int]


def validate_material(
    material: Material,
) -> Material:
    """Normalise one (name, mass, C:N ratio) entry, rejecting nonsense values."""
    name, mass, ratio = material
    if not name:
        raise ValueError("material name must not be empty")
    if mass <= 0:
        raise ValueError(f"mass for {name!r} must be positive")
    if ratio <= 0:
        raise ValueError(f"C:N ratio for {name!r} must be positive")
    return name, float(mass), int(ratio)


def carbon_units(
    material: Material,
) -> float:
    """Carbon units contributed by one material: mass times its C:N ratio."""
    _, mass, ratio = material
    return mass * ratio


def total_mass(
    materials: list[Material],
) -> float:
    return sum(mass for _, mass, _ in materials)


def total_carbon_units(
    materials: list[Material],
) -> float:
    return sum(carbon_units(material) for material in materials)


def overall_ratio(
    materials: list[Material],
) -> float:
    mass = total_mass(materials)
    if mass == 0:
        raise ValueError("cannot compute a ratio for an empty pile")
    return total_carbon_units(materials) / mass


def is_balanced(
    ratio: float,
) -> bool:
    return 25 <= ratio <= 35


def balance(
    materials: list[Material],
) -> Tuple[float, bool]:
    checked = [validate_material(material) for material in materials]
    ratio = round(overall_ratio(checked), 1)
    return ratio, is_balanced(ratio)


def format_report(
    materials: list[Material],
) -> str:
    ratio, balanced = balance(materials)
    verdict = "balanced" if balanced else "needs adjustment"
    lines = [f"{name}: {mass:g} kg at C:N {rat}" for name, mass, rat in materials]
    lines.append(f"total mass: {total_mass(materials):g} kg")
    lines.append(f"overall C:N {ratio} -> {verdict}")
    return "\n".join(lines)


def main() -> None:
    print(format_report([("straw", 50, 15), ("woodchips", 50, 45)]))
    print(format_report([("grass clippings", 20, 18), ("cardboard", 5, 350)]))


if __name__ == "__main__":
    main()

