MAJOR_THRESHOLD: float = 50.0


def validate_blade(
    blade: tuple,
) -> tuple[str, float, float, float]:
    if len(blade) != 4:
        raise ValueError(f"blade record must have 4 fields, got {len(blade)}")
    position, current, target, density = blade
    if not isinstance(position, str) or not position.strip():
        raise ValueError("blade position must be a non-empty string")
    factor = float(density)
    if factor <= 0.0:
        raise ValueError(f"material density factor for {position!r} must be positive")
    return position.strip(), float(current), float(target), factor


def weight_discrepancy(
    current_weight: float,
    target_weight: float,
) -> float:
    return current_weight - target_weight


def counterweight_mass(
    discrepancy: float,
    density_factor: float,
) -> float:
    return discrepancy / density_factor


def adjustment_intensity(
    mass: float,
) -> str:
    if mass > MAJOR_THRESHOLD:
        return "major"
    return "minor"


def adjust(
    blades: list,
) -> list[tuple[float, str]]:
    plan: list[tuple[float, str]] = []
    for blade in blades:
        _position, current, target, factor = validate_blade(blade)
        discrepancy = weight_discrepancy(current, target)
        if discrepancy < 0.0:
            continue
        mass = counterweight_mass(discrepancy, factor)
        plan.append((mass, adjustment_intensity(mass)))
    return plan


def format_plan(
    plan: list[tuple[float, str]],
) -> str:
    if not plan:
        return "no counterweights required"
    lines: list[str] = [
        f"{mass:.1f} g -> {kind} adjustment" for mass, kind in plan
    ]
    return "\n".join(lines)


def main() -> None:
    rotor = [
        ("forward", 1500, 1400, 2.0),
        ("aft", 1200, 1250, 1.5),
        ("port", 1400, 1250, 1.0),
    ]
    plan = adjust(rotor)
    print(plan)
    print(format_plan(plan))


if __name__ == "__main__":
    main()

