MILLILITRES_PER_PLANT = 50.0
MILLILITRES_PER_LITRE_OF_SOIL = 10.0
HIGH_COVERAGE_THRESHOLD = 80.0
LOW_COVERAGE_THRESHOLD = 20.0


def base_plant_need(
    plant_count: int,
) -> float:
    if plant_count < 0:
        raise ValueError("plant count cannot be negative")
    return plant_count * MILLILITRES_PER_PLANT


def soil_retention_capacity(
    soil_litres: float,
) -> float:
    if soil_litres < 0:
        raise ValueError("soil volume cannot be negative")
    return soil_litres * MILLILITRES_PER_LITRE_OF_SOIL


def condensation_factor(
    coverage_percent: float,
) -> float:
    if not 0.0 <= coverage_percent <= 100.0:
        raise ValueError("coverage must be a percentage between 0 and 100")
    if coverage_percent > HIGH_COVERAGE_THRESHOLD:
        return 0.8
    if coverage_percent < LOW_COVERAGE_THRESHOLD:
        return 1.3
    return 1.0


def adjust_for_condensation(
    raw_need: float,
    coverage_percent: float,
) -> float:
    return raw_need * condensation_factor(coverage_percent)


def water_for_terrarium(
    terrarium: tuple[int, float, float],
) -> int:
    plant_count, soil_litres, coverage_percent = terrarium
    raw_need = base_plant_need(plant_count) + soil_retention_capacity(soil_litres)
    return round(adjust_for_condensation(raw_need, coverage_percent))


def regulate(
    terrariums: list[tuple[int, float, float]],
) -> list[int]:
    return [water_for_terrarium(terrarium) for terrarium in terrariums]


def describe_terrarium(
    terrarium: tuple[int, float, float],
    millilitres: int,
) -> str:
    plant_count, soil_litres, coverage_percent = terrarium
    return (
        f"{plant_count} plants, {soil_litres:g} L soil, "
        f"{coverage_percent:g}% condensation -> {millilitres} mL"
    )


def format_report(
    terrariums: list[tuple[int, float, float]],
) -> str:
    additions = regulate(terrariums)
    lines = [
        describe_terrarium(terrarium, millilitres)
        for terrarium, millilitres in zip(terrariums, additions)
    ]
    lines.append(f"total: {sum(additions)} mL")
    return "\n".join(lines)


def main() -> None:
    tanks = [(5, 10, 85), (3, 5, 15), (8, 20, 50)]
    print(format_report(tanks))


if __name__ == "__main__":
    main()

