TrainRecord = tuple[str, int, int]


def validate_schedule(
    trains: list[TrainRecord],
    buffer: int,
) -> None:
    if buffer < 0:
        raise ValueError("buffer must not be negative")
    seen = set()
    for name, arrival, departure in trains:
        if departure < arrival:
            raise ValueError(f"{name}: departure precedes arrival")
        if name in seen:
            raise ValueError(f"{name}: duplicate identifier")
        seen.add(name)


def active_durations(
    trains: list[TrainRecord],
    buffer: int,
) -> dict[str, int]:
    return {name: departure - arrival + buffer for name, arrival, departure in trains}


def occupancy_windows(
    trains: list[TrainRecord],
    buffer: int,
) -> dict[str, tuple[int, int]]:
    durations = active_durations(trains, buffer)
    windows = {}
    for name, arrival, _departure in trains:
        windows[name] = (arrival, arrival + durations[name])
    return windows


def arrival_inside(
    moment: int,
    window: tuple[int, int],
) -> bool:
    start, end = window
    return start <= moment < end


def schedule(
    trains: list[TrainRecord],
    buffer: int,
) -> list[str]:
    validate_schedule(trains, buffer)
    windows = occupancy_windows(trains, buffer)
    conflicting = set()
    for first, _arrival_first, _dep_first in trains:
        for second, arrival_second, _dep_second in trains:
            if first == second:
                continue
            if arrival_inside(arrival_second, windows[first]):
                conflicting.add(first)
                conflicting.add(second)
    return sorted(conflicting)


def format_clock(
    minutes: int,
) -> str:
    return f"{minutes // 60 % 24:02d}:{minutes % 60:02d}"


def format_report(
    trains: list[TrainRecord],
    buffer: int,
) -> str:
    conflicts = set(schedule(trains, buffer))
    windows = occupancy_windows(trains, buffer)
    lines = []
    for name, arrival, _departure in sorted(trains, key=lambda record: record[1]):
        start, end = windows[name]
        flag = "CONFLICT" if name in conflicts else "clear"
        lines.append(
            f"{name:<8} arrives {format_clock(arrival)} "
            f"occupies {format_clock(start)}-{format_clock(end)} [{flag}]"
        )
    return "\n".join(lines)


def main() -> None:
    timetable = [
        ("alpha", 100, 120),
        ("beta", 110, 130),
        ("gamma", 200, 215),
        ("delta", 240, 250),
    ]
    print(format_report(timetable, 10))
    print("conflicts:", schedule(timetable, 10))


if __name__ == "__main__":
    main()

