LOAM_MAX_CLAY: float = 20.0


def validate_sample(
    sample: tuple,
) -> tuple[str, float, float, float]:
    """Unpack a raw record and make sure its weights can be used."""
    identifier, sand, silt, clay = sample
    weights: list[float] = [float(sand), float(silt), float(clay)]
    if min(weights) < 0.0:
        raise ValueError(f"negative weight in sample {identifier!r}")
    if sum(weights) <= 0.0:
        raise ValueError(f"sample {identifier!r} has no material to analyse")
    return str(identifier), weights[0], weights[1], weights[2]


def percentages(
    sample: tuple,
) -> tuple[str, float, float, float]:
    """Return the identifier plus the sand, silt and clay percentages."""
    identifier, sand, silt, clay = validate_sample(sample)
    total: float = sand + silt + clay
    return (
        identifier,
        sand / total * 100.0,
        silt / total * 100.0,
        clay / total * 100.0,
    )


def categorize(
    percent_sand: float,
    percent_clay: float,
    threshold: float,
) -> str:
    """A loam has enough sand to pass the threshold, but stays inside the
    sand and clay limits of the loam class; anything else is normal."""
    sand_in_range: bool = threshold < percent_sand <= LOAM_MAX_SAND
    if sand_in_range and percent_clay < LOAM_MAX_CLAY:
        return "loam"
    return "normal"


def classify(
    samples: list[tuple],
    threshold: int,
) -> list[tuple[str, str]]:
    results: list[tuple[str, str]] = []
    for sample in samples:
        identifier, percent_sand, _, percent_clay = percentages(sample)
        results.append((identifier, categorize(percent_sand, percent_clay, threshold)))
    return results


def build_report(
    samples: list[tuple],
    threshold: int,
) -> str:
    lines: list[str] = ["id       sand%  silt%  clay%  category"]
    for sample in samples:
        identifier, percent_sand, percent_silt, percent_clay = percentages(sample)
        category: str = categorize(percent_sand, percent_clay, threshold)
        lines.append(
            f"{identifier:<8} {percent_sand:5.1f}  {percent_silt:5.1f}"
            f"  {percent_clay:5.1f}  {category}"
        )
    return "\n".join(lines)


def main() -> None:
    samples: list[tuple] = [
        ("site1", 45, 40, 15),
        ("site2", 80, 10, 10),
        ("site3", 20, 30, 50),
    ]
    threshold: int = 40
    print(classify(samples, threshold))
    print(build_report(samples, threshold))


if __name__ == "__main__":
    main()

