def rainfall_erosivity(
    rainfall: float,
    factor: float,
) -> float:
    """Erosivity is the rainfall depth scaled by the erosivity factor."""
    return rainfall * factor


def slope_steepness(
    slope: float,
) -> float:
    """Steepness grows with the square of the slope degree."""
    return (slope ** 2) / 10


def soil_loss_rate(
    rainfall: float,
    slope: float,
    factor: float,
) -> float:
    erosivity = rainfall_erosivity(rainfall, factor)
    steepness = slope_steepness(slope)
    return erosivity * steepness


def validate_terrain(
    terrain: tuple,
) -> tuple:
    if len(terrain) != 3:
        raise ValueError("each terrain needs a region, rainfall and slope")
    region, rainfall, slope = terrain
    if not isinstance(region, str) or not region:
        raise ValueError("region identifier must be a non-empty string")
    if rainfall < 0:
        raise ValueError("rainfall cannot be negative for region " + region)
    if slope < 0:
        raise ValueError("slope cannot be negative for region " + region)
    return region, float(rainfall), float(slope)


def evaluate(
    terrains: list,
    factor: float,
) -> list:
    if factor < 0:
        raise ValueError("the rainfall erosivity factor must be non-negative")
    results = []
    for terrain in terrains:
        region, rainfall, slope = validate_terrain(terrain)
        results.append((region, soil_loss_rate(rainfall, slope, factor)))
    return results


def worst_region(
    results: list,
) -> str:
    return max(results, key=lambda item: item[1])[0]


def format_report(
    results: list,
) -> str:
    lines = ["region        soil loss"]
    for region, rate in results:
        lines.append("{:<14}{:>9.2f}".format(region, rate))
    lines.append("highest loss: " + worst_region(results))
    return "\n".join(lines)


def main() -> None:
    terrains = [
        ("valley", 100, 5),
        ("ridge", 820, 18),
        ("plateau", 450, 3),
        ("gorge", 610, 24),
    ]
    factor = 0.5
    results = evaluate(terrains, factor)
    print(evaluate([("valley", 100, 5)], factor))
    print(format_report(results))


if __name__ == "__main__":
    main()

