from __future__ import annotations

ColorEntry = tuple[str, int, int, int]
RGB = tuple[int, int, int]


def _check_channel(
    value: int,
) -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError(f"channel value must be an int, got {value!r}")
    if not 0 <= value <= 255:
        raise ValueError(f"channel value out of range: {value}")
    return value


def parse_target(
    target: RGB,
) -> RGB:
    if len(target) != 3:
        raise ValueError("target must hold exactly three channel values")
    red, green, blue = target
    return _check_channel(red), _check_channel(green), _check_channel(blue)


def parse_entry(
    entry: ColorEntry,
) -> ColorEntry:
    if len(entry) != 4:
        raise ValueError("each color needs a name and three channel values")
    name = entry[0]
    if not isinstance(name, str) or not name.strip():
        raise ValueError(f"invalid color name: {name!r}")
    return (name.strip(), _check_channel(entry[1]),
            _check_channel(entry[2]), _check_channel(entry[3]))


def color_distance(
    entry: ColorEntry,
    target: RGB,
) -> int:
    return sum(abs(channel - goal) for channel, goal in zip(entry[1:], target))


def rank_colors(
    colors: list[ColorEntry],
    target: RGB,
) -> list[tuple[str, int]]:
    goal = parse_target(target)
    scored = [
        (entry[0], color_distance(entry, goal))
        for entry in (parse_entry(raw) for raw in colors)
    ]
    scored.sort(key=lambda pair: pair[1])
    return scored


def match(
    colors: list[ColorEntry],
    target: RGB,
) -> str:
    ranked = rank_colors(colors, target)
    if not ranked:
        raise ValueError("cannot match against an empty palette")
    return ranked[0][0]


def main() -> None:
    palette = [
        ("crimson", 200, 0, 0),
        ("blue", 0, 0, 200),
        ("olive", 128, 128, 0),
    ]
    target = (190, 10, 0)
    print(f"closest: {match(palette, target)}")
    for name, distance in rank_colors(palette, target):
        print(f"{name:<10} {distance:>4}")


if __name__ == "__main__":
    main()

