def validate_pixels(
    pixels: list[int],
) -> None:
    if not isinstance(pixels, list):
        raise TypeError("pixels must be a list of integers")
    for value in pixels:
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("pixel values must be integers")
        if value < 0 or value > 255:
            raise ValueError("grayscale pixels must lie between 0 and 255")


def binarize(
    pixels: list[int],
    threshold: int,
) -> list[int]:
    return [1 if value > threshold else 0 for value in pixels]


def has_adjacent_one(
    bits: list[int],
    index: int,
) -> bool:
    if index > 0 and bits[index - 1] == 1:
        return True
    return index + 1 < len(bits) and bits[index + 1] == 1


def despeckle(
    bits: list[int],
) -> list[int]:
    cleaned = []
    for index, bit in enumerate(bits):
        if bit == 1 and has_adjacent_one(bits, index):
            cleaned.append(1)
        else:
            cleaned.append(0)
    return cleaned


def coverage_percent(
    bits: list[int],
) -> int:
    if not bits:
        return 0
    return round(100 * sum(bits) / len(bits))


def mask(
    pixels: list[int],
    threshold: int,
) -> int:
    validate_pixels(pixels)
    if not isinstance(threshold, int) or isinstance(threshold, bool):
        raise TypeError("threshold must be an integer")
    return coverage_percent(despeckle(binarize(pixels, threshold)))


def format_report(
    scene_name: str,
    percent: int,
) -> str:
    bar = "#" * (percent // 10)
    return f"{scene_name:<10} {percent:>3}% {bar}"


def main() -> None:
    scenes = {
        "orbit-01": ([50, 210, 50, 220, 230], 200),
        "orbit-02": ([255, 255, 10, 0, 240, 250, 250, 5], 180),
        "orbit-03": ([12, 15, 11, 14, 13, 10], 200),
    }
    for name, (pixels, threshold) in scenes.items():
        print(format_report(name, mask(pixels, threshold)))


if __name__ == "__main__":
    main()

