Signal = tuple[int, int, bool]
Reading = tuple[int, int]


def validate_signal(
    entry: object,
) -> Signal:
    if not isinstance(entry, tuple) or len(entry) != 3:
        raise ValueError(f"each signal must be a 3-tuple, got {entry!r}")
    frequency, strength, artificial = entry
    if not isinstance(frequency, int) or isinstance(frequency, bool):
        raise ValueError(f"frequency must be an int, got {frequency!r}")
    if not isinstance(strength, int) or isinstance(strength, bool):
        raise ValueError(f"strength must be an int, got {strength!r}")
    if not isinstance(artificial, bool):
        raise ValueError(f"origin flag must be a bool, got {artificial!r}")
    return frequency, strength, artificial


def drop_artificial(
    signals: list[Signal],
) -> list[Signal]:
    return [signal for signal in signals if not signal[2]]


def subtract_baseline(
    signals: list[Signal],
    baseline: int,
) -> list[Reading]:
    return [(frequency, strength - baseline) for frequency, strength, _ in signals]


def viable_frequencies(
    readings: list[Reading],
) -> list[int]:
    return sorted(frequency for frequency, strength in readings if strength > 0)


def filter(
    signals: list[object],
    baseline: int,
) -> list[int]:
    if not isinstance(baseline, int) or isinstance(baseline, bool):
        raise ValueError(f"baseline must be an int, got {baseline!r}")
    checked = [validate_signal(entry) for entry in signals]
    natural = drop_artificial(checked)
    adjusted = subtract_baseline(natural, baseline)
    return viable_frequencies(adjusted)


def format_report(
    frequencies: list[int],
) -> str:
    if not frequencies:
        return "no viable frequencies"
    parts = [f"{frequency} MHz" for frequency in frequencies]
    return ", ".join(parts)


def survey(
    catalogue: dict[str, list[Signal]],
    baseline: int,
) -> dict[str, list[int]]:
    return {name: filter(list(signals), baseline) for name, signals in catalogue.items()}


def main() -> None:
    catalogue = {
        "sector-a": [(100, 10, False), (200, 50, True), (300, 3, False)],
        "sector-b": [(880, 6, False), (450, 12, False), (450, 99, True)],
        "sector-c": [(1420, 4, False), (1421, 5, False)],
    }
    baseline = 5
    results = survey(catalogue, baseline)
    for name in sorted(results):
        print(f"{name}: {results[name]} -> {format_report(results[name])}")


if __name__ == "__main__":
    main()

