ROTATION: dict[str, str] = {
    "grass": "legume",
    "legume": "cover",
    "cover": "nightshade",
    "nightshade": "grass",
}


def normalise_family(
    family: str,
) -> str:
    cleaned: str = family.strip().lower()
    if cleaned not in ROTATION:
        raise ValueError(f"unknown plant family: {family!r}")
    return cleaned


def check_season(
    season: int,
) -> int:
    if not isinstance(season, int) or isinstance(season, bool):
        raise TypeError("season must be an integer")
    if season < 1:
        raise ValueError("season must be at least 1")
    return season


def needs_rest(
    family: str,
    season: int,
) -> bool:
    return family == "nightshade" and season % 2 == 0


def next_crop(
    family: str,
) -> str:
    return ROTATION[family]


def assign(
    field: str,
    family: str,
    season: int,
) -> tuple[str, str]:
    if needs_rest(family, season):
        return (field, "fallow")
    return (field, next_crop(family))


def plan(
    fields: list[tuple[str, str]],
    season: int,
) -> list[tuple[str, str]]:
    year: int = check_season(season)
    assignments: list[tuple[str, str]] = []
    for field, family in fields:
        assignments.append(assign(field, normalise_family(family), year))
    return assignments


def format_report(
    assignments: list[tuple[str, str]],
    season: int,
) -> str:
    width: int = max((len(field) for field, _ in assignments), default=0)
    header: str = f"Planting plan for season {season}"
    lines: list[str] = [header, "-" * len(header)]
    for field, crop in assignments:
        lines.append(f"{field.ljust(width)}  ->  {crop}")
    return "\n".join(lines)


def main() -> None:
    fields: list[tuple[str, str]] = [
        ("north", "nightshade"),
        ("south", "grass"),
        ("east", "legume"),
        ("west", "cover"),
    ]
    season: int = 2
    print(plan(fields, season))
    print(format_report(plan(fields, season), season))
    print(format_report(plan(fields, season + 1), season + 1))


if __name__ == "__main__":
    main()

