    season,
):
    if not isinstance(season, int) or isinstance(season, bool):
        raise TypeError("season must be an integer")
    if season < 1:
        raise ValueError("season must be at least 1")
    return season


def needs_rest(
    family,
    season,
):
    return family == "nightshade" and season % 2 == 0


def next_crop(
    family,
):
    return ROTATION[family]


def assign(
    field,
    family,
    season,
):
    if needs_rest(family, season):
        return (field, "fallow")
    return (field, next_crop(family))


def plan(
    fields,
    season,
):
    year = check_season(season)
    assignments = []
    for field, family in fields:
        assignments.append(assign(field, normalise_family(family), year))
    return assignments


def format_report(
    assignments,
    season,
):
    width = max((len(field) for field, _ in assignments), default=0)
    header = f"Planting plan for season {season}"
    lines = [header, "-" * len(header)]
    for field, crop in assignments:
        lines.append(f"{field.ljust(width)}  ->  {crop}")
    return "\n".join(lines)


def main():
    fields = [
        ("north", "nightshade"),
        ("south", "grass"),
        ("east", "legume"),
        ("west", "cover"),
    ]
    season = 2
    print(plan(fields, season))
    print(format_report(plan(fields, season), season))
    print(format_report(plan(fields, season + 1), season + 1))


if __name__ == "__main__":
    main()

