import math


def stress_intensity_range(
    stress: float,
    geometry: float,
    crack_length: float,
) -> float:
    """Alternating stress intensity range in MPa*sqrt(m) for a crack in mm."""
    if crack_length <= 0.0:
        raise ValueError("crack length must be positive")
    return geometry * stress * math.sqrt(math.pi * crack_length / 1000.0)


def growth_rate(
    delta_k: float,
    toughness: float,
    humidity: float,
    temperature: float,
) -> float:
    """Crack extension per cycle in mm, Paris law scaled by environment."""
    if toughness <= 0.0:
        raise ValueError("fracture toughness must be positive")
    if delta_k >= toughness:
        return float("inf")
    paris = 1.2e-8 * (delta_k ** 3.2)
    moisture = 1.0 + 1.8 * max(0.0, min(humidity, 100.0)) / 100.0
    thermal = 1.0 + abs(temperature - 20.0) / 55.0
    closure = 1.0 / (1.0 - delta_k / toughness)
    return paris * moisture * thermal * closure


def propagation(
    initial: float,
    cycles: int,
    stress: float,
    geometry: float,
    toughness: float,
    humidity: float,
    temperature: float,
) -> float:
    """Final crack length in mm after the given number of flight cycles."""
    if cycles < 0:
        raise ValueError("cycles must be non-negative")
    length = float(initial)
    for _ in range(cycles):
        delta_k = stress_intensity_range(stress, geometry, length)
        rate = growth_rate(delta_k, toughness, humidity, temperature)
        if math.isinf(rate):
            return float("inf")
        length += rate
    return length


def format_report(
    label: str,
    start: float,
    final: float,
) -> str:
    if math.isinf(final):
        return f"{label:<22} {start:6.2f} mm -> FAILURE (unstable fracture)"
    growth = final - start
    return f"{label:<22} {start:6.2f} mm -> {final:7.3f} mm  (+{growth:.3f} mm)"


def main() -> None:
    start = 1.5
    cycles = 20000
    scenarios: list[tuple[str, float, float]] = [
        ("dry cabin, 20 C", 5.0, 20.0),
        ("humid cabin, 20 C", 85.0, 20.0),
        ("humid cabin, -55 C", 85.0, -55.0),
        ("humid cabin, 80 C", 85.0, 80.0),
    ]
    for label, humidity, temperature in scenarios:
        final = propagation(start, cycles, 70.0, 1.12, 33.0, humidity, temperature)
        print(format_report(label, start, final))


if __name__ == "__main__":
    main()

