SEVERITY_FACTORS: dict[int, float] = {0: 1.0, 1: 1.15, 2: 1.35, 3: 1.6, 4: 2.0, 5: 2.6}


def require_positive(
    label: str,
    value: float,
) -> float:
    if value <= 0:
        raise ValueError(f"{label} must be positive, got {value!r}")
    return value


def severity_factor(
    weather: int,
) -> float:
    if weather not in SEVERITY_FACTORS:
        raise ValueError(f"weather severity must be 0..5, got {weather!r}")
    return SEVERITY_FACTORS[weather]


def daily_transit_cost(
    distance: float,
    payload: float,
    fuel: float,
    weather: int,
) -> float:
    hull_drag = 1.0 + payload / 1200.0
    burn = distance * fuel * hull_drag / 100.0
    return burn * severity_factor(weather) + payload * 0.35


def fleet_penalty(
    vessels: int,
    urgency: float,
    transit_cost: float,
) -> float:
    utilization = urgency / vessels
    return transit_cost * utilization * (1.0 + utilization * 0.5)


def supply(
    distance: float,
    payload: float,
    fuel: float,
    weather: int,
    vessels: int,
    urgency: float,
    days: int,
) -> float:
    require_positive("distance", distance)
    require_positive("payload", payload)
    require_positive("fuel", fuel)
    require_positive("vessels", vessels)
    require_positive("urgency", urgency)
    require_positive("days", days)
    transit = daily_transit_cost(distance, payload, fuel, weather)
    penalty = fleet_penalty(vessels, urgency, transit)
    return (transit + penalty) * days


def format_report(
    label: str,
    cost: float,
) -> str:
    return f"{label:<22}{cost:>16,.2f} USD"


def main() -> None:
    scenarios: list[tuple[str, float, float, float, int, int, float, int]] = [
