from math import log10


def marine_undercut(
    tide: float,
    wave: float,
    fetch: float,
) -> float:
    """Undercutting energy index at the cliff toe (dimensionless)."""
    if min(tide, wave, fetch) < 0.0:
        raise ValueError("tide, wave and fetch must be non-negative")
    exposure = 1.0 + log10(1.0 + fetch / 10.0)
    swash = 0.4 * tide + wave ** 1.5
    return swash * exposure


def terrestrial_weathering(
    geology: float,
    slope: float,
    rainfall: float,
) -> float:
    """Subaerial weathering factor; geology is a 1 (soft) to 10 (hard) resistance."""
    if not 1.0 <= geology <= 10.0:
        raise ValueError("geology resistance must lie between 1 and 10")
    if not 0.0 <= slope <= 90.0:
        raise ValueError("slope steepness must be given in degrees (0-90)")
    if rainfall < 0.0:
        raise ValueError("rainfall must be non-negative")
    steepness = slope / 45.0
    moisture = rainfall / 800.0
    return steepness * moisture * (11.0 - geology) / 10.0


def annual_retreat(
    undercut: float,
    weathering: float,
    geology: float,
) -> float:
    """Metres of shoreline lost per year from combined marine and land processes."""
    marine_part = 0.05 * undercut / geology
    land_part = 0.30 * weathering
    return marine_part * (1.0 + weathering) + land_part


def classify(
    rate: float,
) -> str:
    if rate < 0.05:
        return "stable"
    if rate < 0.20:
        return "moderate"
    if rate < 0.50:
        return "severe"
    return "critical"


def erosion(
    tide: float,
    wave: float,
    fetch: float,
    geology: float,
    slope: float,
    rainfall: float,
    decades: float,
) -> float:
    """Total metres of cliff lost over the requested number of decades."""
    if decades < 0.0:
        raise ValueError("decades must be non-negative")
    undercut = marine_undercut(tide, wave, fetch)
    weathering = terrestrial_weathering(geology, slope, rainfall)
    return annual_retreat(undercut, weathering, geology) * decades * 10.0


def format_report(
    site: str,
    total: float,
    rate: float,
) -> str:
    return f"{site:<14} {total:7.2f} m lost | {rate:.3f} m/yr ({classify(rate)})"


def main() -> None:
    sites = [
        ("Soft clay bay", 4.2, 3.5, 320.0, 2.0, 55.0, 950.0, 5.0),
        ("Chalk headland", 3.1, 2.0, 180.0, 7.0, 40.0, 700.0, 5.0),
        ("Granite point", 2.5, 1.5, 90.0, 10.0, 25.0, 600.0, 5.0),
    ]
    for name, tide, wave, fetch, geology, slope, rainfall, decades in sites:
        total = erosion(tide, wave, fetch, geology, slope, rainfall, decades)
        print(format_report(name, total, total / (decades * 10.0)))


if __name__ == "__main__":
    main()

