from statistics import mean


def _average(
    values: list[float],
) -> float:
    if not values:
        raise ValueError("at least one observation is required")
    return float(mean(values))


def _clamp(
    value: float,
    low: float,
    high: float,
) -> float:
    return max(low, min(high, value))


def social_engagement(
    avg_level: float,
    guild_rate: float,
    daily_playtime: float,
) -> float:
    level_term = _clamp(avg_level / 100.0, 0.0, 1.0) * 0.40
    guild_term = _clamp(guild_rate, 0.0, 1.0) * 0.35
    play_term = _clamp(daily_playtime / 6.0, 0.0, 1.0) * 0.25
    return _clamp(level_term + guild_term + play_term, 0.0, 1.0)


def monthly_churn(
    engagement: float,
    purchases: float,
    toxicity: float,
    updates: float,
) -> float:
    loyalty = _clamp(purchases / 200.0, 0.0, 0.12)
    content = _clamp(updates / 4.0, 0.0, 1.0) * 0.08
    raw = 0.30 - engagement * 0.20 + _clamp(toxicity, 0.0, 1.0) * 0.35
    return _clamp(raw - loyalty - content, 0.01, 0.95)


def retention(
    levels: list[float],
    guilds: list[float],
    playtime: list[float],
    purchases: float,
    toxicity: float,
    updates: float,
    months: int,
) -> float:
    if months < 0:
        raise ValueError("months cannot be negative")
    engagement = social_engagement(_average(levels), _average(guilds), _average(playtime))
    churn = monthly_churn(engagement, purchases, toxicity, updates)
    monthly_revenue = 5.0 + purchases * 0.08
    surviving = 1.0
    total = 0.0
    for _month in range(months):
        surviving *= 1.0 - churn
        total += surviving * monthly_revenue
    return round(total, 2)


def format_projection(
    label: str,
    revenue: float,
) -> str:
    return f"{label:<18} projected lifetime revenue: ${revenue:,.2f}"


def main() -> None:
    healthy = retention([72, 68, 80], [0.9, 0.75, 0.85], [4.0, 5.5, 3.0], 140.0, 0.05, 3.0, 24)
    toxic = retention([72, 68, 80], [0.4, 0.2, 0.3], [4.0, 5.5, 3.0], 140.0, 0.85, 1.0, 24)
    print(format_projection("Healthy server", healthy))
    print(format_projection("Toxic server", toxic))
    print(f"Toxicity cost per player: ${healthy - toxic:,.2f}")


if __name__ == "__main__":
    main()

