    ("Cabin oxygen", "%"), ("Hull temperature", "C"),
    ("Current velocity", "km/h"), ("Distance from Earth", "km"),
    ("Signal strength", "dB"), ("Navigation error", "deg"),
)


def format_reading(
    label,
    value,
    unit,
):
    return "{0:<22}{1:>14.3f} {2}".format(label, value, unit)


class ProbeTelemetry:
    def __init__(self):
        self._readings = {}

    def synchronize(self):
        self._readings = {
            "solar_voltage": random.uniform(18.0, 30.0),
            "fuel_level": random.uniform(0.0, 100.0),
            "oxygen": random.uniform(19.0, 23.0),
            "hull_temperature": random.uniform(-180.0, 60.0),
            "velocity": random.uniform(15000.0, 40000.0),
            "distance": random.uniform(100000.0, 900000.0),
            "signal_strength": random.uniform(40.0, 100.0),
            "navigation_error": random.uniform(0.0, 0.5),
        }

    def _reading(
        self,
        key,
    ):
        if not self._readings:
            raise RuntimeError("synchronize() must be called before reading telemetry")
        return round(self._readings[key], 3)

    def solar_panel_voltage(self):
        return self._reading("solar_voltage")

    def main_engine_fuel_level(self):
        return self._reading("fuel_level")

    def cabin_oxygen_concentration(self):
        return self._reading("oxygen")

    def external_hull_temperature(self):
        return self._reading("hull_temperature")

    def current_velocity(self):
        return self._reading("velocity")

    def distance_from_earth(self):
        return self._reading("distance")

    def communication_signal_strength(self):
        return self._reading("signal_strength")

    def navigation_error_margin(self):
        return self._reading("navigation_error")


def telemetry():
    probe = ProbeTelemetry()
    probe.synchronize()
    return [
        probe.solar_panel_voltage(), probe.main_engine_fuel_level(),
        probe.cabin_oxygen_concentration(), probe.external_hull_temperature(),
        probe.current_velocity(), probe.distance_from_earth(),
        probe.communication_signal_strength(), probe.navigation_error_margin(),
    ]


def main():
    readings = telemetry()
    print(readings)
    for value, (label, unit) in zip(readings, LABELS):
        print(format_reading(label, value, unit))


if __name__ == "__main__":
    main()

