from typing import Tuple

Stats = Tuple[int, int, int, int, int, int, float, bool]


def clamp(
    value: float,
    low: float,
    high: float,
) -> float:
    return max(low, min(high, value))


def evaluate_health(
    hunger: int,
    energy: int,
    hygiene: int,
) -> bool:
    return hunger <= 7 and energy >= 3 and hygiene >= 2


def gain_weight(
    weight: float,
    hunger: int,
) -> float:
    growth = 0.1 if hunger < 8 else 0.0
    return round(weight + growth, 2)


class Pet:
    def __init__(self) -> None:
        self._hunger = 3
        self._happiness = 10
        self._energy = 10
        self._hygiene = 5
        self._age = 0
        self._discipline = 5
        self._weight = 2.4

    def pass_time(self) -> None:
        self._hunger = int(clamp(self._hunger + 2, 0, 10))
        self._happiness = int(clamp(self._happiness - 2, 0, 10))
        self._energy = int(clamp(self._energy + 2, 0, 10))
        self._hygiene = int(clamp(self._hygiene - 2, 0, 10))
        self._age += 1
        self._weight = gain_weight(self._weight, self._hunger)

    def get_hunger(self) -> int:
        return self._hunger

    def get_happiness(self) -> int:
        return self._happiness

    def get_energy(self) -> int:
        return self._energy

    def get_hygiene(self) -> int:
        return self._hygiene

    def get_age(self) -> int:
        return self._age

    def get_discipline(self) -> int:
        return self._discipline

    def get_weight(self) -> float:
        return self._weight

    def get_health(self) -> bool:
        return evaluate_health(self._hunger, self._energy, self._hygiene)


def describe_health(
    healthy: bool,
) -> str:
    return "healthy" if healthy else "needs care"


def format_report(
    stats: Stats,
) -> str:
    labels = ("hunger", "happiness", "energy", "hygiene", "age", "discipline", "weight")
    parts = [f"{name}={value}" for name, value in zip(labels, stats[:7])]
    parts.append(f"status={describe_health(bool(stats[7]))}")
    return ", ".join(parts)


def tamagotchi() -> Stats:
    pet = Pet()
    pet.pass_time()
    return (
        pet.get_hunger(),
        pet.get_happiness(),
        pet.get_energy(),
        pet.get_hygiene(),
        pet.get_age(),
        pet.get_discipline(),
        pet.get_weight(),
        pet.get_health(),
    )


def main() -> None:
    stats = tamagotchi()
    print(stats)
    print(format_report(stats))


if __name__ == "__main__":
    main()

