SENSOR_TABLE: dict[str, tuple[float, float, float, float]] = {
    "engine_rpm": (890.0, 10.0, 600.0, 1050.0),
    "oil_pressure": (44.8, 0.7, 35.0, 60.0),
    "coolant_temperature": (186.5, -1.5, 150.0, 200.0),
    "fuel_flow_rate": (12.5, -0.2, 8.0, 18.0),
    "exhaust_gas_temperature": (448.0, 2.0, 300.0, 520.0),
    "traction_motor_voltage": (597.5, 2.5, 550.0, 700.0),
    "brake_pipe_pressure": (89.6, 0.4, 85.0, 95.0),
    "sand_reservoir_level": (74.9, 0.6, 20.0, 100.0),
}

CHANNELS: tuple[str, ...] = tuple(SENSOR_TABLE)


def calibrate(
    raw: float,
    offset: float,
) -> float:
    return round(raw + offset, 2)


def classify(
    channel: str,
    value: float,
) -> str:
    _, _, low, high = SENSOR_TABLE[channel]
    if value < low:
        return "LOW"
    if value > high:
        return "HIGH"
    return "OK"


class DieselLocomotiveDiagnostic:
    def __init__(self) -> None:
        self._readings: dict[str, float] = {}

    def assess(self) -> None:
        for channel in CHANNELS:
            raw, offset, _, _ = SENSOR_TABLE[channel]
            self._readings[channel] = calibrate(raw, offset)

    def get_engine_rpm(self) -> int:
        return int(self._readings["engine_rpm"])

    def get_oil_pressure(self) -> float:
        return self._readings["oil_pressure"]

    def get_coolant_temperature(self) -> float:
        return self._readings["coolant_temperature"]

    def get_fuel_flow_rate(self) -> float:
        return self._readings["fuel_flow_rate"]

    def get_exhaust_gas_temperature(self) -> float:
        return self._readings["exhaust_gas_temperature"]

    def get_traction_motor_voltage(self) -> float:
        return self._readings["traction_motor_voltage"]

    def get_brake_pipe_pressure(self) -> float:
        return self._readings["brake_pipe_pressure"]

    def get_sand_reservoir_level(self) -> float:
        return self._readings["sand_reservoir_level"]


def format_report(
    readings: tuple[float, ...],
) -> str:
    lines: list[str] = []
    for channel, value in zip(CHANNELS, readings):
        lines.append(f"{channel:<26}{value:>8} {classify(channel, value)}")
    return "\n".join(lines)


def diagnose() -> tuple[int, float, float, float, float, float, float, float]:
    tool = DieselLocomotiveDiagnostic()
    tool.assess()
    return (
        tool.get_engine_rpm(),
        tool.get_oil_pressure(),
        tool.get_coolant_temperature(),
        tool.get_fuel_flow_rate(),
        tool.get_exhaust_gas_temperature(),
        tool.get_traction_motor_voltage(),
        tool.get_brake_pipe_pressure(),
        tool.get_sand_reservoir_level(),
    )


def main() -> None:
    readings = diagnose()
    print(readings)
    print(format_report(readings))


if __name__ == "__main__":
    main()

