import random


WAVEFORMS = ["sine", "triangle", "sawtooth", "square", "pulse", "noise"]


def quantize(
    value: float,
    step: float,
) -> float:
    return round(round(value / step) * step, 3)


class PatchGenerator:
    def __init__(self) -> None:
        self._waveform = WAVEFORMS[0]
        self._detune = 0
        self._cutoff = 20000.0
        self._resonance = 0.0
        self._attack = 1.0
        self._decay = 1.0
        self._sustain = 1.0
        self._release = 1.0

    def randomize(self) -> None:
        self._waveform = random.choice(WAVEFORMS)
        self._detune = random.randint(-12, 12)
        self._cutoff = quantize(random.uniform(80.0, 12000.0), 50.0)
        self._resonance = round(random.uniform(0.0, 1.0), 2)
        self._attack = quantize(random.uniform(1.0, 500.0), 0.5)
        self._decay = quantize(random.uniform(10.0, 900.0), 0.5)
        self._sustain = round(random.uniform(0.0, 1.0), 2)
        self._release = quantize(random.uniform(10.0, 2000.0), 0.5)

    def get_waveform(self) -> str:
        return self._waveform

    def get_detune(self) -> int:
        return self._detune

    def get_cutoff(self) -> float:
        return self._cutoff

    def get_resonance(self) -> float:
        return self._resonance

    def get_attack(self) -> float:
        return self._attack

    def get_decay(self) -> float:
        return self._decay

    def get_sustain(self) -> float:
        return self._sustain

    def get_release(self) -> float:
        return self._release


def synthesize() -> list[object]:
    generator = PatchGenerator()
    generator.randomize()
    return [
        generator.get_waveform(),
        generator.get_detune(),
        generator.get_cutoff(),
        generator.get_resonance(),
        generator.get_attack(),
        generator.get_decay(),
        generator.get_sustain(),
        generator.get_release(),
    ]


def envelope_length(
    attack: float,
    decay: float,
    release: float,
) -> float:
    return round(attack + decay + release, 3)


def format_patch(
    patch: list[object],
) -> str:
    labels = [
        "osc1", "detune", "cutoff", "resonance",
        "attack", "decay", "sustain", "release",
    ]
    return " | ".join(f"{name}={value}" for name, value in zip(labels, patch))


def main() -> None:
    patch = synthesize()
    print(patch)
    print(format_patch(patch))
    total = envelope_length(float(patch[4]), float(patch[5]), float(patch[7]))
    print(f"envelope spans {total} ms")


if __name__ == "__main__":
    main()

