import random

ABILITY_NAMES = ("strength", "dexterity", "constitution", "intelligence", "wisdom", "charisma")


def roll_ability(
    rng: random.Random,
) -> int:
    dice = sorted(rng.randint(1, 6) for _ in range(4))
    return sum(dice[1:])


def armor_class_from(
    dexterity: int,
) -> int:
    return 10 + (dexterity - 10) // 2


def max_hit_points_from(
    constitution: int,
) -> int:
    return max(1, 8 + (constitution - 10) // 2)


class AttributeGenerator:
    def __init__(self) -> None:
        self._rng = random.Random()
        self._scores = {}

    def roll(self) -> None:
        self._scores = {name: roll_ability(self._rng) for name in ABILITY_NAMES}

    def _score(
        self,
        name: str,
    ) -> int:
        if not self._scores:
            raise RuntimeError("statistics have not been rolled yet")
        return self._scores[name]

    def strength(self) -> int:
        return self._score("strength")

    def dexterity(self) -> int:
        return self._score("dexterity")

    def constitution(self) -> int:
        return self._score("constitution")

    def intelligence(self) -> int:
        return self._score("intelligence")

    def wisdom(self) -> int:
        return self._score("wisdom")

    def charisma(self) -> int:
        return self._score("charisma")

    def armor_class(self) -> int:
        return armor_class_from(self.dexterity())

    def max_hit_points(self) -> int:
        return max_hit_points_from(self.constitution())


def character() -> tuple[int, ...]:
    hero = AttributeGenerator()
    hero.roll()
    return (
        hero.strength(),
        hero.dexterity(),
        hero.constitution(),
        hero.intelligence(),
        hero.wisdom(),
        hero.charisma(),
        hero.armor_class(),
        hero.max_hit_points(),
    )


def format_sheet(
    stats: tuple[int, ...],
) -> str:
    labels = ABILITY_NAMES + ("armor class", "hit points")
    rows = [f"{label.title():<13}{value:>3}" for label, value in zip(labels, stats)]
    return "\n".join(rows)


def main() -> None:
    stats = character()
    print(stats)
    print(format_sheet(stats))


if __name__ == "__main__":
    main()

