import math


def kinetic_energy(
    momentum_gev: float,
    rest_mass_gev: float,
) -> float:
    return round(math.hypot(momentum_gev, rest_mass_gev) - rest_mass_gev, 1)

def format_report(
    label: str,
    value: float,
    unit: str,
) -> str:
    return f"{label:<26}{value:>12g}  {unit}"

class BeamLineSimulator:
    def __init__(self) -> None:
        self._readings: dict[str, float] = {}

    def scan(self) -> None:
        momentum_gev = 6500.938272
        energy = kinetic_energy(momentum_gev, 0.938272)
        self._readings = {
            "energy": energy,
            "intensity": round(16.1e-9 / 1.602176634e-19 / 1e9, 1),
            "field": round(momentum_gev / (0.299792458 * 2612.6), 1),
            "pressure": round(5.0e-5 + 1.0e-4 / 2.0, 8),
            "voltage": round(1.25 / math.sin(math.radians(30.0)), 1),
            "loss": round(5.0e7 * energy * 1.602176634e-10 / 1041.0, 2),
            "helium": round(100.0 * 4750.0 / 5000.0, 1),
            "collisions": round(1.0e34 * 5.0e-29),
        }

    def beam_kinetic_energy(self) -> float:
        return self._readings["energy"]

