from __future__ import annotations

RAW_FRAME: dict[str, int] = {
    "altitude_counts": 3500,
    "airspeed_counts": 900,
    "vertical_speed_counts": 0,
    "pitch_counts": 250,
    "roll_counts": 0,
    "heading_counts": 2700,
    "oat_counts": -500,
    "ap_status_word": 1,
}

PARAMETER_LABELS: tuple[str, ...] = (
    "Cruising altitude (ft)",
    "Indicated airspeed (kt)",
    "Vertical speed (fpm)",
    "Pitch angle (deg)",
    "Roll angle (deg)",
    "True heading (deg)",
    "Outside air temperature (C)",
    "Autopilot engaged",
)


def _scale_count(
    raw: int,
    factor: float,
) -> float:
    return raw * factor


def _quantize(
    value: float,
) -> int:
    return int(round(value))


class AutopilotTelemetry:
    def __init__(self) -> None:
        self._frame: dict[str, int] = {}

    def sync(self) -> None:
        self._frame = dict(RAW_FRAME)

    def _word(
        self,
        name: str,
    ) -> int:
        if not self._frame:
            raise RuntimeError("telemetry bus has not been synced")
        return self._frame[name]

    def check_cruising_altitude(self) -> int:
        return _quantize(_scale_count(self._word("altitude_counts"), 10.0))

    def check_indicated_airspeed(self) -> int:
        return _quantize(_scale_count(self._word("airspeed_counts"), 0.5))

    def check_vertical_speed(self) -> int:
        return _quantize(_scale_count(self._word("vertical_speed_counts"), 1.0))

    def check_pitch_angle(self) -> float:
        return round(_scale_count(self._word("pitch_counts"), 0.01), 2)

    def check_roll_angle(self) -> float:
        return round(_scale_count(self._word("roll_counts"), 0.01), 2)

    def check_true_heading(self) -> int:
        return _quantize(_scale_count(self._word("heading_counts"), 0.1)) % 360

    def check_outside_air_temperature(self) -> int:
        return _quantize(_scale_count(self._word("oat_counts"), 0.1))

    def check_autopilot_engaged(self) -> bool:
        return self._word("ap_status_word") == 1


def autopilot() -> list[object]:
    unit = AutopilotTelemetry()
    unit.sync()
    return [
        unit.check_cruising_altitude(),
        unit.check_indicated_airspeed(),
        unit.check_vertical_speed(),
        unit.check_pitch_angle(),
        unit.check_roll_angle(),
        unit.check_true_heading(),
        unit.check_outside_air_temperature(),
        unit.check_autopilot_engaged(),
    ]


def format_report(
    values: list[object],
) -> str:
    rows: list[str] = []
    for label, value in zip(PARAMETER_LABELS, values):
        rows.append(f"{label:<30}{value}")
    return "\n".join(rows)


def main() -> None:
    readings: list[object] = autopilot()
    print(readings)
    print(format_report(readings))


if __name__ == "__main__":
    main()

