import random
from typing import Tuple

CheckoutState = Tuple[int, float, float, float, float, bool, int, bool]
TAX_RATE = 0.085


def format_currency(
    amount: float,
) -> str:
    return f"${amount:,.2f}"


def compute_total(
    subtotal: float,
    tax: float,
    discount: float,
) -> float:
    return round(max(subtotal + tax - discount, 0.0), 2)


def describe_hardware(
    scanner_ok: bool,
    paper_level: int,
    payment_ready: bool,
) -> str:
    scanner = "online" if scanner_ok else "FAULT"
    printer = "low paper" if paper_level < 20 else "ok"
    terminal = "ready" if payment_ready else "blocked"
    return f"scanner {scanner}, printer {printer} ({paper_level}%), payment {terminal}"


class SelfCheckoutTerminal:
    def __init__(self) -> None:
        self._items: int = 0
        self._subtotal: float = 0.0
        self._tax = 0.0
        self._discount = 0.0
        self._scale_weight = 0.0
        self._scanner_ok = True
        self._paper_level = 100
        self._payment_ready = True

    def simulate(self) -> None:
        self._items = random.randint(1, 40)
        self._subtotal = round(random.uniform(2.0, 300.0), 2)
        self._tax = round(self._subtotal * TAX_RATE, 2)
        self._discount = round(self._subtotal * random.choice([0.0, 0.05, 0.1]), 2)
        self._scale_weight = round(random.choice([0.0, random.uniform(0.05, 3.0)]), 2)
        self._scanner_ok = random.random() > 0.08
        self._paper_level = random.randint(0, 100)
        self._payment_ready = self._scanner_ok and self._paper_level > 5

    def get_item_count(self) -> int:
        return self._items

    def get_subtotal(self) -> float:
        return self._subtotal

    def get_tax_amount(self) -> float:
        return self._tax

    def get_discount_total(self) -> float:
        return self._discount

    def get_scale_weight(self) -> float:
        return self._scale_weight

    def get_scanner_status(self) -> bool:
        return self._scanner_ok

    def get_paper_level(self) -> int:
        return self._paper_level

    def get_payment_ready(self) -> bool:
        return self._payment_ready


def checkout() -> CheckoutState:
    terminal = SelfCheckoutTerminal()
    terminal.simulate()
    return (
        terminal.get_item_count(),
        terminal.get_subtotal(),
        terminal.get_tax_amount(),
        terminal.get_discount_total(),
        terminal.get_scale_weight(),
        terminal.get_scanner_status(),
        terminal.get_paper_level(),
        terminal.get_payment_ready(),
    )


def build_report(
    state: CheckoutState,
) -> str:
    items, subtotal, tax, discount, weight, scanner, paper, payment = state
    total = compute_total(subtotal, tax, discount)
    lines = [
        f"items scanned: {items}",
        f"subtotal: {format_currency(subtotal)}  tax: {format_currency(tax)}",
        f"discounts: -{format_currency(discount)}  total due: {format_currency(total)}",
        f"unexpected weight on scale: {weight} kg",
        describe_hardware(scanner, paper, payment),
    ]
    return "\n".join(lines)


def main() -> None:
    state = checkout()
    print(state)
    print(build_report(state))


if __name__ == "__main__":
    main()

