import random

Metrics = tuple[float, float, float, float, float, float, float, bool]

LABELS = ("lamp", "rotation", "battery", "solar", "foghorn", "wind", "tower", "daylight")


class LighthouseDiagnosticNode:
    def __init__(self) -> None:
        self._rng = random.Random(20260918)
        self._readings = {}

    def _sample(self,
                key: str,
                span: tuple[float, float],
                ) -> None:
        self._readings[key] = round(self._rng.uniform(*span), 1)

    def _require(self,
                 key: str,
                 ) -> float:
        if key not in self._readings:
            raise RuntimeError("self test has not been run on this node")
        return self._readings[key]

    def run_self_test(self) -> None:
        self._sample("lamp", (9200.0, 10400.0))
        self._sample("rotation", (4.8, 6.2))
        self._sample("battery", (72.0, 99.0))
        self._sample("solar", (15.0, 480.0))
        self._sample("foghorn", (95.0, 135.0))
        self._sample("wind", (5.0, 88.0))
        self._sample("temperature", (4.0, 27.0))

    def read_lamp_intensity(self) -> float:
        return self._require("lamp")

    def read_rotation_speed(self) -> float:
        return self._require("rotation")

    def read_battery_charge(self) -> float:
        return self._require("battery")

    def read_solar_output(self) -> float:
        return self._require("solar")

    def read_foghorn_pressure(self) -> float:
        return self._require("foghorn")

    def read_wind_speed(self) -> float:
        return self._require("wind")

    def read_tower_temperature(self) -> float:
        return self._require("temperature")

    def read_daylight_sensor(self) -> bool:
        return self._require("solar") > 200.0


def lighthouse() -> Metrics:
    node = LighthouseDiagnosticNode()
    node.run_self_test()
    return (node.read_lamp_intensity(), node.read_rotation_speed(),
            node.read_battery_charge(), node.read_solar_output(),
            node.read_foghorn_pressure(), node.read_wind_speed(),
            node.read_tower_temperature(), node.read_daylight_sensor())


def format_report(metrics: Metrics,
                  ) -> str:
    return "\n".join(f"{label:<12}{value}"
                     for label, value in zip(LABELS, metrics))


def main() -> None:
    print(format_report(lighthouse()))


if __name__ == "__main__":
    main()

