from __future__ import annotations

import math

BALANCE_CHAMBER_ML = 20.0
PULSES_PER_CHAMBER_CYCLE = 3
AIR_ALARM_THRESHOLD_UL = 50.0


def _filter_sample(
    previous: float,
    target: float,
    alpha: float,
) -> float:
    """First-order sensor filter: readings ease toward the hydraulic target."""
    return previous + alpha * (target - previous)


def _round_reading(
    value: float,
    digits: int,
) -> float:
    return round(value, digits)


def remaining_fluid(
    goal_ml: float,
    removed_ml: float,
) -> float:
    return max(0.0, goal_ml - removed_ml)


class DialysisMonitor:
    def __init__(self) -> None:
        self._blood_pump_rpm = 150.0
        self._blood_flow = 300.0
        self._dialysate_flow = 500.0
        self._venous_pressure = 150.0
        self._arterial_pressure = -100.0
        self._removal_goal = 2000.0
        self._chamber_cycles = 40
        self._chamber_progress = 0
        self._temperature = 37.0
        self._air_volume_ul = 0.0

    def pulse(self) -> None:
        self._chamber_progress += 1
        if self._chamber_progress >= PULSES_PER_CHAMBER_CYCLE:
            self._chamber_progress = 0
            self._chamber_cycles += 1
        self._blood_flow = _filter_sample(self._blood_flow, self._blood_pump_rpm * 2.0, 0.5)
        self._dialysate_flow = _filter_sample(self._dialysate_flow, 500.0, 0.5)
        self._venous_pressure = _filter_sample(self._venous_pressure, self._blood_flow * 0.5, 0.4)
        self._arterial_pressure = _filter_sample(self._arterial_pressure, -self._blood_flow / 3.0, 0.4)
        self._temperature = _filter_sample(self._temperature, 37.0, 0.3)
        self._air_volume_ul = _filter_sample(self._air_volume_ul, 0.0, 0.6)

    def get_blood_flow_rate(self) -> float:
        return _round_reading(self._blood_flow, 1)

    def get_dialysate_flow_rate(self) -> float:
        return _round_reading(self._dialysate_flow, 1)

    def get_venous_pressure(self) -> float:
        return _round_reading(self._venous_pressure, 1)

    def get_arterial_pressure(self) -> float:
        return _round_reading(self._arterial_pressure, 1)

    def get_fluid_removal_goal(self) -> float:
        return _round_reading(self._removal_goal, 1)

    def get_fluid_removed(self) -> float:
        measured = min(self._removal_goal, self._chamber_cycles * BALANCE_CHAMBER_ML)
        return _round_reading(measured, 1)

    def get_dialysate_temperature(self) -> float:
        return _round_reading(self._temperature, 1)

    def get_air_bubble_detected(self) -> bool:
        return self._air_volume_ul > AIR_ALARM_THRESHOLD_UL


def dialysis() -> list[float | bool]:
    monitor = DialysisMonitor()
    monitor.pulse()
    return [
        monitor.get_blood_flow_rate(),
        monitor.get_dialysate_flow_rate(),
        monitor.get_venous_pressure(),
        monitor.get_arterial_pressure(),
        monitor.get_fluid_removal_goal(),
        monitor.get_fluid_removed(),
        monitor.get_dialysate_temperature(),
        monitor.get_air_bubble_detected(),
    ]


def format_report(
    readings: list[float | bool],
) -> str:
    labels = [
        "blood flow (mL/min)",
        "dialysate flow (mL/min)",
        "venous pressure (mmHg)",
        "arterial pressure (mmHg)",
        "removal goal (mL)",
        "fluid removed (mL)",
        "dialysate temp (C)",
        "air bubble alarm",
    ]
    lines = [f"{name:<26}{value}" for name, value in zip(labels, readings)]
    left = remaining_fluid(float(readings[4]), float(readings[5]))
    lines.append(f"{'remaining (mL)':<26}{left}")
    lines.append(f"{'hydraulic balance':<26}{math.isclose(float(readings[1]), 500.0)}")
    return "\n".join(lines)


def main() -> None:
    readings = dialysis()
    print(readings)
    print(format_report(readings))


if __name__ == "__main__":
    main()

