RAW_FRAME: str = (
    "speed=2.5;payload=4500.0;bearing_temp=65.0;motor_current=120.0;"
    "tension=3000.0;water_flow=15.0;vibration=0.8;pull_cord=0"
)

CHANNEL_LABELS: list[str] = [
    "belt speed (m/s)",
    "ore payload (kg)",
    "bearing temp (C)",
    "motor current (A)",
    "belt tension (N)",
    "water flow (L/min)",
    "vibration (mm/s)",
    "pull cord tripped",
]


def parse_frame(
    frame: str,
) -> dict[str, str]:
    fields: dict[str, str] = {}
    for chunk in frame.split(";"):
        key, _, value = chunk.partition("=")
        fields[key.strip()] = value.strip()
    return fields


def read_measure(
    fields: dict[str, str],
    channel: str,
) -> float:
    if channel not in fields:
        raise KeyError(f"missing telemetry channel: {channel}")
    return float(fields[channel])


def read_flag(
    fields: dict[str, str],
    channel: str,
) -> bool:
    return read_measure(fields, channel) != 0.0


class ConveyorDiagnostics:
    def __init__(self) -> None:
        self._log: dict[str, str] = {}

    def survey(self) -> None:
        self._log = parse_frame(RAW_FRAME)

    def belt_speed(self) -> float:
        return read_measure(self._log, "speed")

    def ore_payload(self) -> float:
        return read_measure(self._log, "payload")

    def bearing_temperature(self) -> float:
        return read_measure(self._log, "bearing_temp")

    def motor_current(self) -> float:
        return read_measure(self._log, "motor_current")

    def belt_tension(self) -> float:
        return read_measure(self._log, "tension")

    def water_flow(self) -> float:
        return read_measure(self._log, "water_flow")

    def vibration_level(self) -> float:
        return read_measure(self._log, "vibration")

    def pull_cord_tripped(self) -> bool:
        return read_flag(self._log, "pull_cord")


def format_report(
    values: list[float | bool],
) -> str:
    lines: list[str] = []
    for label, value in zip(CHANNEL_LABELS, values):
        lines.append(f"{label:<20}{value}")
    return "\n".join(lines)


def conveyor() -> list[float | bool]:
