from __future__ import annotations

RAW_SENSOR_FRAMES = {
    "rod_insertion": 850,
    "primary_flow": 100000,
    "secondary_flow": 80000,
    "core_temperature": 3150,
    "vessel_pressure": 120,
    "radiation_level": 5,
    "turbine_speed": 36000,
    "scram_latch": 1,
}


def _clamp(
    value: float,
    low: float,
    high: float,
) -> float:
    return max(low, min(high, value))


class ReactorControlCenter:
    def __init__(self) -> None:
        self._frames = {}

    def synchronize(self) -> None:
        self._frames = dict(RAW_SENSOR_FRAMES)

    def _decode(
        self,
        channel: str,
        factor: float,
    ) -> float:
        if channel not in self._frames:
            raise RuntimeError(f"sensor bus not synchronized for {channel}")
        return round(self._frames[channel] * factor, 6)

    def get_control_rod_insertion(self) -> float:
        return _clamp(self._decode("rod_insertion", 0.1), 0.0, 100.0)

    def get_primary_coolant_flow(self) -> float:
        return self._decode("primary_flow", 0.1)

    def get_secondary_coolant_flow(self) -> float:
        return self._decode("secondary_flow", 0.1)

    def get_core_temperature(self) -> float:
        return self._decode("core_temperature", 0.1)

    def get_vessel_pressure(self) -> float:
        return self._decode("vessel_pressure", 0.01)

    def get_radiation_containment(self) -> float:
        return self._decode("radiation_level", 0.01)

    def get_turbine_speed(self) -> float:
        return self._decode("turbine_speed", 0.1)

    def get_scram_readiness(self) -> bool:
        return self._decode("scram_latch", 1.0) == 1.0


def format_readings(
    readings: tuple[float, float, float, float, float, float, float, bool],
) -> str:
    labels = (
        "rod insertion %", "primary flow", "secondary flow", "core temp C",
        "vessel pressure MPa", "radiation level", "turbine rpm", "scram ready",
    )
    return "\n".join(f"{name:>20}: {value}" for name, value in zip(labels, readings))


def reactor() -> tuple[float, float, float, float, float, float, float, bool]:
    center = ReactorControlCenter()
    center.synchronize()
    return (
        center.get_control_rod_insertion(),
        center.get_primary_coolant_flow(),
        center.get_secondary_coolant_flow(),
        center.get_core_temperature(),
        center.get_vessel_pressure(),
        center.get_radiation_containment(),
        center.get_turbine_speed(),
        center.get_scram_readiness(),
    )


def main() -> None:
    plant_state = reactor()
    print(plant_state)
    print(format_readings(plant_state))


if __name__ == "__main__":
    main()

