LIMITS = {
    "chamber": (1150.0, 1250.0),
    "cooling": (350.0, 450.0),
    "belt": (1.0, 2.0),
    "gas": (2.0, 3.0),
    "oxygen": (18.0, 22.0),
    "stress": (0.0, 8.0),
    "draft": (120.0, 180.0),
}

CHANNELS = [
    ("chamber", "Heating chamber", "C"),
    ("cooling", "Cooling zone", "C"),
    ("belt", "Belt speed", "m/min"),
    ("gas", "Gas pressure", "bar"),
    ("oxygen", "Oxygen mixture", "%"),
    ("stress", "Thermal stress", "MPa"),
    ("draft", "Exhaust draft", "m3/min"),
]


class AnnealingKilnTelemetry:
    def __init__(self) -> None:
        self._raw = {}

    def measure(self) -> None:
        self._raw = {
            "chamber_counts": 12000,
            "cooling_counts": 4000,
            "belt_pulses": 150,
            "gas_counts": 250,
            "oxygen_counts": 2000,
            "draft_counts": 1500,
            "seal_leak_ppm": 6,
        }

    def chamber_temperature(self) -> float:
        return self._raw["chamber_counts"] / 10.0

    def cooling_zone_temperature(self) -> float:
        return self._raw["cooling_counts"] / 10.0

    def belt_speed(self) -> float:
        return self._raw["belt_pulses"] / 100.0

    def gas_pressure(self) -> float:
        return self._raw["gas_counts"] / 100.0

    def oxygen_ratio(self) -> float:
        return self._raw["oxygen_counts"] / 100.0

    def thermal_stress(self) -> float:
        gradient = self.chamber_temperature() - self.cooling_zone_temperature()
        return round(gradient / 160.0, 3)

    def exhaust_draft(self) -> float:
        return self._raw["draft_counts"] / 10.0

    def door_seal_intact(self) -> bool:
        return self._raw["seal_leak_ppm"] <= 10


def format_reading(
    label: str,
    value: float,
    unit: str,
    low: float,
    high: float,
) -> str:
    status = "OK" if low <= value <= high else "ALARM"
    return f"{label:<16} {value:>8.2f} {unit:<7} {status}"


def build_report(
    readings: tuple,
) -> list:
    lines = []
    for (key, label, unit), value in zip(CHANNELS, readings[:7]):
        low, high = LIMITS[key]
        lines.append(format_reading(label, float(value), unit, low, high))
    seal_state = "sealed" if readings[7] else "breached"
    lines.append(f"{'Door seal':<16} {seal_state}")
    return lines


def kiln() -> tuple:
    probe = AnnealingKilnTelemetry()
    probe.measure()
    return (
        probe.chamber_temperature(),
        probe.cooling_zone_temperature(),
        probe.belt_speed(),
        probe.gas_pressure(),
        probe.oxygen_ratio(),
        probe.thermal_stress(),
        probe.exhaust_draft(),
        probe.door_seal_intact(),
    )


def main() -> None:
    readings = kiln()
    print(readings)
    for line in build_report(readings):
        print(line)


if __name__ == "__main__":
    main()

