        return self._raw["chamber_counts"] / 10.0

    def cooling_zone_temperature(self):
        return self._raw["cooling_counts"] / 10.0

    def belt_speed(self):
        return self._raw["belt_pulses"] / 100.0

    def gas_pressure(self):
        return self._raw["gas_counts"] / 100.0

    def oxygen_ratio(self):
        return self._raw["oxygen_counts"] / 100.0

    def thermal_stress(self):
        gradient = self.chamber_temperature() - self.cooling_zone_temperature()
        return round(gradient / 160.0, 3)

    def exhaust_draft(self):
        return self._raw["draft_counts"] / 10.0

    def door_seal_intact(self):
        return self._raw["seal_leak_ppm"] <= 10


def format_reading(
    label,
    value,
    unit,
    low,
    high,
):
    status = "OK" if low <= value <= high else "ALARM"
    return f"{label:<16} {value:>8.2f} {unit:<7} {status}"


def build_report(
    readings,
):
    lines = []
    for (key, label, unit), value in zip(CHANNELS, readings[:7]):
        low, high = LIMITS[key]
        lines.append(format_reading(label, float(value), unit, low, high))
    seal_state = "sealed" if readings[7] else "breached"
    lines.append(f"{'Door seal':<16} {seal_state}")
    return lines


def kiln():
    probe = AnnealingKilnTelemetry()
    probe.measure()
    return (
        probe.chamber_temperature(),
        probe.cooling_zone_temperature(),
        probe.belt_speed(),
        probe.gas_pressure(),
        probe.oxygen_ratio(),
        probe.thermal_stress(),
        probe.exhaust_draft(),
        probe.door_seal_intact(),
    )


def main():
    readings = kiln()
    print(readings)
    for line in build_report(readings):
        print(line)


if __name__ == "__main__":
    main()

