from math import sqrt

REQUIRED_KEYS = ("wind", "wave", "hull", "lake")
APPROACH_FACTOR = 1.05
WIND_CREDIT = 0.5
WAVE_PENALTY = 0.5
DRAG_CONSTANT = 48.0


def validate_conditions(
    conditions: dict[str, float],
) -> dict[str, float]:
    checked = {}
    for key in REQUIRED_KEYS:
        if key not in conditions:
            raise KeyError(f"missing condition: {key}")
        value = float(conditions[key])
        if value < 0.0:
            raise ValueError(f"condition {key} must not be negative")
        checked[key] = value
    return checked


def approach_speed(
    weight: float,
    headwind: float,
) -> float:
    if weight <= 0.0:
        raise ValueError("weight must be positive")
    return APPROACH_FACTOR * sqrt(weight) - WIND_CREDIT * headwind


def hydrodynamic_drag(
    speed: float,
    wave_height: float,
    hull_index: float,
) -> float:
    wave_factor = 1.0 + WAVE_PENALTY * wave_height
    return DRAG_CONSTANT * hull_index * wave_factor * speed


def deceleration(
    drag: float,
    weight: float,
) -> float:
    return drag / weight


def stopping_distance(
    speed: float,
    decel: float,
) -> float:
    if decel <= 0.0:
        raise ValueError("hull produces no retarding force")
    return speed ** 2 / (2.0 * decel)


def round_to_ten(
    distance: float,
) -> float:
    return round(distance / 10.0) * 10.0


def calculate(
    weight: float,
    conditions: dict[str, float],
) -> float:
    checked = validate_conditions(conditions)
    speed = approach_speed(weight, checked["wind"])
    drag = hydrodynamic_drag(speed, checked["wave"], checked["hull"])
    decel = deceleration(drag, weight)
    total = round_to_ten(stopping_distance(speed, decel))
    if total > checked["lake"]:
        return -total
    return total


def format_report(
    weight: float,
    distance: float,
) -> str:
    label = f"{weight:.0f} lb seaplane"
    if distance < 0.0:
        return f"{label}: overrun, needs {abs(distance):.0f} ft of water"
    return f"{label}: stops in {distance:.0f} ft"


def main() -> None:
    scenarios = [
        (5000.0, {"wind": 10.0, "wave": 2.0, "hull": 1.5, "lake": 2000.0}),
        (7200.0, {"wind": 4.0, "wave": 3.5, "hull": 2.2, "lake": 900.0}),
    ]
    for weight, conditions in scenarios:
        print(format_report(weight, calculate(weight, conditions)))


if __name__ == "__main__":
    main()

