from __future__ import annotations

import math

CLEARANCE_PER_GFR = 0.0056


def validate(
    dosage: dict[str, float],
    patient: dict[str, float],
) -> None:
    if dosage["amount_mg"] <= 0.0 or dosage["target_mg_per_l"] <= 0.0:
        raise ValueError("dose amount and target concentration must be positive")
    if not 0.0 < dosage["tissue_factor"] <= 1.0:
        raise ValueError("tissue binding factor must lie in (0, 1]")
    if patient["mass_kg"] <= 0.0:
        raise ValueError("body mass must be positive")
    if patient["liver_score"] <= 0.0 or patient["kidney_gfr"] <= 0.0:
        raise ValueError("liver score and kidney filtration rate must be positive")


def volume_of_distribution(
    mass_kg: float,
    tissue_factor: float,
) -> float:
    """Apparent volume of distribution in litres."""
    return mass_kg * tissue_factor


def total_clearance(
    liver_score: float,
    kidney_gfr: float,
) -> float:
    """Combined hepatic/renal clearance in litres per hour."""
    return liver_score * kidney_gfr * CLEARANCE_PER_GFR


def elimination_rate_constant(
    clearance_l_per_h: float,
    volume_l: float,
) -> float:
    return clearance_l_per_h / volume_l


def half_life(
    rate_constant: float,
) -> float:
    return math.log(2.0) / rate_constant


def hours_to_threshold(
    amount_mg: float,
    volume_l: float,
    target_mg_per_l: float,
    half_life_h: float,
) -> float:
    initial = amount_mg / volume_l
    if initial <= target_mg_per_l:
        return 0.0
    return half_life_h * math.log2(initial / target_mg_per_l)


def clearance(
    dosage: dict[str, float],
    patient: dict[str, float],
) -> float:
    validate(dosage, patient)
    volume = volume_of_distribution(patient["mass_kg"], dosage["tissue_factor"])
    cleared = total_clearance(patient["liver_score"], patient["kidney_gfr"])
    rate = elimination_rate_constant(cleared, volume)
    span = half_life(rate)
    hours = hours_to_threshold(
        dosage["amount_mg"], volume, dosage["target_mg_per_l"], span
    )
    return round(hours, 1)


def format_report(
    dosage: dict[str, float],
    patient: dict[str, float],
    hours: float,
) -> str:
    return (
        f"{dosage['amount_mg']:.0f} mg in a {patient['mass_kg']:.0f} kg patient "
        f"falls below {dosage['target_mg_per_l']:.0f} mg/L after {hours} hours"
    )


def main() -> None:
    dosage = {"amount_mg": 500.0, "target_mg_per_l": 10.0, "tissue_factor": 0.6}
    patient = {"mass_kg": 70.0, "liver_score": 1.0, "kidney_gfr": 90.0}
    print(format_report(dosage, patient, clearance(dosage, patient)))


if __name__ == "__main__":
    main()

