from math import ceil

REFERENCE_DEPTH = 3000.0
DEPTH_SLACK = 0.03
CURRENT_SLACK = 0.01
BASE_LAYING_SPEED = 600.0
SPEED_PENALTY_PER_REPEATER = 2.0
PROFILE_KEYS = ("depth", "current", "attenuation")


def validate_plan(
    distance: float,
    seabed: dict[str, float],
) -> dict[str, float]:
    if distance <= 0.0:
        raise ValueError("distance must be a positive number of kilometres")
    missing = [key for key in PROFILE_KEYS if key not in seabed]
    if missing:
        raise KeyError("seabed profile lacks: " + ", ".join(missing))
    if seabed["depth"] <= 0.0:
        raise ValueError("seabed depth must be positive")
    if seabed["current"] < 0.0:
        raise ValueError("ocean current speed cannot be negative")
    if seabed["attenuation"] <= 0.0:
        raise ValueError("attenuation limit must be positive")
    return {key: float(seabed[key]) for key in PROFILE_KEYS}


def slack_factor(
    depth: float,
    current: float,
) -> float:
    depth_share = depth / REFERENCE_DEPTH * DEPTH_SLACK
    current_share = current * CURRENT_SLACK
    return depth_share + current_share


def cable_length(
    distance: float,
    slack: float,
) -> float:
    return round(distance * (1.0 + slack), 1)


def repeater_count(
    length: float,
    attenuation: float,
) -> int:
    return ceil(length / attenuation)


def deployment_days(
    length: float,
    repeaters: int,
) -> int:
    speed = BASE_LAYING_SPEED - SPEED_PENALTY_PER_REPEATER * repeaters
    if speed <= 0.0:
        raise ValueError("too many repeaters: the ship cannot advance")
    return ceil(length / speed)


def route(
    distance: float,
    seabed: dict[str, float],
) -> tuple[float, int, int]:
    profile = validate_plan(distance, seabed)
    slack = slack_factor(profile["depth"], profile["current"])
    length = cable_length(distance, slack)
    repeaters = repeater_count(length, profile["attenuation"])
    return length, repeaters, deployment_days(length, repeaters)


def format_report(
    distance: float,
    plan: tuple[float, int, int],
) -> str:
    length, repeaters, days = plan
    return (
        f"Route span: {distance:.1f} km\n"
        f"Cable to load: {length:.1f} km\n"
        f"Optical repeaters: {repeaters}\n"
        f"Deployment time: {days} days"
    )


def main() -> None:
    seabed: dict[str, float] = {"depth": 3000.0, "current": 2.0, "attenuation": 100.0}
    print(format_report(8000.0, route(8000.0, seabed)))


if __name__ == "__main__":
    main()

