from typing import Mapping

Pattern = Mapping[str, float]
Cord = Mapping[str, float]


def require_non_negative(
    label: str,
    value: float,
) -> float:
    if value < 0:
        raise ValueError(f"{label} must not be negative (got {value})")
    return value


def read_measure(
    source: Mapping[str, float],
    key: str,
) -> float:
    if key not in source:
        raise KeyError(f"measurement '{key}' is missing from the specification")
    return require_non_negative(key, float(source[key]))


def knot_allowance(
    square_knots: float,
    half_hitches: float,
    diameter: float,
    multiplier: float,
) -> float:
    return (square_knots + half_hitches) * diameter * multiplier


def finished_strand(
    knot_length: float,
    drop: float,
    fringe: float,
) -> float:
    return knot_length + drop + fringe


def cut(
    pattern: Pattern,
    cord: Cord,
) -> float:
    knots = knot_allowance(
        read_measure(pattern, "square_knots"),
        read_measure(pattern, "half_hitches"),
        read_measure(cord, "diameter"),
        read_measure(cord, "multiplier"),
    )
    finished = finished_strand(
        knots,
        read_measure(pattern, "drop"),
        read_measure(pattern, "fringe"),
    )
    return finished * 2


def total_cord(
    cut_length: float,
    strands: int,
) -> float:
    return cut_length * require_non_negative("strands", strands)


def format_report(
    title: str,
    cut_length: float,
    strands: int,
) -> str:
    bulk = total_cord(cut_length, strands)
    return (
        f"{title}\n"
        f"  cut each strand at: {cut_length:.1f} cm\n"
        f"  strands on dowel:   {strands}\n"
        f"  cord to buy:        {bulk / 100:.2f} m"
    )


def main() -> None:
    pattern: Pattern = {
        "square_knots": 50,
        "half_hitches": 0,
        "drop": 20,
        "fringe": 10,
    }
    cord: Cord = {"diameter": 4, "multiplier": 3}
    strands = 24
    print(format_report("Wall hanging (chevron)", cut(pattern, cord), strands))


if __name__ == "__main__":
    main()

