import math
from dataclasses import dataclass

GRAVITY = 9.81
ANGLE_INCREMENT = 5.0
CURVE_SPAN_DEGREES = 90.0


@dataclass
class Sled:
    velocity: float
    mass: float


@dataclass
class Curve:
    radius: float
    friction: float


def validate_curve(
    curve: Curve,
) -> None:
    if curve.radius <= 0.0:
        raise ValueError("curve radius must be positive")
    if not 0.0 <= curve.friction < 1.0:
        raise ValueError("friction coefficient must lie in [0, 1)")


def validate_sled(
    sled: Sled,
) -> None:
    if sled.mass <= 0.0:
        raise ValueError("sled mass must be positive")
    if sled.velocity < 0.0:
        raise ValueError("entry velocity cannot be negative")


def centrifugal_force(
    mass: float,
    velocity: float,
    radius: float,
) -> float:
    return mass * velocity * velocity / radius


def minimum_banking_angle(
    force: float,
    mass: float,
    friction: float,
) -> float:
    weight = mass * GRAVITY
    numerator = force - friction * weight
    denominator = weight + friction * force
    return math.degrees(math.atan2(max(numerator, 0.0), denominator))


def buildable_angle(
    angle: float,
    increment: float = ANGLE_INCREMENT,
) -> float:
    return math.ceil(angle / increment) * increment


def arc_length(
    radius: float,
    span_degrees: float = CURVE_SPAN_DEGREES,
) -> float:
    return radius * math.radians(span_degrees)


def safe_exit_velocity(
    velocity: float,
    curve: Curve,
) -> float:
    loss = 2.0 * curve.friction * GRAVITY * arc_length(curve.radius)
    return math.sqrt(max(velocity * velocity - loss, 0.0))


def bank(
    sled: Sled,
    curve: Curve,
) -> tuple[float, int]:
    validate_sled(sled)
    validate_curve(curve)
    force = centrifugal_force(sled.mass, sled.velocity, curve.radius)
    required = minimum_banking_angle(force, sled.mass, curve.friction)
    return buildable_angle(required), math.floor(safe_exit_velocity(sled.velocity, curve))


def format_report(
    sled: Sled,
    curve: Curve,
    angle: float,
    exit_velocity: int,
) -> str:
    lines = [
        f"entry velocity : {sled.velocity:.1f} m/s",
        f"sled mass      : {sled.mass:.1f} kg",
        f"curve radius   : {curve.radius:.1f} m",
        f"ice friction   : {curve.friction:.3f}",
        f"banking angle  : {angle:.0f} deg",
        f"exit velocity  : {exit_velocity} m/s",
    ]
    return "\n".join(lines)


def main() -> None:
    sled = Sled(velocity=30.0, mass=200.0)
    curve = Curve(radius=50.0, friction=0.05)
    angle, exit_velocity = bank(sled, curve)
    print(format_report(sled, curve, angle, exit_velocity))


if __name__ == "__main__":
    main()

