from __future__ import annotations


def ensure_sequence(
    throws: list[int],
) -> None:
    """Reject inputs that cannot describe a juggling pattern at all."""
    if not throws:
        raise ValueError("a pattern needs at least one throw")
    for throw in throws:
        if throw < 0:
            raise ValueError(f"negative throw height: {throw}")


def object_count(
    throws: list[int],
) -> int | None:
    """Average of the throws, or None when the average is fractional."""
    total: int = sum(throws)
    if total % len(throws) != 0:
        return None
    return total // len(throws)


def landing_times(
    throws: list[int],
) -> list[int]:
    """Beat (modulo the period) on which each throw comes back down."""
    landings: list[int] = []
    for index, throw in enumerate(throws):
        landings.append((index + throw) % len(throws))
    return landings


def collisions(
    landings: list[int],
) -> list[int]:
    """Landing beats that are claimed by more than one throw."""
    seen: set[int] = set()
    clashes: list[int] = []
    for beat in landings:
        if beat in seen and beat not in clashes:
            clashes.append(beat)
        seen.add(beat)
    return clashes


def validate(
    throws: list[int],
) -> tuple[bool, int]:
    """Return whether the siteswap is valid and how many objects it needs."""
    ensure_sequence(throws)
    objects: int | None = object_count(throws)
    if objects is None:
        return False, 0
    if collisions(landing_times(throws)):
        return False, objects
    return True, objects


def format_report(
    throws: list[int],
    result: tuple[bool, int],
) -> str:
    pattern: str = "".join(str(throw) for throw in throws)
    valid, objects = result
    if valid:
        return f"{pattern}: valid pattern with {objects} object(s)"
    if objects == 0:
        return f"{pattern}: invalid, average throw height is not a whole number"
    clashing: list[int] = collisions(landing_times(throws))
    beats: str = ", ".join(str(beat) for beat in clashing)
    return f"{pattern}: invalid, mid-air collision on beat(s) {beats}"


def main() -> None:
    patterns: list[list[int]] = [
        [3],
        [5, 3, 1],
        [4, 4, 1],
        [3, 4, 5],
        [5, 5, 5, 0, 0],
        [4, 2, 3],
    ]
    for pattern in patterns:
        print(format_report(pattern, validate(pattern)))


if __name__ == "__main__":
    main()

