def validate_count(
    n: int,
) -> int:
    """Return n as a non-negative int, raising on invalid input."""
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError(f"n must be an int, got {type(n).__name__}")
    if n < 0:
        raise ValueError(f"n must be non-negative, got {n}")
    return n


def fibonacci_sequence(
    n: int,
) -> list[int]:
    """Return the first n Fibonacci numbers, starting with 0 and 1."""
    count = validate_count(n)
    numbers: list[int] = []
    current, following = 0, 1
    while len(numbers) < count:
        numbers.append(current)
        current, following = following, current + following
    return numbers


def nth_fibonacci(
    index: int,
) -> int:
    """Return the Fibonacci number at the given zero-based index."""
    position = validate_count(index)
    return fibonacci_sequence(position + 1)[-1]


def even_members(
    numbers: list[int],
) -> list[int]:
    """Return only the even values of the given sequence."""
    return [value for value in numbers if value % 2 == 0]


def format_sequence(
    numbers: list[int],
) -> str:
    """Render a sequence as a comma-separated string."""
    if not numbers:
        return "(empty)"
    return ", ".join(str(value) for value in numbers)


def describe(
    n: int,
) -> str:
    """Build a one-line report about the first n Fibonacci numbers."""
    numbers = fibonacci_sequence(n)
    evens = even_members(numbers)
    return (
        f"first {n}: [{format_sequence(numbers)}] "
        f"sum={sum(numbers)} evens=[{format_sequence(evens)}]"
    )


def main() -> None:
    for size in (1, 5, 10):
        print(describe(size))
    print(f"nth_fibonacci(30) -> {nth_fibonacci(30)}")


if __name__ == "__main__":
    main()

