def validate_year(
    year: int,
    label: str,
) -> int:
    """Return the year unchanged, or raise if it is not a usable year."""
    if not isinstance(year, int) or isinstance(year, bool):
        raise TypeError(f"{label} must be an integer, got {type(year).__name__}")
    if year < 0:
        raise ValueError(f"{label} must not be negative, got {year}")
    return year


def calculate_age(
    birth_year: int,
    current_year: int,
) -> int:
    """Return the age of a person born in birth_year as of current_year."""
    birth = validate_year(birth_year, "birth_year")
    current = validate_year(current_year, "current_year")
    if birth > current:
        raise ValueError(f"birth_year {birth} is after current_year {current}")
    return current - birth


def parse_record(
    line: str,
) -> tuple[str, int]:
    """Parse a 'name,birth_year' record into its two fields."""
    parts = [field.strip() for field in line.split(",")]
    if len(parts) != 2:
        raise ValueError(f"expected 'name,birth_year' but got {line!r}")
    name, raw_year = parts
    if not name:
        raise ValueError(f"missing name in record {line!r}")
    if not raw_year.isdigit():
        raise ValueError(f"invalid birth year {raw_year!r} in record {line!r}")
    return name, int(raw_year)


def ages_from_records(
    records: list[str],
    current_year: int,
) -> list[tuple[str, int]]:
    """Compute (name, age) pairs for every non-blank record."""
    result = []
    for line in records:
        if not line.strip():
            continue
        name, birth_year = parse_record(line)
        result.append((name, calculate_age(birth_year, current_year)))
    return result


