    records: list[str],
    current_year: int,
) -> str:
    """Produce a full text report of ages plus the group average."""
    pairs = ages_from_records(records, current_year)
    lines = [describe(name, age) for name, age in pairs]
    lines.append(f"Average age: {average_age(pairs):.1f}")
    return "\n".join(lines)


