import math


def circle_area(
    radius: float,
) -> float:
    """Return the area of a circle with the given radius."""
    validate_radius(radius)
    return math.pi * float(radius) * float(radius)


def validate_radius(
    radius: float,
) -> None:
    """Raise if the radius is not a usable non-negative real number."""
    if isinstance(radius, bool) or not isinstance(radius, (int, float)):
        raise TypeError("radius must be a real number, got %r" % (radius,))
    if math.isnan(radius) or math.isinf(radius):
        raise ValueError("radius must be finite, got %r" % (radius,))
    if radius < 0:
        raise ValueError("radius must be non-negative, got %r" % (radius,))


def circle_circumference(
    radius: float,
) -> float:
    """Return the circumference matching the same radius."""
    validate_radius(radius)
    return 2.0 * math.pi * float(radius)


def annulus_area(
    inner: float,
    outer: float,
) -> float:
    """Return the area of the ring between two concentric circles."""
    if outer < inner:
        raise ValueError("outer radius must not be smaller than inner radius")
    return circle_area(outer) - circle_area(inner)


def parse_radii(
    text: str,
) -> list[float]:
    """Read whitespace- or comma-separated radii from a line of text."""
    tokens = text.replace(",", " ").split()
    return [float(token) for token in tokens]


def format_row(
    radius: float,
) -> str:
    """Render one table row of area and circumference for a radius."""
    area = circle_area(radius)
    circumference = circle_circumference(radius)
    return "%8.3f %14.6f %14.6f" % (radius, area, circumference)


def report(
    radii: list[float],
) -> str:
    """Build a small table of areas and circumferences."""
    lines = ["%8s %14s %14s" % ("radius", "area", "circumference")]
    for radius in radii:
        lines.append(format_row(radius))
    return "\n".join(lines)


def main() -> int:
    radii = parse_radii("0, 1, 1.5, 2, 10")
    print(report(radii))
    print("circle_area(1) =", circle_area(1))
    print("circle_area(0) =", circle_area(0))
    print("ring 1..2 area =", annulus_area(1, 2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

