MONTH_LENGTHS = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)


def is_leap_year(
    year: int,
) -> bool:
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def days_in_month(
    year: int,
    month: int,
) -> int:
    if month == 2 and is_leap_year(year):
        return 29
    return MONTH_LENGTHS[month - 1]


def validate_date(
    year: int,
    month: int,
    day: int,
) -> None:
    if not 1 <= month <= 12:
        raise ValueError(f"month out of range: {month}")
    limit = days_in_month(year, month)
    if not 1 <= day <= limit:
        raise ValueError(f"day out of range for {year}-{month}: {day}")


def format_date(
    year: int,
    month: int,
    day: int,
) -> str:
    validate_date(year, month, day)
    return f"{year:04d}-{month:02d}-{day:02d}"


def parse_date(
    text: str,
) -> tuple[int, int, int]:
    parts = text.strip().split("-")
    if len(parts) != 3:
        raise ValueError(f"expected YYYY-MM-DD, got {text!r}")
    year, month, day = (int(part) for part in parts)
    validate_date(year, month, day)
    return year, month, day


def day_of_year(
    year: int,
    month: int,
    day: int,
) -> int:
    validate_date(year, month, day)
    total = day
    for earlier in range(1, month):
        total += days_in_month(year, earlier)
    return total


def describe(
    year: int,
    month: int,
    day: int,
) -> str:
    stamp = format_date(year, month, day)
    ordinal = day_of_year(year, month, day)
    return f"{stamp} is day {ordinal:>3} of {year}"


def report(
    dates: list[tuple[int, int, int]],
) -> str:
    return "\n".join(describe(*date) for date in dates)


def main() -> None:
    print(report([(2023, 7, 15), (2020, 1, 1), (2024, 2, 29), (1999, 12, 31)]))
    roundtrip = parse_date("2023-07-15")
    print(f"parsed {roundtrip} back into {format_date(*roundtrip)}")


if __name__ == "__main__":
    main()

