def normalize_name(
    item_name: str,
) -> str:
    cleaned = item_name.strip().lower()
    if not cleaned:
        raise ValueError("item name must not be blank")
    return cleaned


def update_inventory(
    inventory: dict[str, int],
    item_name: str,
    quantity: int,
) -> dict[str, int]:
    key = normalize_name(item_name)
    updated = dict(inventory)
    updated[key] = updated.get(key, 0) + quantity
    if updated[key] < 0:
        raise ValueError("stock for %s cannot fall below zero" % key)
    return updated


def apply_transactions(
    inventory: dict[str, int],
    transactions: list[tuple[str, int]],
) -> dict[str, int]:
    current = dict(inventory)
    for name, amount in transactions:
        current = update_inventory(current, name, amount)
    return current


def total_units(
    inventory: dict[str, int],
) -> int:
    return sum(inventory.values())


def low_stock(
    inventory: dict[str, int],
    threshold: int,
) -> list[str]:
    return sorted(name for name, count in inventory.items() if count < threshold)


def format_inventory(
    inventory: dict[str, int],
) -> str:
    width = max((len(name) for name in inventory), default=0)
    lines = []
    for name in sorted(inventory):
        lines.append("%-*s %5d" % (width, name, inventory[name]))
    return "\n".join(lines)


def build_report(
    inventory: dict[str, int],
    threshold: int,
) -> str:
    summary = "total units: %d" % total_units(inventory)
    warnings = low_stock(inventory, threshold)
    if warnings:
        summary += "\nreorder: " + ", ".join(warnings)
    return format_inventory(inventory) + "\n" + summary


def main() -> None:
    start = {'apple': 10}
    print(update_inventory(start, 'apple', 5))
    print(update_inventory(start, 'banana', 3))
    deliveries = [('Apple', 12), ('banana', 20), ('cherry', 4), ('apple', -6)]
    stock = apply_transactions(start, deliveries)
    print(build_report(stock, 8))


if __name__ == "__main__":
    main()

