def validate_count(
    n: int,
) -> int:
    """Return n as a non-negative int, rejecting bad input."""
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError(f"expected an integer, got {type(n).__name__}")
    if n < 0:
        raise ValueError(f"expected a non-negative integer, got {n}")
    return n


def list_of_squares(
    n: int,
) -> list[int]:
    """Squares of 1..n inclusive; an empty list when n is 0."""
    count: int = validate_count(n)
    return [i * i for i in range(1, count + 1)]


def sum_of_squares(
    n: int,
) -> int:
    """Total of the first n squares."""
    return sum(list_of_squares(n))


def digit_widths(
    squares: list[int],
) -> list[int]:
    """Number of decimal digits of each square, used for column alignment."""
