from collections.abc import Iterable
import sys


def ensure_text(
    value: object,
    label: str,
) -> str:
    """Return the value as a string, rejecting anything that is not text."""
    if not isinstance(value, str):
        raise TypeError(f"{label} must be a str, got {type(value).__name__}")
    return value


def tokenize(
    sentence: str,
) -> list[str]:
    """Split a sentence into words, discarding runs of whitespace."""
    return ensure_text(sentence, "sentence").split()


def reverse_words(
    sentence: str,
) -> str:
    """Reverse the order of the words in a sentence, keeping each word intact."""
    words = tokenize(sentence)
    words.reverse()
    return " ".join(words)


def word_count(
    sentence: str,
) -> int:
    """Count the words of a sentence."""
    return len(tokenize(sentence))


def longest_word(
    sentence: str,
) -> str:
    """Return the longest word, or the empty string when there is no word."""
    words = tokenize(sentence)
    if not words:
        return ""
    return max(words, key=len)


def describe(
    sentence: str,
) -> str:
    """Build a one-line report about a sentence and its reversed form."""
    parts = [
        f"original={sentence!r}",
        f"reversed={reverse_words(sentence)!r}",
        f"words={word_count(sentence)}",
        f"longest={longest_word(sentence)!r}",
    ]
    return ", ".join(parts)


def report_all(
    sentences: Iterable[str],
) -> str:
    """Describe every sentence of an iterable, one report per line."""
    return "\n".join(describe(sentence) for sentence in sentences)


def main(
    argv: list[str],
) -> int:
    """Reverse the sentences given as arguments, or those read from stdin."""
    sentences = argv[1:]
    if not sentences:
        sentences = [line.rstrip("\n") for line in sys.stdin]
    print(report_all(sentences))
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))

