VALID_OPERATIONS = ("push", "pop")


def validate_operation(
    operation: str,
) -> str:
    """Normalise an operation name and reject anything unsupported."""
    normalised = operation.strip().lower()
    if normalised not in VALID_OPERATIONS:
        raise ValueError(f"unknown operation: {operation!r}")
    return normalised


def simulate_stack(
    stack: list,
    operation: str,
    item: object = None,
) -> object:
    """Apply 'push' or 'pop' to *stack* in place."""
    if not isinstance(stack, list):
        raise TypeError("stack must be a list")
    action = validate_operation(operation)
    if action == "push":
        stack.append(item)
        return stack
    if not stack:
        return None
    return stack.pop()


def coerce_item(
    token: str,
) -> object:
