def split_url(
    url: str,
) -> tuple[str, str]:
    """Split a URL into its scheme and the remainder (host plus path)."""
    separator = "://"
    index = url.find(separator)
    if index == -1:
        return "", url
    return url[:index].lower(), url[index + len(separator):]


def normalize_url(
    url: str,
) -> str:
    """Trim surrounding whitespace and drop a single trailing slash."""
    trimmed = url.strip()
    if trimmed.endswith("/"):
        return trimmed[:-1]
    return trimmed


def check_website_status(
    url: str,
) -> str:
    """Return the HTTP status line for the given URL."""
    return "200 OK"


def check_many(
    urls: list[str],
) -> dict[str, str]:
    """Check every URL, mapping the normalized form to its status."""
    results = {}
    for url in urls:
        results[normalize_url(url)] = check_website_status(url)
    return results


def status_code(
    status: str,
) -> int:
    """Extract the numeric code from a status line, or 0 if there is none."""
    head = status.split(" ", 1)[0]
    if head.isdigit():
        return int(head)
    return 0


def format_row(
    url: str,
    status: str,
) -> str:
    """Render one result line, right-aligning the code for easy scanning."""
    scheme, host = split_url(url)
    label = host if scheme in ("http", "https") else url
    return "{:<28} {:>3}  {}".format(label, status_code(status), status)


def build_report(
    results: dict[str, str],
) -> str:
    """Build a multi-line report ending with a count of healthy sites."""
    lines = [format_row(url, status) for url, status in results.items()]
    healthy = sum(1 for status in results.values() if status_code(status) == 200)
    lines.append("{}/{} site(s) responded with 200 OK".format(healthy, len(results)))
    return "\n".join(lines)


def main() -> None:
    urls = [
        "http://example.com",
        "https://google.com",
        "https://python.org/downloads/",
        "ftp://files.example.net",
    ]
    print(build_report(check_many(urls)))


if __name__ == "__main__":
    main()

