def validate_channel(
    value: int,
    position: str,
) -> int:
    if not isinstance(value, int) or isinstance(value, bool):
        raise TypeError(f"channel at {position} must be an int")
    if not 0 <= value <= 255:
        raise ValueError(f"channel at {position} out of range 0..255: {value}")
    return value


def validate_pixel(
    pixel: list[int],
    row_index: int,
    col_index: int,
) -> list[int]:
    if len(pixel) != 3:
        raise ValueError(f"pixel at ({row_index}, {col_index}) needs exactly 3 channels")
    return [validate_channel(channel, f"({row_index}, {col_index}, {index})")
            for index, channel in enumerate(pixel)]


def validate_image(
    image_matrix: list[list[list[int]]],
) -> list[list[list[int]]]:
    width = len(image_matrix[0]) if image_matrix else 0
    checked = []
    for row_index, row in enumerate(image_matrix):
        if len(row) != width:
            raise ValueError(f"row {row_index} has width {len(row)}, expected {width}")
        checked.append([validate_pixel(pixel, row_index, col_index)
                        for col_index, pixel in enumerate(row)])
    return checked


def pixel_luminance(
    pixel: list[int],
) -> int:
    return sum(pixel) // len(pixel)


def to_grayscale(
    image_matrix: list[list[list[int]]],
) -> list[list[int]]:
    clean = validate_image(image_matrix)
    return [[pixel_luminance(pixel) for pixel in row] for row in clean]


def render_ascii(
    grayscale_image: list[list[int]],
    ramp: str = "@%#*+=-:. ",
) -> str:
    scale = len(ramp) - 1
    return "\n".join(
        "".join(ramp[value * scale // 255] for value in row)
        for row in grayscale_image
    )


def describe(
    image_matrix: list[list[list[int]]],
) -> str:
    gray = to_grayscale(image_matrix)
    values = [value for row in gray for value in row]
    if not values:
        return "empty image"
    size = f"{len(gray[0])}x{len(gray)}"
    return f"{size} image, gray range {min(values)}..{max(values)}\n{render_ascii(gray)}"


def main() -> None:
    print(to_grayscale([[[255, 0, 0], [0, 255, 0]]]))
    print(to_grayscale([[[10, 20, 30]]]))
    gradient = [[[step, step, step] for step in range(0, 256, 32)]] * 3
    print(describe(gradient))


if __name__ == "__main__":
    main()

