def merge_dicts(dict1: dict, dict2: dict) -> dict:
    """
    Merges two dictionaries. If a key exists in both, the value from the second dictionary overwrites the first.

    Args:
        dict1 (dict): The first dictionary.
        dict2 (dict): The second dictionary.

    Returns:
        dict: A new dictionary containing the merged items.
    """
    merged: dict = dict1.copy()
    for key, value in dict2.items():
        merged[key] = value
    return merged

def example_usage() -> None:
    dict_a: dict = {'a': 1, 'b': 2}
    dict_b: dict = {'b': 3, 'c': 4}
    result1: dict = merge_dicts(dict_a, dict_b)
    print(f"Example 1: {result1}")

    dict_x: dict = {'x': 10}
    dict_y: dict = {'y': 20}
    result2: dict = merge_dicts(dict_x, dict_y)
    print(f"Example 2: {result2}")

if __name__ == "__main__":
    example_usage()

