def validate_numbers(
    numbers: list[int],
) -> int:
    """Check the input and return the value of ``n`` it implies."""
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("numbers must be a list of integers")
    n: int = len(numbers) + 1
    seen: set[int] = set()
    for value in numbers:
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError(f"not an integer: {value!r}")
        if value < 1 or value > n:
            raise ValueError(f"value {value} outside the range 1..{n}")
        if value in seen:
            raise ValueError(f"duplicate value: {value}")
        seen.add(value)
    return n


def find_missing_number(
    numbers: list[int],
) -> int:
    """Return the single number from 1..n absent from ``numbers``."""
    n: int = validate_numbers(numbers)
    expected_total: int = n * (n + 1) // 2
    return expected_total - sum(numbers)


def describe(
    numbers: list[int],
) -> str:
    """Render one dataset together with its missing number."""
    missing: int = find_missing_number(numbers)
    shown: str = ", ".join(str(value) for value in numbers)
    return f"[{shown}] -> missing {missing}"


def report(
    datasets: list[list[int]],
) -> list[str]:
    """Describe every dataset, turning bad input into a readable line."""
    lines: list[str] = []
    for dataset in datasets:
        try:
            lines.append(describe(dataset))
        except (TypeError, ValueError) as error:
            lines.append(f"{dataset!r} -> invalid input: {error}")
    return lines


def main() -> None:
    datasets: list[list[int]] = [
        [1, 2, 4, 5],
        [1, 3],
        [2],
        [4, 1, 5, 3, 6, 2, 8],
        [1, 2, 2, 4],
    ]
