import re

EMAIL_PATTERN = re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}")


def extract_emails(
    text: str,
) -> list[str]:
    """Return every valid-looking email address found in ``text``, in order."""
    return [match.group(0) for match in EMAIL_PATTERN.finditer(text)]


def split_address(
    address: str,
) -> tuple[str, str]:
    """Return the (local part, lower-cased domain) pair of an address."""
    local, domain = address.split("@", 1)
    return local, domain.lower()


def normalize(
    address: str,
) -> str:
    """Rewrite an address so that domain comparisons are case-insensitive."""
    local, domain = split_address(address)
    return local + "@" + domain


def unique_emails(
    text: str,
) -> list[str]:
    """Extract addresses, dropping later duplicates that differ only in domain case."""
    seen = set()
    result = []
    for address in extract_emails(text):
        key = normalize(address)
        if key not in seen:
            seen.add(key)
            result.append(address)
    return result


def group_by_domain(
    text: str,
) -> dict[str, list[str]]:
    """Map each domain to the local parts of the addresses seen for it."""
    groups = {}
    for address in unique_emails(text):
        local, domain = split_address(address)
        groups.setdefault(domain, []).append(local)
    return groups


def format_report(
    text: str,
) -> str:
    """Render a short human-readable summary of the addresses in ``text``."""
    groups = group_by_domain(text)
    if not groups:
        return "No email addresses found."
    lines = []
    for domain in sorted(groups):
        locals_ = sorted(groups[domain], key=str.lower)
        joined = ", ".join(local + "@" + domain for local in locals_)
        lines.append("%s (%d): %s" % (domain, len(locals_), joined))
    return "\n".join(lines)


def main() -> None:
    samples = [
        "Contact us at info@example.com or support@test.org.",
        "No emails here.",
        "Write to Sales@Example.com, Sales@example.com or dev@example.com today.",
    ]
    for sample in samples:
        print(extract_emails(sample))
        print(format_report(sample))
        print("-" * 40)


if __name__ == "__main__":
    main()

