def encrypt_shift(
    text: str,
    shift: int
) -> str:
    encrypted_text: list[str] = []

    for char in text:
        if 'a' <= char <= 'z':
            start: int = ord('a')
            shifted_char_code: int = (ord(char) - start + shift) % 26 + start
            encrypted_text.append(chr(shifted_char_code))
        elif 'A' <= char <= 'Z':
            start: int = ord('A')
            shifted_char_code: int = (ord(char) - start + shift) % 26 + start
            encrypted_text.append(chr(shifted_char_code))
        else:
            encrypted_text.append(char)

    return "".join(encrypted_text)

