def longest_common_prefix(strings: list[str]) -> str:
    if not strings:
        return ""

    prefix: str = ""
    first_word: str = strings[0]

    for i in range(len(first_word)):
        char: str = first_word[i]
        for j in range(1, len(strings)):
            current_word: str = strings[j]
            if i >= len(current_word) or current_word[i] != char:
                return prefix
        prefix += char
    return prefix

