from typing import List, Sequence, Union

Number = Union[int, float]


def validate_inputs(data: Sequence[Number], window_size: int) -> None:
    """Reject inputs for which a moving average is undefined."""
    if not isinstance(window_size, int):
        raise TypeError("window_size must be an integer")
    if window_size <= 0:
        raise ValueError("window_size must be positive")
    for index, value in enumerate(data):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(f"data[{index}] is not a number: {value!r}")
    if window_size > len(data):
        raise ValueError("window_size cannot exceed the number of data points")


def calculate_sma(data: List[Number], window_size: int) -> List[float]:
    """Simple moving average of `data` over a sliding window."""
    validate_inputs(data, window_size)
    window_total = float(sum(data[:window_size]))
    averages = [window_total / window_size]
    for position in range(window_size, len(data)):
        window_total += data[position] - data[position - window_size]
        averages.append(window_total / window_size)
    return averages


def format_value(value: float, decimals: int) -> str:
    return f"{value:.{decimals}f}"


def format_series(values: Sequence[float], decimals: int) -> str:
    return "[" + ", ".join(format_value(v, decimals) for v in values) + "]"


def trend_of(averages: Sequence[float]) -> str:
    """Describe whether the averaged series rises, falls or stays flat."""
    if len(averages) < 2:
        return "flat"
    first = averages[0]
    last = averages[-1]
    if last > first:
        return "rising"
    if last < first:
        return "falling"
    return "flat"


def sma_report(label: str, data: List[Number], window_size: int) -> str:
    averages = calculate_sma(data, window_size)
    return (
        f"{label}: window={window_size} "
        f"sma={format_series(averages, 2)} trend={trend_of(averages)}"
    )


def main() -> int:
    samples = [
        ("series A", [1, 2, 3, 4, 5], 3),
        ("series B", [10, 20, 30, 40], 2),
        ("prices", [12.5, 11.0, 13.25, 12.75, 10.5, 9.0], 4),
    ]
    for label, data, window_size in samples:
        print(sma_report(label, data, window_size))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

