from __future__ import annotations

import sys
from datetime import date


def validate_date(
    year: int,
    month: int,
    day: int,
) -> date:
    """Build a date object, rejecting impossible or future dates."""
    if not (1 <= month <= 12):
        raise ValueError(f"month out of range: {month}")
    try:
        parsed = date(year, month, day)
    except ValueError as exc:
        raise ValueError(f"invalid date {year}-{month}-{day}: {exc}") from None
    if parsed > date.today():
        raise ValueError(f"date {parsed.isoformat()} is in the future")
    return parsed


def days_since(
    year: int,
    month: int,
    day: int,
) -> int:
    """Number of full days that have passed since the given past date."""
    start = validate_date(year, month, day)
    return (date.today() - start).days


def split_into_weeks(
    total_days: int,
) -> tuple[int, int]:
    """Split a day count into whole weeks plus leftover days."""
    weeks = total_days // 7
    return weeks, total_days - weeks * 7


def parse_date_string(
    text: str,
) -> tuple[int, int, int]:
    """Parse 'YYYY-MM-DD' into its three integer components."""
    parts = text.split("-")
    if len(parts) != 3:
        raise ValueError(f"expected YYYY-MM-DD, got {text!r}")
    try:
        numbers = [int(part) for part in parts]
    except ValueError:
        raise ValueError(f"non-numeric component in {text!r}") from None
    return numbers[0], numbers[1], numbers[2]


def pluralize(
    count: int,
    noun: str,
) -> str:
    return f"{count} {noun}" if count == 1 else f"{count} {noun}s"


def describe(
    year: int,
    month: int,
    day: int,
) -> str:
    """Human readable report for a single date."""
    total = days_since(year, month, day)
    weeks, leftover = split_into_weeks(total)
    label = date(year, month, day).isoformat()
    if weeks == 0:
        return f"{label}: {pluralize(total, 'day')} ago"
    return (
        f"{label}: {pluralize(total, 'day')} ago "
        f"({pluralize(weeks, 'week')} and {pluralize(leftover, 'day')})"
    )


def main(
    argv: list[str],
) -> int:
    if not argv:
        print("usage: days_since.py YYYY-MM-DD [YYYY-MM-DD ...]", file=sys.stderr)
        return 2
    status = 0
    for argument in argv:
        try:
            year, month, day = parse_date_string(argument)
            print(describe(year, month, day))
        except ValueError as exc:
            print(f"error: {exc}", file=sys.stderr)
            status = 1
    return status


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

