def normalize(
    text: str,
) -> str:
    """Return the lowercase, alphanumeric-only form of *text*."""
    return "".join(ch.lower() for ch in text if ch.isalnum())


def first_mismatch(
    cleaned: str,
    reversed_text: str,
) -> int:
    """Index of the first position where the two strings differ, or -1."""
    for i, (a, b) in enumerate(zip(cleaned, reversed_text)):
        if a != b:
            return i
    return -1


def is_palindrome_string(
    s: str,
) -> bool:
    """True if *s* reads the same forwards and backwards, ignoring case
    and non-alphanumeric characters."""
    cleaned = normalize(s)
    return first_mismatch(cleaned, cleaned[::-1]) < 0


def describe(
    phrase: str,
    cleaned: str,
    index: int,
) -> str:
    """One-line verdict for *phrase*, given its normalized form and the
    index of its first mismatch (-1 when there is none)."""
    if index < 0:
        return "{0!r}: palindrome ({1} significant chars)".format(phrase, len(cleaned))
    return "{0!r}: not a palindrome (differs at position {1})".format(phrase, index)


def summarize(
    total: int,
    hits: int,
) -> str:
    """Closing line counting how many of *total* phrases were palindromes."""
    return "{0} of {1} phrases are palindromes".format(hits, total)


def report(
    phrases: list[str],
    title: str,
) -> list[str]:
    """Titled report with a verdict per phrase and a closing summary."""
    lines = [title]
    hits = 0
    for phrase in phrases:
        cleaned = normalize(phrase)
        index = first_mismatch(cleaned, cleaned[::-1])
        if index < 0:
            hits += 1
        lines.append(describe(phrase, cleaned, index))
    lines.append(summarize(len(phrases), hits))
    return lines


def main() -> None:
    samples = [
        "Racecar",
        "A man, a plan, a canal: Panama",
        "No 'x' in Nixon",
        "hello world",
        "Was it a car or a cat I saw?",
        "",
    ]
    for line in report(samples, "Palindrome check"):
        print(line)


if __name__ == "__main__":
    main()

