HEX_DIGITS: str = "0123456789abcdefABCDEF"


def is_valid_hex_color(
    code: str,
) -> bool:
    if not isinstance(code, str):
        return False
    if not code.startswith("#"):
        return False
    body: str = code[1:]
    if len(body) not in (3, 6):
        return False
    return all(ch in HEX_DIGITS for ch in body)


def normalize_hex_color(
    code: str,
) -> str:
    if not is_valid_hex_color(code):
        raise ValueError("not a valid hex color: %r" % (code,))
    body: str = code[1:]
    if len(body) == 3:
        body = "".join(ch * 2 for ch in body)
    return "#" + body.upper()


def hex_to_rgb(
    code: str,
) -> tuple[int, int, int]:
    full: str = normalize_hex_color(code)
    red: int = int(full[1:3], 16)
    green: int = int(full[3:5], 16)
    blue: int = int(full[5:7], 16)
    return red, green, blue


def channel_luminance(
    value: int,
) -> float:
    scaled: float = value / 255.0
    if scaled <= 0.03928:
        return scaled / 12.92
    return ((scaled + 0.055) / 1.055) ** 2.4


def relative_luminance(
    code: str,
) -> float:
    red, green, blue = hex_to_rgb(code)
    return (
        0.2126 * channel_luminance(red)
        + 0.7152 * channel_luminance(green)
        + 0.0722 * channel_luminance(blue)
    )


def readable_text_color(
    code: str,
) -> str:
    return "#000000" if relative_luminance(code) > 0.179 else "#FFFFFF"


def describe(
    code: str,
) -> str:
    if not is_valid_hex_color(code):
        return "%-10s invalid" % (code,)
    rgb: tuple[int, int, int] = hex_to_rgb(code)
    return "%-10s valid  %s  rgb%s  text=%s" % (
        code,
        normalize_hex_color(code),
        rgb,
        readable_text_color(code),
    )


def main() -> None:
    samples: list[str] = ["#ABC", "#123456", "#GGGGGG", "#fff", "123456", "#0d1b2a"]
    for sample in samples:
        print(describe(sample))


if __name__ == "__main__":
    main()

