from string import ascii_lowercase


ALPHABET: set[str] = set(ascii_lowercase)


def letters_used(
    text: str,
) -> set[str]:
    """Return the set of distinct lowercase letters appearing in text."""
    return {char.lower() for char in text if char.lower() in ALPHABET}


def is_pangram(
    text: str,
) -> bool:
    """Return True when text contains every letter of the English alphabet."""
    return ALPHABET <= letters_used(text)


def missing_letters(
    text: str,
) -> list[str]:
    """Return the alphabet letters absent from text, in alphabetical order."""
    return sorted(ALPHABET - letters_used(text))


def coverage_ratio(
    text: str,
) -> float:
    """Return the fraction of the alphabet covered by text, from 0.0 to 1.0."""
    return len(letters_used(text)) / len(ALPHABET)


def letter_counts(
    text: str,
) -> dict[str, int]:
    """Count how often each alphabet letter occurs in text."""
    counts: dict[str, int] = {letter: 0 for letter in ascii_lowercase}
    for char in text:
        lowered: str = char.lower()
        if lowered in counts:
            counts[lowered] += 1
    return counts


def rarest_present_letter(
    text: str,
) -> str:
    """Return the least frequent letter that still occurs in text."""
    counts: dict[str, int] = letter_counts(text)
    present: list[str] = [letter for letter, total in counts.items() if total > 0]
    if not present:
        raise ValueError("text contains no alphabetic characters")
    return min(present, key=lambda letter: (counts[letter], letter))


def format_report(
    text: str,
) -> str:
    """Build a short human readable summary for a single phrase."""
    verdict: str = "pangram" if is_pangram(text) else "not a pangram"
    percent: float = coverage_ratio(text) * 100
    lines: list[str] = [f'"{text}" is {verdict} ({percent:.1f}% of the alphabet).']
    absent: list[str] = missing_letters(text)
    if absent:
        lines.append("  missing: " + ", ".join(absent))
    else:
        lines.append(f"  rarest letter used: {rarest_present_letter(text)}")
    return "\n".join(lines)


def report_all(
    phrases: list[str],
) -> str:
    """Join the reports of several phrases into a single block of text."""
    return "\n".join(format_report(phrase) for phrase in phrases)


if __name__ == "__main__":
    samples: list[str] = [
        "The quick brown fox jumps over the lazy dog.",
        "Hello World",
        "Pack my box with five dozen liquor jugs!",
        "Sphinx of black quartz, judge my vow",
    ]
    print(report_all(samples))
    pangram_count: int = sum(1 for phrase in samples if is_pangram(phrase))
    print(f"{pangram_count} of {len(samples)} phrases are pangrams.")

