def rarest_present_letter(
    text,
):
    """Return the least frequent letter that still occurs in text."""
    counts = letter_counts(text)
    present = [letter for letter, total in counts.items() if total > 0]
    if not present:
        raise ValueError("text contains no alphabetic characters")
    return min(present, key=lambda letter: (counts[letter], letter))


def format_report(
    text,
):
    """Build a short human readable summary for a single phrase."""
    verdict = "pangram" if is_pangram(text) else "not a pangram"
    percent = coverage_ratio(text) * 100
    lines = [f'"{text}" is {verdict} ({percent:.1f}% of the alphabet).']
    absent = missing_letters(text)
    if absent:
        lines.append("  missing: " + ", ".join(absent))
    else:
        lines.append(f"  rarest letter used: {rarest_present_letter(text)}")
    return "\n".join(lines)


def report_all(
    phrases,
):
    """Join the reports of several phrases into a single block of text."""
    return "\n".join(format_report(phrase) for phrase in phrases)


if __name__ == "__main__":
    samples = [
        "The quick brown fox jumps over the lazy dog.",
        "Hello World",
        "Pack my box with five dozen liquor jugs!",
        "Sphinx of black quartz, judge my vow",
    ]
    print(report_all(samples))
    pangram_count = sum(1 for phrase in samples if is_pangram(phrase))
    print(f"{pangram_count} of {len(samples)} phrases are pangrams.")

