def validate_binary(
    text: str,
) -> str:
    """Return the stripped binary string, raising ValueError if it is malformed."""
    candidate = text.strip()
    if not candidate:
        raise ValueError("binary string must contain at least one digit")
    for index, digit in enumerate(candidate):
        if digit not in "01":
            raise ValueError(f"invalid digit {digit!r} at position {index}")
    return candidate


def binary_to_gray(
    binary: str,
) -> str:
    """Convert a binary string into the equivalent Gray code string."""
    bits = validate_binary(binary)
    gray = [bits[0]]
    for previous, current in zip(bits, bits[1:]):
        gray.append("1" if previous != current else "0")
    return "".join(gray)


def gray_to_binary(
    gray: str,
) -> str:
    """Invert the Gray code encoding, recovering the original binary string."""
    code = validate_binary(gray)
    bits = [code[0]]
    for digit in code[1:]:
        bits.append("1" if bits[-1] != digit else "0")
    return "".join(bits)


def to_int(
    binary: str,
) -> int:
    """Interpret a binary string as a non-negative integer."""
    return int(validate_binary(binary), 2)


def gray_sequence(
    width: int,
) -> list[str]:
    """List every Gray code of the given bit width in counting order."""
    if width < 1:
        raise ValueError("width must be positive")
    return [binary_to_gray(format(value, f"0{width}b")) for value in range(2 ** width)]


def format_row(
    binary: str,
) -> str:
    """Render one table row with a binary value, its Gray code and its integer value."""
    return f"{binary:>8} {binary_to_gray(binary):>8} {to_int(binary):>5}"


def format_table(
    values: list[str],
) -> str:
    """Build a text table for the given binary strings, with a header line."""
    header = f"{'binary':>8} {'gray':>8} {'value':>5}"
    return "\n".join([header] + [format_row(value) for value in values])


def main(
    samples: list[str],
) -> int:
    print(format_table(samples))
    for sample in samples:
        encoded = binary_to_gray(sample)
        print(f"{sample} -> {encoded} -> {gray_to_binary(encoded)}")
    codes = gray_sequence(3)
    print("3-bit Gray sequence:", " ".join(codes))
    changes = sum(
        1
        for left, right in zip(codes, codes[1:])
        if sum(a != b for a, b in zip(left, right)) == 1
    )
    print(f"adjacent single-bit transitions: {changes}/{len(codes) - 1}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(["000", "1011", "11110", "1"]))

